insert into public.exams (id, slug, name, description, is_active) values ('a1000000-0000-4000-8000-000000000001', 'plab1', 'PLAB 1', 'PLAB 1 single best answer study bank (PLABoratory).', true) on conflict (slug) do update set name = excluded.name, is_active = true;
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('045896fa-5431-5d76-94cc-e08c897ed08c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 19 year old woman presents to the Emergency Department saying she took 40 paracetamol 500 mg tablets in one go about 10 hours ago after an argument. She weighs 60 kg and feels nauseated but is otherwise well. Bloods, including a paracetamol level, have just been sent and results will take about 1 hour. What is the SINGLE most appropriate immediate management?', 'She has taken 20 g, about 333 mg/kg, a potentially toxic dose, and presents 8 to 24 hours after ingestion. In this window, acetylcysteine should be started immediately without waiting for the level, because delaying treatment beyond 8 hours greatly increases the risk of liver injury. Treatment can be stopped later if the level and bloods allow. Activated charcoal is only useful within 1 hour of ingestion. A psychiatric assessment is needed once she is medically fit.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e3907efe-cdf6-5fb2-855b-f619c8a49340', '045896fa-5431-5d76-94cc-e08c897ed08c', 'A', 'Refer immediately to a liver transplant unit', false, 0),
  ('6a9720e9-4bee-59cd-b2c4-c538da6f1d6b', '045896fa-5431-5d76-94cc-e08c897ed08c', 'B', 'Give activated charcoal', false, 1),
  ('f86314a5-52c5-5ed0-b679-ab33eb0b6013', '045896fa-5431-5d76-94cc-e08c897ed08c', 'C', 'Start IV acetylcysteine immediately', true, 2),
  ('6058ebfe-76c9-54be-87bd-623a880f599b', '045896fa-5431-5d76-94cc-e08c897ed08c', 'D', 'Give oral methionine', false, 3),
  ('59c1db72-dee1-58d5-8340-47258a86ee79', '045896fa-5431-5d76-94cc-e08c897ed08c', 'E', 'Wait for the paracetamol level before treating', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('64819622-e817-51c1-a42f-d4f1cf28aaaf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 26 year old man develops sudden facial swelling, a widespread urticarial rash, stridor and wheeze minutes after eating a dish containing peanuts at a restaurant. On arrival in the Emergency Department his blood pressure is 82/50 mmHg and heart rate 130 beats/minute. What is the SINGLE most appropriate first drug to give?', 'This is anaphylaxis with airway and circulatory compromise. The first drug is IM adrenaline 0.5 mg (0.5 mL of 1 mg/mL) into the anterolateral thigh in adults, repeated after 5 minutes if there is no improvement. IV adrenaline 1 mg is the cardiac arrest dose and must not be given to a patient with a pulse. Antihistamines and steroids are not first-line in the Resuscitation Council UK guideline, and the subcutaneous route is absorbed less reliably.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('def8b997-c114-58b7-b492-087cff0df5c6', '64819622-e817-51c1-a42f-d4f1cf28aaaf', 'A', 'Adrenaline 0.5 mg (500 micrograms) intramuscularly, 1 mg/mL (1:1000)', true, 0),
  ('4cf27623-c628-5472-b080-bf2eb95a0b8d', '64819622-e817-51c1-a42f-d4f1cf28aaaf', 'B', 'Adrenaline 1 mg intravenously, 1:10,000', false, 1),
  ('874e4446-c7f8-5bed-b1cf-0de501b9f85a', '64819622-e817-51c1-a42f-d4f1cf28aaaf', 'C', 'Chlorphenamine 10 mg intramuscularly', false, 2),
  ('89d0f2ea-a6d3-59ad-9e96-b3d88c108293', '64819622-e817-51c1-a42f-d4f1cf28aaaf', 'D', 'Adrenaline 0.5 mg subcutaneously', false, 3),
  ('dc9e20e3-27c6-5963-9d9d-31d6c99acb48', '64819622-e817-51c1-a42f-d4f1cf28aaaf', 'E', 'Hydrocortisone 200 mg intravenously', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('96b43db2-bd09-5c8c-9bcf-310127d2b6fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 31 year old man is brought to the Emergency Department after a motorbike collision with an obvious open fracture of the tibia that has bled heavily at the scene. He weighs about 70 kg. Heart rate is 115 beats/minute, blood pressure 122/90 mmHg, respiratory rate 24 breaths/minute and capillary refill 3 seconds. He is anxious but orientated. What is his estimated blood loss?', 'This fits ATLS class II haemorrhage: heart rate 100-120, normal systolic blood pressure with a narrowed pulse pressure, respiratory rate 20-30 and mild anxiety. That corresponds to losing 15-30% of circulating volume, about 750-1500 mL in a 70 kg adult. Class III (30-40%, 1500-2000 mL) causes a fall in systolic BP, HR 120-140 and confusion. Class IV (over 40%, more than 2000 mL) causes marked hypotension and lethargy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8085d001-82b1-574f-8289-ec1212729639', '96b43db2-bd09-5c8c-9bcf-310127d2b6fe', 'A', 'Less than 750 mL', false, 0),
  ('7926438c-a6b8-57eb-a8b2-176e1a861525', '96b43db2-bd09-5c8c-9bcf-310127d2b6fe', 'B', '750-1500 mL', true, 1),
  ('34fcbd7a-4a18-592f-bf41-ea9beb04a3b7', '96b43db2-bd09-5c8c-9bcf-310127d2b6fe', 'C', '1500-2000 mL', false, 2),
  ('a0c16b19-1fa1-5e96-bd67-f19cab7370f9', '96b43db2-bd09-5c8c-9bcf-310127d2b6fe', 'D', '2000-3000 mL', false, 3),
  ('129e636b-8fec-56b4-bea2-29d71489cb00', '96b43db2-bd09-5c8c-9bcf-310127d2b6fe', 'E', 'More than 3000 mL', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b4a4bf8a-011d-5af5-8826-ab7ac514e4a0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 66 year old man with chronic kidney disease stage 4 presents feeling generally weak. His serum potassium is 7.1 mmol/L. An ECG shows tall tented T waves and widened QRS complexes. He is haemodynamically stable. What is the SINGLE most appropriate immediate treatment?', 'With severe hyperkalaemia and ECG changes, the first priority is protecting the heart. IV calcium (30 mL of 10% calcium gluconate or 10 mL of 10% calcium chloride) stabilises the myocardium within minutes but does not lower potassium. Insulin-glucose and salbutamol then shift potassium into cells. Binders and dialysis remove potassium from the body. ECGs should be repeated and the calcium dose repeated if the changes persist.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5782a5b-51e0-548a-9243-61ee00e93be5', 'b4a4bf8a-011d-5af5-8826-ab7ac514e4a0', 'A', 'IV calcium gluconate 10%', true, 0),
  ('bb33bd5d-f70c-56cb-987c-4b2eea9ac267', 'b4a4bf8a-011d-5af5-8826-ab7ac514e4a0', 'B', 'Oral calcium resonium', false, 1),
  ('cbc78a9c-59d8-542a-9eef-718c9a6b4670', 'b4a4bf8a-011d-5af5-8826-ab7ac514e4a0', 'C', 'Nebulised salbutamol', false, 2),
  ('ad715627-25bb-50e1-956b-f96949c405b8', 'b4a4bf8a-011d-5af5-8826-ab7ac514e4a0', 'D', 'IV insulin and glucose', false, 3),
  ('7e78b621-a02f-5fe0-a5ad-da343fdb5ef4', 'b4a4bf8a-011d-5af5-8826-ab7ac514e4a0', 'E', 'Emergency haemodialysis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2b0d6a0a-802b-5265-83bd-7a9f0ec0731f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 24 year old man is brought to the Emergency Department after being stabbed in the right side of his chest. He is extremely breathless and agitated. His heart rate is 136 beats/minute, blood pressure 78/44 mmHg and oxygen saturation 84% on high-flow oxygen. The trachea is deviated to the left, the right hemithorax is hyper-resonant and breath sounds are absent on the right. What is the SINGLE most appropriate immediate action?', 'This is a tension pneumothorax, a clinical diagnosis that must be treated before any imaging. Immediate decompression is needed: needle decompression in the 2nd intercostal space, midclavicular line, or the 4th/5th space anterior to the midaxillary line (ATLS now prefers the 4th/5th space in adults), or finger thoracostomy in trauma. A chest drain is then inserted. Pericardiocentesis is for cardiac tamponade, which causes muffled heart sounds and raised JVP without tracheal deviation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7544ff42-797c-56ab-93ed-c630e1d549a8', '2b0d6a0a-802b-5265-83bd-7a9f0ec0731f', 'A', 'Pericardiocentesis', false, 0),
  ('771c7f99-8202-5738-9f7c-2ffe15901c3d', '2b0d6a0a-802b-5265-83bd-7a9f0ec0731f', 'B', 'Urgent chest X-ray', false, 1),
  ('69bccab1-3ae8-51cd-98c1-8dc149fdf272', '2b0d6a0a-802b-5265-83bd-7a9f0ec0731f', 'C', 'CT scan of the chest', false, 2),
  ('1c818a72-1ba1-582c-8d84-7865039f5ef5', '2b0d6a0a-802b-5265-83bd-7a9f0ec0731f', 'D', 'Insert a right-sided chest drain after the chest X-ray', false, 3),
  ('209187fe-83bc-5ea2-add1-95c789d785ae', '2b0d6a0a-802b-5265-83bd-7a9f0ec0731f', 'E', 'Needle or finger thoracostomy on the right', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3fa42f9e-85dd-5d7b-b75d-9177997a0369', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 31 year old man is found collapsed in a public toilet. His respiratory rate is 6 breaths/minute, oxygen saturation 86% on air and GCS 7/15. His pupils are pinpoint and there are track marks on both forearms. A bag-valve-mask is being used to support his breathing. What is the SINGLE most appropriate drug treatment?', 'Pinpoint pupils, respiratory depression and reduced consciousness in a person who injects drugs indicate opioid toxicity. Give naloxone IV (or IM if there is no access) in titrated doses, repeated as needed. Its half-life is shorter than most opioids, so he needs observation and possibly an infusion. Flumazenil reverses benzodiazepines but can cause seizures and is not routinely used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('343a038d-2c5c-50be-8af3-f5334f243e4b', '3fa42f9e-85dd-5d7b-b75d-9177997a0369', 'A', 'IM adrenaline', false, 0),
  ('f5c7ced4-8188-5f4a-a2f1-588cdc1c4919', '3fa42f9e-85dd-5d7b-b75d-9177997a0369', 'B', 'IV flumazenil', false, 1),
  ('5029c92b-0799-5f3a-9625-edc43f6be04e', '3fa42f9e-85dd-5d7b-b75d-9177997a0369', 'C', 'IV glucose', false, 2),
  ('66db9980-a9fe-57fb-9663-e429f3d6cdff', '3fa42f9e-85dd-5d7b-b75d-9177997a0369', 'D', 'IV naloxone', true, 3),
  ('80482c2f-5853-5963-a61d-ca4fbdc10e37', '3fa42f9e-85dd-5d7b-b75d-9177997a0369', 'E', 'IV atropine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f3deff16-973f-5213-885a-4fe35c9bece4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 68 year old woman on warfarin for atrial fibrillation is brought to the Emergency Department after slipping on ice and hitting her head 2 hours ago. She did not lose consciousness and has no vomiting, amnesia or neurological deficit. Her GCS is 15/15. What is the SINGLE most appropriate investigation?', 'NICE head injury guidance (NG232) recommends a CT head within 8 hours of injury for people on anticoagulants (such as warfarin or DOACs) who have had a head injury, even with no other indications. A CT is needed within 1 hour if there is GCS below 13 on arrival, GCS below 15 at 2 hours, suspected skull fracture, a post-traumatic seizure, a focal deficit or more than one episode of vomiting. Skull X-rays are not used for this.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9fbc41a8-e733-5b23-9783-d2fbe9f4515b', 'f3deff16-973f-5213-885a-4fe35c9bece4', 'A', 'CT scan of the head within 8 hours', true, 0),
  ('26347505-eb7b-5ca4-be38-51deb1a06302', 'f3deff16-973f-5213-885a-4fe35c9bece4', 'B', 'No imaging needed; discharge with head injury advice', false, 1),
  ('181d7fa9-e91e-57da-a5eb-3a4ab7c94b07', 'f3deff16-973f-5213-885a-4fe35c9bece4', 'C', 'CT scan of the head only if her GCS falls', false, 2),
  ('89e2f0b6-aaca-596b-98a7-ca97aa1fa05e', 'f3deff16-973f-5213-885a-4fe35c9bece4', 'D', 'Skull X-ray', false, 3),
  ('25c1aa5d-a022-59a3-a388-88a3ddfa6a99', 'f3deff16-973f-5213-885a-4fe35c9bece4', 'E', 'MRI of the brain within 24 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('533896a5-0d37-59be-9eb7-6fb91f5cfaa5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A family of four is brought to the Emergency Department in winter. They all have headache, nausea and dizziness, and their symptoms improve when they are away from home. They use an old gas boiler. The father is now confused. His oxygen saturation on pulse oximetry is 99%. What is the SINGLE most appropriate immediate management?', 'These features suggest carbon monoxide poisoning. Pulse oximetry cannot tell carboxyhaemoglobin from oxyhaemoglobin, so saturations are falsely normal. Diagnosis is by a carboxyhaemoglobin level on a blood gas. Give high-flow 100% oxygen at once, which shortens the half-life of carboxyhaemoglobin. Hyperbaric oxygen is considered in severe cases (such as loss of consciousness or pregnancy) after discussion with a specialist. Hydroxocobalamin treats cyanide poisoning.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('570eda2f-bf1e-56c8-9f75-5a552c719f79', '533896a5-0d37-59be-9eb7-6fb91f5cfaa5', 'A', 'Reassure as the oxygen saturation is normal', false, 0),
  ('73482da7-b481-5b73-8374-5b045c953409', '533896a5-0d37-59be-9eb7-6fb91f5cfaa5', 'B', '100% oxygen via a non-rebreather mask', true, 1),
  ('1bc4a66c-bfce-58e6-a762-2bd70ed53737', '533896a5-0d37-59be-9eb7-6fb91f5cfaa5', 'C', 'Oral paracetamol and discharge', false, 2),
  ('b7279812-6c29-5f77-8286-df3c9276ec5d', '533896a5-0d37-59be-9eb7-6fb91f5cfaa5', 'D', 'Hyperbaric oxygen before any other treatment', false, 3),
  ('730d66c9-86fc-576e-ac64-059a152e209d', '533896a5-0d37-59be-9eb7-6fb91f5cfaa5', 'E', 'IV hydroxocobalamin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e098f09-f444-58e6-ad7c-bc4eccadc3c9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 72 year old man is admitted with confusion and fever. His temperature is 38.9°C, heart rate 118 beats/minute, blood pressure 86/50 mmHg and respiratory rate 26 breaths/minute. His NEWS2 score is 9. He has a productive cough with right basal crackles. What is the SINGLE most appropriate action within the first hour?', 'He has suspected sepsis with hypotension, likely from pneumonia. The ''Sepsis Six'' should be completed within 1 hour: give oxygen to target saturations, take blood cultures, give IV antibiotics, give an IV fluid bolus (500 mL crystalloid), measure lactate and monitor urine output. Delaying antibiotics in septic shock increases mortality. A chest X-ray is done but must not delay treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f5b1676d-4e7a-5c2f-b806-abaeeb4370a7', '2e098f09-f444-58e6-ad7c-bc4eccadc3c9', 'A', 'Wait for chest X-ray confirmation before giving antibiotics', false, 0),
  ('df7c508d-505f-56b4-887b-2fee9df05d58', '2e098f09-f444-58e6-ad7c-bc4eccadc3c9', 'B', 'Arrange urgent CT chest', false, 1),
  ('6f185441-8b20-5427-9a17-40d468cae489', '2e098f09-f444-58e6-ad7c-bc4eccadc3c9', 'C', 'Start oral amoxicillin and review in 4 hours', false, 2),
  ('c9bcebc3-36b9-5ec6-a268-4036c841e5af', '2e098f09-f444-58e6-ad7c-bc4eccadc3c9', 'D', 'Give IV fluids only and wait for blood results', false, 3),
  ('edf5f887-463e-581f-b709-bfb6ab716f0e', '2e098f09-f444-58e6-ad7c-bc4eccadc3c9', 'E', 'Take blood cultures, give IV broad-spectrum antibiotics and give an IV fluid bolus', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5b58a19f-a4a4-556d-9f23-3d63def19096', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 35 year old woman is brought in 2 hours after taking a large number of amitriptyline tablets. She is drowsy with a GCS of 11/15. Her heart rate is 128 beats/minute and blood pressure 94/60 mmHg. Her ECG shows sinus tachycardia with a QRS duration of 140 ms. Arterial pH is 7.29. What is the SINGLE most appropriate treatment?', 'Tricyclic antidepressant overdose blocks sodium channels and causes a broad QRS, arrhythmias, seizures and hypotension. IV sodium bicarbonate is first-line for a QRS over 100 ms, arrhythmias or acidosis, because alkalinisation and sodium loading reduce cardiotoxicity. Flumazenil is contraindicated because it can provoke seizures. Class I antiarrhythmics and amiodarone should be avoided. Charcoal is only given with a protected airway in a drowsy patient.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0de966ac-861f-526d-a4b7-5ec3bbc6f964', '5b58a19f-a4a4-556d-9f23-3d63def19096', 'A', 'IV amiodarone', false, 0),
  ('904f1595-df7e-52a5-8251-6bd228057f0d', '5b58a19f-a4a4-556d-9f23-3d63def19096', 'B', 'Oral activated charcoal through a nasogastric tube without airway protection', false, 1),
  ('dcbb0b30-d6a4-5b68-8f78-21d78c95363f', '5b58a19f-a4a4-556d-9f23-3d63def19096', 'C', 'IV naloxone', false, 2),
  ('605db6d2-68cb-5a9a-b735-c997687e4722', '5b58a19f-a4a4-556d-9f23-3d63def19096', 'D', 'IV flumazenil', false, 3),
  ('dc08d0bc-01a4-5f79-ae93-ff0c23b3e089', '5b58a19f-a4a4-556d-9f23-3d63def19096', 'E', 'IV sodium bicarbonate', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7da99967-6f15-58db-8edf-ce187ccfd75e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 45 year old man is brought in after a house fire. He has singed nasal hairs, soot in his mouth, a hoarse voice and stridor. His oxygen saturation is 95%. What is the SINGLE most appropriate immediate management?', 'Signs of inhalation injury (facial burns, singed nasal hair, soot, hoarseness, stridor) mean the airway can swell rapidly and obstruct. Early intubation by a senior anaesthetist is needed before airway oedema develops. High-flow oxygen treats possible carbon monoxide poisoning, and cyanide poisoning should be considered. Burns are assessed by total body surface area for fluid resuscitation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8d13d5ba-a14e-5116-89d2-394ac8703a2d', '7da99967-6f15-58db-8edf-ce187ccfd75e', 'A', 'Chest X-ray before any intervention', false, 0),
  ('18623977-8c7f-5c8d-a95d-c0b62d619ddd', '7da99967-6f15-58db-8edf-ce187ccfd75e', 'B', 'Discharge with advice', false, 1),
  ('4fe45d21-fa84-540e-a157-c2ae84f97a72', '7da99967-6f15-58db-8edf-ce187ccfd75e', 'C', 'Oral steroids', false, 2),
  ('93924e84-1661-5efd-bf40-443eb34dc3a2', '7da99967-6f15-58db-8edf-ce187ccfd75e', 'D', 'Nebulised salbutamol and observe', false, 3),
  ('aeed4bbc-1fe0-5d27-92f5-a69809942ee6', '7da99967-6f15-58db-8edf-ce187ccfd75e', 'E', 'Early senior anaesthetic review for definitive airway (intubation)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('50f7f141-27df-556c-9a5c-5e3c2897fd85', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 70 kg man has partial and full thickness burns to 30% of his body surface area. What is his fluid requirement in the first 24 hours according to the Parkland formula?', 'Parkland formula: 4 mL x weight (kg) x %TBSA = 4 x 70 x 30 = 8,400 mL of Hartmann''s in 24 hours, with half in the first 8 hours from the time of the burn and the rest over the next 16 hours. IV fluids are needed for burns over 15% in adults (10% in children). Superficial (epidermal) burns are not included in the TBSA calculation. Resuscitation is guided by urine output (0.5-1 mL/kg/h).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4cacd52e-2c75-53cd-b24f-164b36046150', '50f7f141-27df-556c-9a5c-5e3c2897fd85', 'A', '16,800 mL over 24 hours', false, 0),
  ('07406562-95fe-552c-b3eb-1fcf697674ea', '50f7f141-27df-556c-9a5c-5e3c2897fd85', 'B', '8,400 mL of crystalloid, half in the first 8 hours from the time of the burn', true, 1),
  ('ba3e82bd-2c70-5a54-a4c1-d056f16420f3', '50f7f141-27df-556c-9a5c-5e3c2897fd85', 'C', '4,200 mL over 24 hours', false, 2),
  ('371d3704-d8eb-5843-8ad2-de346f0b4712', '50f7f141-27df-556c-9a5c-5e3c2897fd85', 'D', '2,100 mL over 24 hours', false, 3),
  ('6da261b0-b92b-5c2a-8a2e-e00fcb1f79f8', '50f7f141-27df-556c-9a5c-5e3c2897fd85', 'E', 'No IV fluids needed', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('23d3bc80-bcf0-586e-a392-184f6009f8b8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 22 year old woman took an unknown quantity of aspirin 4 hours ago. She has tinnitus, vomiting, sweating and rapid breathing. Her ABG shows a mixed respiratory alkalosis and metabolic acidosis. Salicylate level is 750 mg/L. What is the SINGLE most appropriate treatment?', 'Salicylate poisoning causes tinnitus, vomiting, hyperventilation (respiratory alkalosis) and later metabolic acidosis, sweating and hypoglycaemia. IV sodium bicarbonate is used to alkalinise the urine for moderate toxicity. Haemodialysis is indicated for very high levels (over 700 mg/L), severe acidosis, AKI, pulmonary oedema, seizures or coma. Charcoal is used within 1 hour.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f7fecb56-af4b-57d2-aa10-33014ffb4ca6', '23d3bc80-bcf0-586e-a392-184f6009f8b8', 'A', 'IV sodium bicarbonate alone', false, 0),
  ('c1d693f7-1be4-51ca-8271-2f8d06904e36', '23d3bc80-bcf0-586e-a392-184f6009f8b8', 'B', 'Gastric lavage', false, 1),
  ('84f9ac48-72fe-588f-9a37-c4aee8466f9f', '23d3bc80-bcf0-586e-a392-184f6009f8b8', 'C', 'Haemodialysis', true, 2),
  ('2ea76e24-741a-5967-aa1d-cc2efdf2cb89', '23d3bc80-bcf0-586e-a392-184f6009f8b8', 'D', 'IV N-acetylcysteine', false, 3),
  ('ef0ef196-cb5e-55ef-8e30-07da07bc5a79', '23d3bc80-bcf0-586e-a392-184f6009f8b8', 'E', 'Oral activated charcoal only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9ed80f4a-4b2c-5cc3-9cb6-eabd17161fe8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 34 year old man is brought in after a seizure. His friends say he took ''ecstasy'' at a festival and drank large amounts of water. He is confused and his sodium is 121 mmol/L. His temperature is 39.8°C. What is the SINGLE most likely explanation for the hyponatraemia?', 'MDMA causes serotonin release, hyperthermia, sympathetic overactivity and SIADH. Combined with drinking a lot of water, this can cause severe hyponatraemia and cerebral oedema. Other complications include rhabdomyolysis, AKI, DIC and serotonin syndrome. Management is cooling, benzodiazepines, hypertonic saline for symptomatic hyponatraemia and supportive care.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e30f724d-c31a-5e3a-a28c-d55561d9f7f7', '9ed80f4a-4b2c-5cc3-9cb6-eabd17161fe8', 'A', 'Diabetes insipidus', false, 0),
  ('9af1137e-233f-5e8b-a2e5-204a68ed6600', '9ed80f4a-4b2c-5cc3-9cb6-eabd17161fe8', 'B', 'Laboratory error', false, 1),
  ('9e7a560a-002e-56a3-b338-193924ad8448', '9ed80f4a-4b2c-5cc3-9cb6-eabd17161fe8', 'C', 'Heat stroke alone', false, 2),
  ('35e1c998-5545-5c25-80a0-e0507c2f9987', '9ed80f4a-4b2c-5cc3-9cb6-eabd17161fe8', 'D', 'Adrenal crisis', false, 3),
  ('dcc0c9dd-e223-5cad-aa53-d9d96ce1df14', '9ed80f4a-4b2c-5cc3-9cb6-eabd17161fe8', 'E', 'MDMA-induced SIADH combined with excess water intake', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c268a7a-6324-5e1d-a02d-140d1c5594f7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 26 year old man has taken an overdose of his mother''s diazepam with alcohol. His GCS is 10, respiratory rate 12 and oxygen saturation 96% on air. He has no other drugs on board. What is the SINGLE most appropriate management?', 'Benzodiazepine overdose is usually managed supportively (airway, breathing, monitoring). Flumazenil is not routinely recommended because it can precipitate seizures, especially with co-ingested proconvulsants (such as tricyclics) or in benzodiazepine-dependent patients. It may be used carefully in specific iatrogenic cases. Alcohol increases respiratory depression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ceeaecd3-5e39-521e-a62c-786493e87a6f', '2c268a7a-6324-5e1d-a02d-140d1c5594f7', 'A', 'Activated charcoal by mouth while drowsy', false, 0),
  ('459476f5-2559-5480-ae4b-f0d75ad3dfc4', '2c268a7a-6324-5e1d-a02d-140d1c5594f7', 'B', 'Supportive care with airway protection and monitoring', true, 1),
  ('c3f2326d-bd41-5e6f-b3e6-d95d33129014', '2c268a7a-6324-5e1d-a02d-140d1c5594f7', 'C', 'Gastric lavage', false, 2),
  ('79af5025-ff4b-5cbc-a563-39d04215d23f', '2c268a7a-6324-5e1d-a02d-140d1c5594f7', 'D', 'IV naloxone', false, 3),
  ('96009b27-27cf-5646-9116-7902b63425aa', '2c268a7a-6324-5e1d-a02d-140d1c5594f7', 'E', 'IV flumazenil routinely', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2b6c6539-da4a-5fbd-b214-d84b5c2776e9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 59 year old man is found at home drowsy after drinking antifreeze. He has a high anion gap metabolic acidosis with a raised osmolar gap. Urine microscopy shows calcium oxalate crystals. What is the SINGLE most appropriate antidote?', 'Ethylene glycol (antifreeze) and methanol are metabolised by alcohol dehydrogenase to toxic metabolites, causing a high anion gap acidosis with a raised osmolar gap. Ethylene glycol causes AKI with oxalate crystals, and methanol causes visual loss. Fomepizole (or ethanol) blocks alcohol dehydrogenase. Haemodialysis is often needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a8f753ab-3eb4-5739-998a-f8e8e4836531', '2b6c6539-da4a-5fbd-b214-d84b5c2776e9', 'A', 'Naloxone', false, 0),
  ('867b7d3e-b34b-5a9c-acdd-14e74b3d7040', '2b6c6539-da4a-5fbd-b214-d84b5c2776e9', 'B', 'Fomepizole (or IV ethanol)', true, 1),
  ('710eae80-c9eb-503b-beb8-1298b978d301', '2b6c6539-da4a-5fbd-b214-d84b5c2776e9', 'C', 'Flumazenil', false, 2),
  ('eafecb79-5c2c-530d-9a41-1702a1bc4173', '2b6c6539-da4a-5fbd-b214-d84b5c2776e9', 'D', 'Desferrioxamine', false, 3),
  ('de5e27f1-5021-598b-bee4-6a4766621d72', '2b6c6539-da4a-5fbd-b214-d84b5c2776e9', 'E', 'N-acetylcysteine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('40a66e33-36a4-52fd-b623-68c399e851f6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 48 year old man is brought in after a fall from a ladder. He is alert but has neck pain and tenderness over his cervical spine. He has no neurological deficit. What is the SINGLE most appropriate imaging?', 'NICE recommends CT of the cervical spine (within 1 hour) for adults with neck pain or tenderness and dangerous mechanisms (such as a fall from over 1 m or 5 stairs), age 65 or over, focal neurology or other high-risk factors. Plain X-rays are mainly for children. The Canadian C-spine rule guides decisions. Spinal immobilisation is maintained until injury is excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ed22da87-8fbc-5f2d-b286-ef3169deb7e7', '40a66e33-36a4-52fd-b623-68c399e851f6', 'A', 'Flexion-extension X-rays', false, 0),
  ('6d5bf0ea-c167-5fac-a133-d63b6e8f74b6', '40a66e33-36a4-52fd-b623-68c399e851f6', 'B', 'Plain X-ray of the cervical spine in all adults', false, 1),
  ('31b1213b-af89-5fba-b44d-aef0fdfd713d', '40a66e33-36a4-52fd-b623-68c399e851f6', 'C', 'MRI as first-line', false, 2),
  ('7d693a91-bfda-5f76-8e45-a977a4427313', '40a66e33-36a4-52fd-b623-68c399e851f6', 'D', 'No imaging needed', false, 3),
  ('aff28940-45f7-5204-8275-bfe3df6bc708', '40a66e33-36a4-52fd-b623-68c399e851f6', 'E', 'CT scan of the cervical spine', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7364bc27-0a7e-5544-a279-439f89eeeb28', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 65 year old man has been pulled from cold water and is now hypothermic, with a core temperature of 29°C and a slow, irregular pulse. He is unconscious. What is the SINGLE most appropriate management?', 'Severe hypothermia (below 30°C) carries a high risk of ventricular fibrillation with rough handling. Management is careful handling, removing wet clothes, active rewarming (warm IV fluids, forced warm air, or extracorporeal rewarming in cardiac arrest) and monitoring. In arrest below 30°C, drugs are withheld and shocks limited to 3 until the patient is warmer. ''Not dead until warm and dead.''', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('01197573-58d4-5aba-8e5e-2c5a849a6506', '7364bc27-0a7e-5544-a279-439f89eeeb28', 'A', 'Careful handling, active internal rewarming and monitoring for arrhythmias (VF)', true, 0),
  ('c4326dc0-f809-56f0-9eff-152ea5c77451', '7364bc27-0a7e-5544-a279-439f89eeeb28', 'B', 'Give IV adrenaline every 3 minutes', false, 1),
  ('32d0c1b4-8df6-5d3c-8a8e-bf867579ad94', '7364bc27-0a7e-5544-a279-439f89eeeb28', 'C', 'Pronounce death immediately', false, 2),
  ('f4ee0929-798c-51f0-a721-b95a4c585fec', '7364bc27-0a7e-5544-a279-439f89eeeb28', 'D', 'Rapid vigorous movement to warm him', false, 3),
  ('52321bd9-c998-5318-8283-ccc828f2ed29', '7364bc27-0a7e-5544-a279-439f89eeeb28', 'E', 'Cool him further', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6c5a9583-afd6-55d1-b4c5-585d14a994b4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 70 year old woman is found collapsed at home during a heatwave. Her temperature is 41.2°C, she is confused and her skin is hot and dry. What is the SINGLE most appropriate immediate management?', 'Heat stroke is a core temperature over 40°C with CNS dysfunction, and it is a medical emergency. It needs rapid cooling (cold water immersion where possible, or evaporative cooling and ice packs to the groin and axillae) and treatment of complications (rhabdomyolysis, AKI, DIC, liver injury). Antipyretics are ineffective. Older people are especially at risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0c308705-3009-5481-8388-02a1557bd5dc', '6c5a9583-afd6-55d1-b4c5-585d14a994b4', 'A', 'Antibiotics alone', false, 0),
  ('511b310f-4efb-5348-bb3e-652703d92809', '6c5a9583-afd6-55d1-b4c5-585d14a994b4', 'B', 'Wrap in warm blankets', false, 1),
  ('973df4a3-0734-5e90-9436-a5ad75b5e1b5', '6c5a9583-afd6-55d1-b4c5-585d14a994b4', 'C', 'Rapid active cooling (e.g. evaporative cooling, ice packs) and supportive care', true, 2),
  ('7dd8cbe5-5add-590e-a67d-04dd7de249e1', '6c5a9583-afd6-55d1-b4c5-585d14a994b4', 'D', 'Oral paracetamol and observe', false, 3),
  ('643a2b12-a3c3-51d7-a515-ade4ccaa1ce2', '6c5a9583-afd6-55d1-b4c5-585d14a994b4', 'E', 'Discharge after fluids', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8fb6a631-aa71-5011-a191-a38400dc3cfd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 25 year old woman is stung by a bee and develops facial swelling, wheeze and urticaria, and her BP falls. She receives two doses of IM adrenaline with partial improvement. She remains hypotensive and wheezy. What is the SINGLE most appropriate next step?', 'Refractory anaphylaxis (persisting after two IM adrenaline doses) needs IV fluids and a low-dose IV adrenaline infusion with critical care support (Resuscitation Council UK). Mast cell tryptase is taken at 1-2 hours. Patients need observation for biphasic reactions, two adrenaline auto-injectors, and referral to an allergy clinic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b17e9c3d-edfb-5632-bedd-493a1338acf5', '8fb6a631-aa71-5011-a191-a38400dc3cfd', 'A', 'Give IV adrenaline 1 mg bolus', false, 0),
  ('7f2e00b8-e4d1-5096-a2c5-d4093458af3a', '8fb6a631-aa71-5011-a191-a38400dc3cfd', 'B', 'Give oral prednisolone only', false, 1),
  ('a6968dfe-3116-57ca-ad36-34599cb7dadf', '8fb6a631-aa71-5011-a191-a38400dc3cfd', 'C', 'Start an IV adrenaline infusion with critical care support and IV fluid bolus', true, 2),
  ('9cc64b5c-0e7e-598c-afa7-5b7eb12417b9', '8fb6a631-aa71-5011-a191-a38400dc3cfd', 'D', 'Give oral cetirizine and discharge', false, 3),
  ('18397d77-4e69-53e0-a64d-5cf18278f03c', '8fb6a631-aa71-5011-a191-a38400dc3cfd', 'E', 'Wait 4 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9177d60b-db55-5cda-9a84-871cb8e2940b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 72 year old man on anticoagulation is brought in after collapsing. He has a pulsatile abdominal mass and hypotension. Two large-bore cannulae are in place. He has received 1 L of crystalloid. Which strategy is MOST appropriate while transferring to theatre?', 'In major haemorrhage, activate the major haemorrhage protocol: give red cells, FFP and platelets in balanced ratios, tranexamic acid (in trauma, within 3 hours), reverse anticoagulation and use permissive hypotension until the bleeding is controlled. Excess crystalloid worsens coagulopathy (the lethal triad of hypothermia, acidosis and coagulopathy). O-negative blood is used in an emergency.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ddee05a0-6581-5a65-88fe-1f38858e54e8', '9177d60b-db55-5cda-9a84-871cb8e2940b', 'A', 'Activate major haemorrhage protocol with balanced blood products and permissive hypotension', true, 0),
  ('c7cf7825-e4bd-5d48-91e6-439a26061feb', '9177d60b-db55-5cda-9a84-871cb8e2940b', 'B', 'Raise BP to 160 mmHg with vasopressors', false, 1),
  ('d310f703-f776-5aef-8387-e31b6d3b30fc', '9177d60b-db55-5cda-9a84-871cb8e2940b', 'C', 'Transfuse platelets only', false, 2),
  ('f2db5986-e976-56c6-ac26-910bb6264626', '9177d60b-db55-5cda-9a84-871cb8e2940b', 'D', 'Wait for full crossmatch before giving blood', false, 3),
  ('1c4e593c-b1c0-591a-835f-5558c343f316', '9177d60b-db55-5cda-9a84-871cb8e2940b', 'E', 'Give 4 L of crystalloid rapidly', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0b1a90b2-e7c0-5a34-83ca-0ae6a1aa37bf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 30 year old woman is hit by a car. She is alert. Her BP is 82/50 mmHg and HR 130 beats/minute. FAST scan shows free fluid in the abdomen. Her chest X-ray and pelvis X-ray are normal. What is the SINGLE most appropriate management?', 'An unstable trauma patient with a positive FAST (free intraperitoneal fluid) needs an emergency laparotomy for haemorrhage control, likely from the spleen or liver. CT is only for haemodynamically stable patients. Damage control resuscitation with blood products and tranexamic acid is started.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b373adb-92ee-570e-9181-c4426e2437ab', '0b1a90b2-e7c0-5a34-83ca-0ae6a1aa37bf', 'A', 'Diagnostic peritoneal lavage', false, 0),
  ('22e85d4e-eb45-5752-9208-b59f20a09c5a', '0b1a90b2-e7c0-5a34-83ca-0ae6a1aa37bf', 'B', 'CT abdomen first', false, 1),
  ('bfcb53fa-402b-5ca6-a8a6-bf75ad5c5b7a', '0b1a90b2-e7c0-5a34-83ca-0ae6a1aa37bf', 'C', 'Observe and repeat FAST in 4 hours', false, 2),
  ('1bb758c5-ff1e-5e0b-83b1-3d36160f5e3b', '0b1a90b2-e7c0-5a34-83ca-0ae6a1aa37bf', 'D', 'IV fluids and discharge', false, 3),
  ('a0d78eb5-7a32-5f4d-afe1-215d83da54d5', '0b1a90b2-e7c0-5a34-83ca-0ae6a1aa37bf', 'E', 'Emergency laparotomy (with blood product resuscitation)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('48c8ba72-7a99-545a-96e4-74dd1f774254', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 23 year old man is struck on the left lower ribs during a rugby tackle. He has left upper quadrant pain and left shoulder tip pain (Kehr''s sign). He is haemodynamically stable. What is the SINGLE most appropriate investigation?', 'Left lower rib trauma with LUQ pain and referred shoulder tip pain suggests splenic injury. In a stable patient, a contrast CT grades the injury. Many splenic injuries are managed conservatively or with embolisation. Unstable patients need a laparotomy. After splenectomy, patients need vaccinations (pneumococcal, Hib, meningococcal, annual flu) and often lifelong penicillin prophylaxis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('320eadec-ebc1-51e7-9e4f-6d643d02a85b', '48c8ba72-7a99-545a-96e4-74dd1f774254', 'A', 'Upper GI endoscopy', false, 0),
  ('69c1fb4c-c98a-5939-a973-0d693cec8e1b', '48c8ba72-7a99-545a-96e4-74dd1f774254', 'B', 'Ultrasound in 1 week', false, 1),
  ('156c8e45-1e9f-5b17-9b67-a241c29b4186', '48c8ba72-7a99-545a-96e4-74dd1f774254', 'C', 'No imaging needed', false, 2),
  ('dc163c68-d378-5622-b7c0-9f0700771ca2', '48c8ba72-7a99-545a-96e4-74dd1f774254', 'D', 'Plain abdominal X-ray', false, 3),
  ('8c1d9387-5594-53a7-abf4-e36d6a8c8924', '48c8ba72-7a99-545a-96e4-74dd1f774254', 'E', 'CT abdomen with contrast', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b6fde30a-6bbf-58c6-9b0d-b15465893bd1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 45 year old man is brought in after a motorbike crash. He has severe pelvic pain, his BP is 84/50 mmHg and his pelvis is unstable on inspection. What is the SINGLE most appropriate immediate step?', 'Pelvic fractures can cause life-threatening haemorrhage. A pelvic binder at the level of the greater trochanters reduces pelvic volume and bleeding. The pelvis should not be ''sprung'', which can dislodge clot. Blood at the urethral meatus suggests urethral injury, so catheterisation should be avoided until assessed. Definitive control is by embolisation or surgical packing and fixation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d516ba27-75bf-5913-841d-fe13c3ab699b', 'b6fde30a-6bbf-58c6-9b0d-b15465893bd1', 'A', 'Spring the pelvis repeatedly to confirm instability', false, 0),
  ('10166679-d4a7-5aa5-8de7-186fda27a0c9', 'b6fde30a-6bbf-58c6-9b0d-b15465893bd1', 'B', 'Insert a urinary catheter immediately', false, 1),
  ('68570f6a-66d8-5d65-8d09-d2425fdc1ca2', 'b6fde30a-6bbf-58c6-9b0d-b15465893bd1', 'C', 'Perform a digital rectal exam first', false, 2),
  ('1c3dc68a-6235-5fc1-87af-504f8e0e7f29', 'b6fde30a-6bbf-58c6-9b0d-b15465893bd1', 'D', 'Send to MRI', false, 3),
  ('2ef8b3b1-b046-586e-9fb2-c9bd4fabe084', 'b6fde30a-6bbf-58c6-9b0d-b15465893bd1', 'E', 'Apply a pelvic binder at the level of the greater trochanters', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('250dcf4d-fbb1-5166-a884-70f8867695c6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 25 year old man has been punched in the face. He has double vision on upward gaze, numbness of his cheek and upper lip, and his eye appears sunken. What is the SINGLE most likely injury?', 'A blow-out fracture of the orbital floor can trap the inferior rectus, limiting upward gaze and causing diplopia, with infraorbital nerve numbness and enophthalmos. CT of the orbits confirms it. He needs maxillofacial and ophthalmology review, and should avoid nose blowing. Surgery is for persistent entrapment or significant enophthalmos.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7cace4cb-ec2a-5e6b-8cd9-61df9a1fdcbf', '250dcf4d-fbb1-5166-a884-70f8867695c6', 'A', 'Zygomatic arch fracture only', false, 0),
  ('9db0be73-0566-55d3-a02d-062e1423ee22', '250dcf4d-fbb1-5166-a884-70f8867695c6', 'B', 'Mandible fracture', false, 1),
  ('a6e7e477-caea-53b2-ad98-c5373dc44445', '250dcf4d-fbb1-5166-a884-70f8867695c6', 'C', 'Nasal fracture', false, 2),
  ('ee591869-3779-5f60-b2a3-2262170f70c9', '250dcf4d-fbb1-5166-a884-70f8867695c6', 'D', 'Retinal detachment', false, 3),
  ('5396a848-628e-56b5-983b-fe7e43b5193b', '250dcf4d-fbb1-5166-a884-70f8867695c6', 'E', 'Orbital floor (blow-out) fracture with inferior rectus entrapment', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3c04f7f9-0569-54c1-a9ec-798686217b27', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 34 year old man has been bitten on the hand by a dog 2 hours ago. The wound is a deep puncture over his knuckle. He has no allergies. What is the SINGLE most appropriate management?', 'Dog, cat and human bites carry a high risk of infection (Pasteurella, staphylococci, streptococci, anaerobes). Wounds are irrigated, debrided and usually left open, especially on the hand. Prophylactic co-amoxiclav is recommended for higher-risk bites (hand, deep, immunocompromised). Tetanus and rabies risk should be assessed. A ''fight bite'' over the knuckle may involve the joint.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e20e8185-e255-554e-927b-f5732b717b7d', '3c04f7f9-0569-54c1-a9ec-798686217b27', 'A', 'Suture the wound closed and no antibiotics', false, 0),
  ('aa593d8f-9394-5c05-907c-dae1ad0caf53', '3c04f7f9-0569-54c1-a9ec-798686217b27', 'B', 'Irrigate and debride the wound, leave it unsutured, give co-amoxiclav and assess tetanus status', true, 1),
  ('6681c1ee-24e5-505f-b951-6d34325e5eba', '3c04f7f9-0569-54c1-a9ec-798686217b27', 'C', 'Oral flucloxacillin alone', false, 2),
  ('90e760fd-f3af-557b-9da8-d74fa1f80003', '3c04f7f9-0569-54c1-a9ec-798686217b27', 'D', 'Oral metronidazole alone', false, 3),
  ('9565a594-4fa2-5415-8423-e3944020a1ff', '3c04f7f9-0569-54c1-a9ec-798686217b27', 'E', 'Topical antiseptic only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bc010c13-45d5-5913-85fc-904452f3c095', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 40 year old man has a dirty laceration from a rusty nail while gardening. He received a full course of 5 tetanus vaccinations in the past, the last over 10 years ago. What is the SINGLE most appropriate tetanus management?', 'UK guidance: people who have had a full 5-dose course do not need a booster after a tetanus-prone wound. A high-risk wound (heavy contamination, extensive devitalised tissue) may need human tetanus immunoglobulin. Incomplete or unknown immunisation needs a booster plus immunoglobulin for high-risk wounds. Thorough wound cleaning is essential.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e3a111f4-44dc-56a1-9578-9541570c4b93', 'bc010c13-45d5-5913-85fc-904452f3c095', 'A', 'No booster needed as he is fully immunised (immunoglobulin only if the wound is high-risk)', true, 0),
  ('31bb74f5-a2ed-53d3-a73d-524d7d14bcc8', 'bc010c13-45d5-5913-85fc-904452f3c095', 'B', 'Give tetanus immunoglobulin only', false, 1),
  ('2e5a77a3-914b-57f1-b8ac-7c5a9bc29d9e', 'bc010c13-45d5-5913-85fc-904452f3c095', 'C', 'Give a tetanus booster and immunoglobulin to everyone', false, 2),
  ('94f62655-6bc0-5249-a39e-abddd9fe640a', 'bc010c13-45d5-5913-85fc-904452f3c095', 'D', 'Give penicillin only', false, 3),
  ('47caae21-f08c-570b-bf21-38ec25fe5c81', 'bc010c13-45d5-5913-85fc-904452f3c095', 'E', 'Start a full primary course', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('165f5637-2967-5782-bee9-29336e8de0a1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 19 year old student is brought in after a bout of drinking. He has a GCS of 8, is vomiting, and has a capillary glucose of 2.8 mmol/L. What is the SINGLE most appropriate immediate management?', 'Acute alcohol intoxication can cause respiratory depression, aspiration, hypoglycaemia and hypothermia. Management is airway protection, the recovery position, correcting hypoglycaemia (IV glucose, with thiamine given if malnourished or alcohol-dependent) and looking for other causes of reduced GCS (head injury, other drugs). A persistently low GCS needs CT head.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b0d06074-741d-535d-8102-4a9b3c588654', '165f5637-2967-5782-bee9-29336e8de0a1', 'A', 'Give IV flumazenil', false, 0),
  ('daa347d1-565e-5c53-8300-bf3a76b7ea91', '165f5637-2967-5782-bee9-29336e8de0a1', 'B', 'Give oral glucose with airway unprotected', false, 1),
  ('94ab92ec-34f3-5754-9898-e9ef19f41c6b', '165f5637-2967-5782-bee9-29336e8de0a1', 'C', 'Protect airway, recovery position, give IV glucose and consider thiamine; reassess GCS', true, 2),
  ('1d8374d7-6e82-5130-8835-e49746b8df72', '165f5637-2967-5782-bee9-29336e8de0a1', 'D', 'Give IV naloxone', false, 3),
  ('0fa07061-65a0-5e47-b3e6-430c2feac2b5', '165f5637-2967-5782-bee9-29336e8de0a1', 'E', 'Leave him to sleep it off', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('805cea70-c004-5ebe-b5f1-a6c45a155ca3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 25 year old woman has severe, sudden swelling of her lips and tongue with difficulty breathing. She has a history of recurrent swelling episodes without urticaria, and her mother has the same. Adrenaline has little effect. Her C4 is low. What is the SINGLE most appropriate treatment?', 'Hereditary angioedema (C1 esterase inhibitor deficiency, autosomal dominant) causes recurrent bradykinin-mediated angioedema without urticaria, often with abdominal pain. It responds poorly to adrenaline, antihistamines and steroids. Acute treatment is C1-INH concentrate, icatibant (a bradykinin receptor antagonist) or ecallantide. Low C4 is a screening test.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e97103b3-39e8-524c-9d76-7bf035e42243', '805cea70-c004-5ebe-b5f1-a6c45a155ca3', 'A', 'Oral cetirizine', false, 0),
  ('e868aafa-dbcc-503f-a2d9-362171d63dbe', '805cea70-c004-5ebe-b5f1-a6c45a155ca3', 'B', 'IV chlorphenamine', false, 1),
  ('5114bef3-d168-57d7-9d4b-87fde80f1501', '805cea70-c004-5ebe-b5f1-a6c45a155ca3', 'C', 'C1 esterase inhibitor concentrate (or icatibant)', true, 2),
  ('c15e3071-ec3a-5b34-8d8a-051461ea356e', '805cea70-c004-5ebe-b5f1-a6c45a155ca3', 'D', 'IM adrenaline repeatedly', false, 3),
  ('8a660e65-fa46-5818-a1e2-8e0c1040e7f3', '805cea70-c004-5ebe-b5f1-a6c45a155ca3', 'E', 'Oral prednisolone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('99f680f9-d100-5c51-9590-4ff6ad3837ed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 28 year old man was in a car crash. He has right chest pain and breathlessness. His chest X-ray shows a large right pleural fluid collection and he is tachycardic. A chest drain immediately drains 1,600 mL of blood. What is the SINGLE most appropriate next step?', 'A massive haemothorax (over 1,500 mL on initial drainage, or ongoing loss over 200 mL/h for 2-4 hours) needs a thoracotomy, with resuscitation with blood products. Smaller haemothoraces are managed with a large-bore chest drain. Retained haemothorax can lead to empyema or a trapped lung.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dbc99b78-640f-5981-aa97-c5b32b6a8d1b', '99f680f9-d100-5c51-9590-4ff6ad3837ed', 'A', 'Remove the drain', false, 0),
  ('989964ec-0588-5cfa-a063-7ea47cfb3999', '99f680f9-d100-5c51-9590-4ff6ad3837ed', 'B', 'Give IV antibiotics only', false, 1),
  ('3688f930-93d3-5909-8bd9-4b37768f8000', '99f680f9-d100-5c51-9590-4ff6ad3837ed', 'C', 'Discharge after drain removal', false, 2),
  ('46c5b80b-8107-5aa2-9482-079729bffee1', '99f680f9-d100-5c51-9590-4ff6ad3837ed', 'D', 'Urgent thoracotomy', true, 3),
  ('db9ec265-52fe-591f-963f-7615feb62418', '99f680f9-d100-5c51-9590-4ff6ad3837ed', 'E', 'Clamp the drain and observe', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04c51f3b-5f93-57c8-a205-cf0d9254f0d1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 30 year old man took an overdose of 45 paracetamol 500 mg tablets 10 hours ago and is seen in the Emergency Department. His GCS is 15/15. His temperature is 37.0°C, pulse rate 80 bpm, BP 120/70 mmHg, respiratory rate 15 breaths per minute and oxygen saturation 99% breathing air. Blood for paracetamol level has been taken. Which is the most appropriate initial management?', 'She has taken 22.5 g (a potentially toxic dose) and presents 10 hours after ingestion. When presentation is 8-24 hours after a toxic dose, acetylcysteine should be started immediately without waiting for the paracetamol level. Charcoal is only useful within 1 hour, and gastric lavage is not recommended.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5a6e53c4-5542-56ef-b191-fc6a3d93da60', '04c51f3b-5f93-57c8-a205-cf0d9254f0d1', 'A', 'Await paracetamol levels before further action', false, 0),
  ('0c075ade-374a-5775-a185-3cc3188765f1', '04c51f3b-5f93-57c8-a205-cf0d9254f0d1', 'B', 'Gastric lavage', false, 1),
  ('17f9883e-8518-5656-be77-b72130a398e5', '04c51f3b-5f93-57c8-a205-cf0d9254f0d1', 'C', 'Give 50 g charcoal orally', false, 2),
  ('df3048a3-2d67-5787-a07e-b517c5600a94', '04c51f3b-5f93-57c8-a205-cf0d9254f0d1', 'D', 'No treatment required', false, 3),
  ('9fbef70f-c432-55ae-adf1-6523f079a74e', '04c51f3b-5f93-57c8-a205-cf0d9254f0d1', 'E', 'Start N-acetylcysteine', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d9cdf30d-0a2f-5273-a9c9-fa46a62318dc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 32 year old man falls from a ladder and sustains a mid-shaft fracture of the left humerus. On examination he cannot extend his wrist or fingers at the metacarpophalangeal joints and has reduced sensation over the dorsum of the hand at the base of the thumb. Which nerve is MOST likely to be injured?', 'The radial nerve runs in the spiral (radial) groove of the humeral shaft, so it is vulnerable in mid-shaft fractures. Injury causes wrist drop (loss of wrist and finger extensors) and sensory loss over the first dorsal web space. The axillary nerve is injured with surgical neck fractures or shoulder dislocation. The median nerve causes thenar weakness and the ulnar nerve causes claw hand.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('302ea767-a715-5e64-987b-64aeb972cad7', 'd9cdf30d-0a2f-5273-a9c9-fa46a62318dc', 'A', 'Axillary nerve', false, 0),
  ('fe35dfdd-1808-55fe-bcee-5d4a5701bda3', 'd9cdf30d-0a2f-5273-a9c9-fa46a62318dc', 'B', 'Ulnar nerve', false, 1),
  ('9bbbb37f-ce35-56e1-94f1-ba9ac46d8ba7', 'd9cdf30d-0a2f-5273-a9c9-fa46a62318dc', 'C', 'Median nerve', false, 2),
  ('196785d1-3394-5343-8ec5-f343cbe9cdb6', 'd9cdf30d-0a2f-5273-a9c9-fa46a62318dc', 'D', 'Radial nerve', true, 3),
  ('37c077cd-7862-535a-bf46-08e681b6df41', 'd9cdf30d-0a2f-5273-a9c9-fa46a62318dc', 'E', 'Musculocutaneous nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('076393f1-0c3a-5e59-9aa4-579e25ab3055', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 24 year old rugby player has his anterior shoulder dislocation reduced in the Emergency Department. Afterwards, he has weakness when abducting the arm beyond 15 degrees and a patch of numbness over the lateral aspect of the upper arm. Which nerve is MOST likely to be injured?', 'The axillary nerve wraps around the surgical neck of the humerus and is the nerve most often injured in anterior shoulder dislocation. It supplies deltoid (abduction from about 15 to 90 degrees) and teres minor, and gives sensation over the ''regimental badge'' area. Axillary nerve function should be documented before and after reduction. Supraspinatus (suprascapular nerve) starts abduction, and the long thoracic nerve causes a winged scapula.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1db2ead1-d0f8-5cbb-bdbc-4f459fd96f85', '076393f1-0c3a-5e59-9aa4-579e25ab3055', 'A', 'Long thoracic nerve', false, 0),
  ('91203d7b-2bd3-5fc0-8d50-9db6c7b1a27f', '076393f1-0c3a-5e59-9aa4-579e25ab3055', 'B', 'Suprascapular nerve', false, 1),
  ('b966f899-697d-5545-b5a7-d84a2e67ba21', '076393f1-0c3a-5e59-9aa4-579e25ab3055', 'C', 'Axillary nerve', true, 2),
  ('fb94d153-f80d-52b3-8952-4d25922f2792', '076393f1-0c3a-5e59-9aa4-579e25ab3055', 'D', 'Radial nerve', false, 3),
  ('b0d65618-ea87-5338-9483-d15540bd4955', '076393f1-0c3a-5e59-9aa4-579e25ab3055', 'E', 'Musculocutaneous nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('91df43f4-48a3-5b34-9eeb-9fdf3bc461b9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 50 year old woman has numbness and tingling in her thumb, index and middle fingers that wakes her at night and is relieved by shaking her hand. Tapping over the flexor retinaculum at the wrist reproduces her symptoms. Which nerve is MOST likely to be affected?', 'This is carpal tunnel syndrome, compression of the median nerve in the carpal tunnel. It causes paraesthesia in the lateral three and a half digits, which is worse at night, with a positive Tinel''s and Phalen''s sign. Thenar wasting is a late sign. Associations include pregnancy, hypothyroidism, diabetes, rheumatoid arthritis and acromegaly. Management is wrist splints, steroid injection or surgical decompression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('534ad684-7a2e-539a-9f81-15ffef84e824', '91df43f4-48a3-5b34-9eeb-9fdf3bc461b9', 'A', 'Median nerve', true, 0),
  ('d918918b-f7a5-5895-af04-4060797569b5', '91df43f4-48a3-5b34-9eeb-9fdf3bc461b9', 'B', 'Ulnar nerve', false, 1),
  ('4905f205-11f2-5c57-bc2e-6fb76ac2abdb', '91df43f4-48a3-5b34-9eeb-9fdf3bc461b9', 'C', 'Musculocutaneous nerve', false, 2),
  ('b5eb806d-95a9-5f1a-b3e9-db9c88c3c7ab', '91df43f4-48a3-5b34-9eeb-9fdf3bc461b9', 'D', 'Axillary nerve', false, 3),
  ('c07a60db-b466-54e5-8dcd-942c933de322', '91df43f4-48a3-5b34-9eeb-9fdf3bc461b9', 'E', 'Radial nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('56bd5f8b-1ab0-5153-81d3-9a49684cfa4c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 30 year old man is stabbed in the right side of his neck. Afterwards, he has drooping of his right shoulder and cannot shrug it against resistance. He has difficulty raising his arm above his head. Which nerve has MOST likely been injured?', 'The spinal accessory nerve crosses the posterior triangle of the neck superficially and supplies sternocleidomastoid and trapezius. Injury (from trauma or lymph node biopsy in the posterior triangle) causes weak shoulder shrugging, shoulder drooping and difficulty raising the arm above 90 degrees. The long thoracic nerve supplies serratus anterior; injury causes winging of the scapula.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('439e52ba-03ad-5111-91f9-f358d8d782e8', '56bd5f8b-1ab0-5153-81d3-9a49684cfa4c', 'A', 'Accessory nerve (cranial nerve XI)', true, 0),
  ('3d2eb831-526b-5a9c-8a52-d126d294597e', '56bd5f8b-1ab0-5153-81d3-9a49684cfa4c', 'B', 'Suprascapular nerve', false, 1),
  ('983d0e68-6726-5324-adab-9b7a0929253a', '56bd5f8b-1ab0-5153-81d3-9a49684cfa4c', 'C', 'Phrenic nerve', false, 2),
  ('6cd087fc-2bca-5e3c-b0b8-a40745d00c09', '56bd5f8b-1ab0-5153-81d3-9a49684cfa4c', 'D', 'Hypoglossal nerve', false, 3),
  ('9a9b987a-fd8f-5418-9275-576d05d21841', '56bd5f8b-1ab0-5153-81d3-9a49684cfa4c', 'E', 'Long thoracic nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6467a073-2d7d-58c0-84c3-a26207acadf4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 24 year old woman has a viral illness. Her blood test shows a raised IgM against a newly encountered virus. Which cell type is MOST directly responsible for producing these antibodies?', 'Antibodies are secreted by plasma cells, which are differentiated B lymphocytes. IgM is the first antibody produced in a primary immune response and indicates recent infection. IgG follows and is responsible for long-term immunity and crosses the placenta. Helper T cells (CD4) support B cell activation and class switching but do not secrete antibodies.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5e56504f-fb84-5a71-bed3-f7267f9625a7', '6467a073-2d7d-58c0-84c3-a26207acadf4', 'A', 'T helper cells', false, 0),
  ('3b06a7e3-3dfb-5e17-8fcd-c68169d3a45c', '6467a073-2d7d-58c0-84c3-a26207acadf4', 'B', 'Natural killer cells', false, 1),
  ('a9ef3605-d82a-5cdc-9e22-b24a5f0592e0', '6467a073-2d7d-58c0-84c3-a26207acadf4', 'C', 'Macrophages', false, 2),
  ('35704fd2-720d-550b-b8d0-c11fff6d5968', '6467a073-2d7d-58c0-84c3-a26207acadf4', 'D', 'Plasma cells', true, 3),
  ('c1187577-3daf-52e8-bc63-02942befc66b', '6467a073-2d7d-58c0-84c3-a26207acadf4', 'E', 'Neutrophils', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2826ce20-7d6a-5290-b8ad-e8b277005156', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 45 year old woman has had a thyroidectomy. Afterwards she has a hoarse voice. Which nerve is MOST likely to have been injured?', 'The recurrent laryngeal nerve runs in the tracheo-oesophageal groove close to the inferior thyroid artery and supplies all intrinsic laryngeal muscles except cricothyroid. Unilateral injury causes hoarseness, and bilateral injury can cause stridor and airway obstruction. The external branch of the superior laryngeal nerve supplies cricothyroid, and injury affects high-pitched voice. The left RLN loops under the aortic arch, so it can be affected by thoracic disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0025674d-bd34-5a66-82c8-294e157d1642', '2826ce20-7d6a-5290-b8ad-e8b277005156', 'A', 'Vagus nerve in the jugular foramen', false, 0),
  ('e7377f1c-063b-58aa-8081-af733f427d09', '2826ce20-7d6a-5290-b8ad-e8b277005156', 'B', 'External laryngeal nerve only', false, 1),
  ('ac22efd7-e0ec-5b9c-9057-98f3f0fbdb9d', '2826ce20-7d6a-5290-b8ad-e8b277005156', 'C', 'Hypoglossal nerve', false, 2),
  ('05c29ea7-dd2a-5fb1-9b32-e43ae1b37abc', '2826ce20-7d6a-5290-b8ad-e8b277005156', 'D', 'Phrenic nerve', false, 3),
  ('33b73dd7-acbf-5be4-b7f8-13b59ea04faa', '2826ce20-7d6a-5290-b8ad-e8b277005156', 'E', 'Recurrent laryngeal nerve', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e1159c91-759d-5c61-aa83-128767981823', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 30 year old man sustains a deep laceration to the medial side of his elbow. He now has weakness of finger abduction and adduction, and a claw-like deformity of his ring and little fingers, with numbness of the little finger. Which nerve is injured?', 'The ulnar nerve supplies the interossei, the medial two lumbricals and hypothenar muscles, and sensation to the little finger and medial half of the ring finger. Injury causes claw hand (ring and little fingers), weak finger abduction and adduction, and a positive Froment''s sign. The ''ulnar paradox'' means a proximal lesion causes less clawing because flexor digitorum profundus is also weakened.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('78826455-3e68-5f55-becb-d0238258bcd0', 'e1159c91-759d-5c61-aa83-128767981823', 'A', 'Musculocutaneous nerve', false, 0),
  ('e173ac12-acca-5320-baf3-10c85614f045', 'e1159c91-759d-5c61-aa83-128767981823', 'B', 'Median nerve', false, 1),
  ('36fe1f79-6c6b-5e92-9f9e-5ff951e7798d', 'e1159c91-759d-5c61-aa83-128767981823', 'C', 'Axillary nerve', false, 2),
  ('0f8c3cf7-b62b-586a-89ae-839b500bdcea', 'e1159c91-759d-5c61-aa83-128767981823', 'D', 'Radial nerve', false, 3),
  ('a1719319-98fd-5edb-96dd-bbd062f503be', 'e1159c91-759d-5c61-aa83-128767981823', 'E', 'Ulnar nerve', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e93dcffe-40ec-568c-be96-cf1710d78b73', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 50 year old man has foot drop after a fracture of the fibular neck. He cannot dorsiflex or evert his foot and has numbness over the dorsum of the foot. Which nerve is injured?', 'The common peroneal nerve wraps around the neck of the fibula and is vulnerable to fractures, tight casts and leg crossing. Injury causes foot drop (weak dorsiflexion and eversion) and sensory loss over the dorsum of the foot and lateral leg, with intact inversion and ankle reflex. This distinguishes it from an L5 radiculopathy, in which inversion is also weak.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('05a84ae0-d01c-5f94-9495-8dfd0bef64f2', 'e93dcffe-40ec-568c-be96-cf1710d78b73', 'A', 'Common peroneal (fibular) nerve', true, 0),
  ('6835cf4e-c222-5726-a9e8-b30f30b3751a', 'e93dcffe-40ec-568c-be96-cf1710d78b73', 'B', 'Femoral nerve', false, 1),
  ('1159a549-76b6-5bf2-814e-4f54000859ce', 'e93dcffe-40ec-568c-be96-cf1710d78b73', 'C', 'Obturator nerve', false, 2),
  ('077cab67-d7a1-5be6-b1f8-cab37dff9613', 'e93dcffe-40ec-568c-be96-cf1710d78b73', 'D', 'Sciatic nerve', false, 3),
  ('54474253-ce77-54fa-812d-b58166d81fbe', 'e93dcffe-40ec-568c-be96-cf1710d78b73', 'E', 'Tibial nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d8650726-324c-51ef-ade7-69dacd3be1fd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 28 year old woman has had winging of her right scapula, noticed when pushing against a wall, after a mastectomy with axillary node clearance. Which nerve has been injured?', 'The long thoracic nerve (C5-C7) supplies serratus anterior, which holds the scapula against the chest wall. Injury (in axillary surgery, carrying heavy loads, or trauma) causes winging of the scapula, seen when pushing against a wall. The thoracodorsal nerve supplies latissimus dorsi. Accessory nerve injury causes lateral winging from trapezius weakness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1e58bc37-66a3-5636-b3fb-d0dcbf3434d5', 'd8650726-324c-51ef-ade7-69dacd3be1fd', 'A', 'Axillary nerve', false, 0),
  ('7ec21b74-93b7-52be-a4dd-815492e02696', 'd8650726-324c-51ef-ade7-69dacd3be1fd', 'B', 'Long thoracic nerve', true, 1),
  ('c7920b3a-b1ce-52d7-8909-f8fc8893c791', 'd8650726-324c-51ef-ade7-69dacd3be1fd', 'C', 'Thoracodorsal nerve', false, 2),
  ('71fb60e6-2d12-5652-8753-552c640524de', 'd8650726-324c-51ef-ade7-69dacd3be1fd', 'D', 'Suprascapular nerve', false, 3),
  ('c55cd92d-8cb7-5e36-bf81-d7edcaaebf45', 'd8650726-324c-51ef-ade7-69dacd3be1fd', 'E', 'Accessory nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('99b565d7-e7ef-5d73-8e0d-a57c6a27758e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 66 year old man has a stab wound to the anterior thigh with loss of knee extension and absent knee reflex. Sensation over the anterior thigh and medial leg is reduced. Which nerve is injured?', 'The femoral nerve (L2-L4) supplies quadriceps (knee extension) and the knee reflex, and sensation to the anterior thigh and, via the saphenous nerve, the medial leg. Injury causes weak knee extension and an absent knee jerk. The obturator nerve supplies the hip adductors. The lateral femoral cutaneous nerve causes meralgia paraesthetica (lateral thigh numbness) without weakness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d61eb5cc-ff09-5d54-85b6-e81463d27dcc', '99b565d7-e7ef-5d73-8e0d-a57c6a27758e', 'A', 'Lateral femoral cutaneous nerve', false, 0),
  ('6b54ed06-f65d-5586-8083-06912603792a', '99b565d7-e7ef-5d73-8e0d-a57c6a27758e', 'B', 'Femoral nerve', true, 1),
  ('4938b547-8f8f-555e-a4f0-733ea9017ca2', '99b565d7-e7ef-5d73-8e0d-a57c6a27758e', 'C', 'Obturator nerve', false, 2),
  ('87beb07b-360b-582b-870f-73d4643c6db0', '99b565d7-e7ef-5d73-8e0d-a57c6a27758e', 'D', 'Common peroneal nerve', false, 3),
  ('c9b045b1-18d1-5524-8164-eec514746c2f', '99b565d7-e7ef-5d73-8e0d-a57c6a27758e', 'E', 'Sciatic nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0b9709ff-138f-5878-8d81-fbf296bc282a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 35 year old pregnant woman has burning and numbness on the outer side of her thigh, worse on standing. There is no weakness and reflexes are normal. Which nerve is MOST likely affected?', 'Meralgia paraesthetica is compression of the lateral cutaneous nerve of the thigh as it passes under the inguinal ligament. It causes purely sensory symptoms on the anterolateral thigh. Risk factors include pregnancy, obesity, tight belts and diabetes. Treatment is conservative (loosening clothing, weight loss), with nerve blocks if it persists.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('545ca917-4afa-5383-bf96-5c6492629732', '0b9709ff-138f-5878-8d81-fbf296bc282a', 'A', 'Femoral nerve', false, 0),
  ('c6b8f040-edbb-51d6-920f-e4bea02a95ac', '0b9709ff-138f-5878-8d81-fbf296bc282a', 'B', 'Sciatic nerve', false, 1),
  ('02c5f6a2-c3ab-5a6c-a85a-21efea544825', '0b9709ff-138f-5878-8d81-fbf296bc282a', 'C', 'Lateral cutaneous nerve of the thigh (meralgia paraesthetica)', true, 2),
  ('2f7f1c6d-0994-5580-8014-ae4eab6390bf', '0b9709ff-138f-5878-8d81-fbf296bc282a', 'D', 'L4 nerve root', false, 3),
  ('bc897b76-4174-5d08-aa6b-e09166ed7979', '0b9709ff-138f-5878-8d81-fbf296bc282a', 'E', 'Obturator nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f9ee6f61-e1d6-52d3-9529-5623f31f67ed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 45 year old man has absent ankle reflexes bilaterally. Which spinal nerve root segment is tested by the ankle reflex?', 'Reflex root values: biceps C5-C6, supinator (brachioradialis) C5-C6, triceps C7, knee L3-L4, and ankle S1-S2. A useful rhyme is ''S1-2 buckle my shoe, 3-4 kick the door, 5-6 pick up sticks, 7-8 lay them straight''. Plantar responses test corticospinal tract integrity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1bda4ae5-07fc-59cc-a330-e70c3f3130f2', 'f9ee6f61-e1d6-52d3-9529-5623f31f67ed', 'A', 'L3-L4', false, 0),
  ('f247b542-f8fe-5859-b7ba-d913c89293c0', 'f9ee6f61-e1d6-52d3-9529-5623f31f67ed', 'B', 'S1 (S1-S2)', true, 1),
  ('a0e82b87-1f07-5038-9e89-e522fbd61958', 'f9ee6f61-e1d6-52d3-9529-5623f31f67ed', 'C', 'C7-C8', false, 2),
  ('bb2bf163-4ab0-51de-ad6a-c829f9abc3e8', 'f9ee6f61-e1d6-52d3-9529-5623f31f67ed', 'D', 'C5-C6', false, 3),
  ('6aa331a4-9eaa-5d66-9a4f-6264a2cd8d11', 'f9ee6f61-e1d6-52d3-9529-5623f31f67ed', 'E', 'L5', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e39c14a5-28d8-5ca7-8edc-73a909166b97', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 60 year old man had a right middle cerebral artery stroke. Which of the following clinical features is MOST likely?', 'The MCA supplies the lateral cerebral hemisphere, so occlusion causes contralateral face and arm weakness and sensory loss (more than the leg), contralateral homonymous hemianopia, and aphasia (if the dominant, usually left, hemisphere) or neglect (if non-dominant, usually right). ACA strokes affect the contralateral leg more than the arm. Posterior circulation strokes cause cerebellar or brainstem signs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('da850ce0-50b9-5ff6-ab2e-249a550b79cc', 'e39c14a5-28d8-5ca7-8edc-73a909166b97', 'A', 'Bilateral visual loss', false, 0),
  ('005d13d6-5048-5393-837e-57c716690450', 'e39c14a5-28d8-5ca7-8edc-73a909166b97', 'B', 'Vertigo and ataxia', false, 1),
  ('e6b41ddc-84b4-5d4c-9b35-340155f36976', 'e39c14a5-28d8-5ca7-8edc-73a909166b97', 'C', 'Expressive aphasia in a right-handed person', false, 2),
  ('1f5de5e2-f524-5f7c-9073-e04d48ba8633', 'e39c14a5-28d8-5ca7-8edc-73a909166b97', 'D', 'Left-sided face and arm weakness more than leg, with left-sided neglect', true, 3),
  ('5f999b7c-fea0-54ea-9aaf-1f9f480a1124', 'e39c14a5-28d8-5ca7-8edc-73a909166b97', 'E', 'Right-sided leg weakness more than arm', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('756ad248-7640-50b1-b1b4-0a39cfe50ba8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 70 year old woman has a sudden onset left homonymous hemianopia with macular sparing. She has no limb weakness. Which artery is MOST likely occluded?', 'The posterior cerebral artery supplies the occipital cortex. Occlusion causes contralateral homonymous hemianopia, often with macular sparing because of dual supply from the MCA. Lesions of the optic chiasm (such as a pituitary tumour) cause bitemporal hemianopia, and optic tract lesions cause incongruous homonymous hemianopia. Temporal lobe lesions cause superior quadrantanopia (''pie in the sky'').', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a9cabee7-df0d-5ca5-91c8-b4a4cc3cdcf0', '756ad248-7640-50b1-b1b4-0a39cfe50ba8', 'A', 'Anterior communicating artery', false, 0),
