insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c60faa8-0832-5638-bc97-92ed5ef59a0d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 28 year old man has a stab wound causing a hemisection of his spinal cord at T10 on the right. Which pattern of deficits is MOST likely below the lesion?', 'Brown-Séquard syndrome (hemisection of the cord) causes ipsilateral motor weakness (corticospinal tract) and loss of proprioception and vibration (dorsal columns), plus contralateral loss of pain and temperature (spinothalamic tract, which decussates within 1-2 segments of entering the cord). Anterior cord syndrome spares the dorsal columns, and central cord syndrome affects the arms more than the legs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('647d7e6b-3ab3-546e-a84b-9d9e38bdcf51', '9c60faa8-0832-5638-bc97-92ed5ef59a0d', 'A', 'Left-sided weakness with right-sided proprioceptive loss', false, 0),
  ('63dc0c39-b1a4-526d-b3b9-3cdbdb965265', '9c60faa8-0832-5638-bc97-92ed5ef59a0d', 'B', 'Right-sided loss of pain and temperature only', false, 1),
  ('f2a6aaba-74d4-5253-9ee5-23271d4aa2da', '9c60faa8-0832-5638-bc97-92ed5ef59a0d', 'C', 'No deficit', false, 2),
  ('ef5c68a4-10c4-5226-9281-37eb641735d9', '9c60faa8-0832-5638-bc97-92ed5ef59a0d', 'D', 'Bilateral loss of all sensation', false, 3),
  ('4a78bc00-b5c9-5595-b075-f22a6774acea', '9c60faa8-0832-5638-bc97-92ed5ef59a0d', 'E', 'Right-sided weakness and loss of proprioception, with left-sided loss of pain and temperature', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('23165813-1618-5011-bd2e-cb1ccce2792a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 65 year old man has a loss of pain and temperature sensation in a ''cape-like'' distribution over his shoulders and arms, with preserved light touch and proprioception. He has wasting of the small hand muscles. MRI shows a fluid-filled cavity in the cervical cord. What is the SINGLE most likely diagnosis?', 'Syringomyelia is a fluid-filled cavity in the central spinal cord, often associated with Chiari malformation. It damages the decussating spinothalamic fibres, causing dissociated sensory loss (loss of pain and temperature with preserved touch and proprioception) in a cape distribution, plus lower motor neurone signs in the arms from anterior horn involvement. Painless burns can occur.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
