  ('11bde7f9-3622-5468-a554-c1bb20b9b2c5', '23165813-1618-5011-bd2e-cb1ccce2792a', 'A', 'Multiple sclerosis', false, 0),
  ('9981afcf-c7bc-5956-b09e-59c677bfca92', '23165813-1618-5011-bd2e-cb1ccce2792a', 'B', 'Carpal tunnel syndrome', false, 1),
  ('9761f5f2-82d4-535c-a664-8f41bf3f1b42', '23165813-1618-5011-bd2e-cb1ccce2792a', 'C', 'Syringomyelia', true, 2),
  ('e5ab6449-5dd6-52a1-aa99-91271f49e036', '23165813-1618-5011-bd2e-cb1ccce2792a', 'D', 'Brown-Séquard syndrome', false, 3),
  ('50a1c762-77cc-505f-b998-affe33100f4f', '23165813-1618-5011-bd2e-cb1ccce2792a', 'E', 'Motor neurone disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e73ebc2d-67d4-5f31-a33d-2d2b1a74ca2c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 40 year old woman has bacterial meningitis. The lumbar puncture is performed at the L3-L4 interspace. Which structure is the LAST to be penetrated before entering the subarachnoid space?', 'LP layers in order: skin, subcutaneous tissue, supraspinous ligament, interspinous ligament, ligamentum flavum, epidural space, dura mater, arachnoid mater, then the subarachnoid space containing CSF. The spinal cord ends at L1-L2 in adults, so the L3-L4 or L4-L5 interspaces are used. The iliac crests (Tuffier''s line) mark the L4 level.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
