  ('a123a519-03c3-522d-9db5-1aa8363c62e7', 'e73ebc2d-67d4-5f31-a33d-2d2b1a74ca2c', 'A', 'Ligamentum flavum', false, 0),
  ('8d06da6e-3cec-5cf7-9e38-0979cf366fd0', 'e73ebc2d-67d4-5f31-a33d-2d2b1a74ca2c', 'B', 'Pia mater', false, 1),
  ('4297492c-f7f6-50ad-bfe5-20ce4ef6994d', 'e73ebc2d-67d4-5f31-a33d-2d2b1a74ca2c', 'C', 'Arachnoid mater (after the dura mater)', true, 2),
  ('4b73acfe-6fee-5eee-a5de-a6c35c97eab9', 'e73ebc2d-67d4-5f31-a33d-2d2b1a74ca2c', 'D', 'Interspinous ligament', false, 3),
  ('8b29aac8-8b18-562d-adc8-38e7d78232db', 'e73ebc2d-67d4-5f31-a33d-2d2b1a74ca2c', 'E', 'Supraspinous ligament', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4ebbb97b-42aa-57ce-a948-e396098808dd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 30 year old woman with a blood group A rhesus-negative type has a baby who is group O rhesus-positive. Which type of antibody is MOST responsible for haemolytic disease of the newborn due to rhesus incompatibility?', 'Only IgG crosses the placenta, which is why maternal anti-D (IgG) produced after a sensitising event can cause haemolytic disease of the fetus and newborn in later rhesus-positive pregnancies. IgM is the first antibody produced in a primary response and is too large to cross the placenta. Anti-D prophylaxis prevents sensitisation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
