  ('f0409582-ab02-5b3c-a499-5107b7a83f04', '4ebbb97b-42aa-57ce-a948-e396098808dd', 'B', 'IgA', false, 1),
  ('e831ceec-7fff-5403-9b31-38cf4d47f94a', '4ebbb97b-42aa-57ce-a948-e396098808dd', 'C', 'IgD', false, 2),
  ('5a9a5eaa-944b-5d7c-a78a-28173295acde', '4ebbb97b-42aa-57ce-a948-e396098808dd', 'D', 'IgG', true, 3),
