insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e45d4690-4001-5ec0-aacf-82b6ea6f1f66', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 25 year old man has recurrent pneumococcal and meningococcal infections. Which complement deficiency is MOST associated with recurrent Neisseria infections?', 'Terminal complement (membrane attack complex, C5-C9) deficiency predisposes to recurrent Neisseria infections. C3 deficiency causes severe recurrent pyogenic infections. Early classical pathway deficiencies (C1q, C2, C4) are linked to SLE. C1 esterase inhibitor deficiency causes hereditary angioedema. Eculizumab (a C5 inhibitor) raises meningococcal risk, so vaccination is required.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
