  ('a9c1786f-c6b8-5daf-9318-ac62f696684d', 'e45d4690-4001-5ec0-aacf-82b6ea6f1f66', 'A', 'C1 esterase inhibitor deficiency', false, 0),
  ('faf57a67-e914-539c-a7ca-787afaede2aa', 'e45d4690-4001-5ec0-aacf-82b6ea6f1f66', 'B', 'Mannose-binding lectin excess', false, 1),
  ('c1d1690a-c8e9-5562-a8bf-cec9141de206', 'e45d4690-4001-5ec0-aacf-82b6ea6f1f66', 'C', 'Deficiency of terminal complement components (C5-C9)', true, 2),
  ('64d38da5-16c5-5520-b124-54454b4cb22b', 'e45d4690-4001-5ec0-aacf-82b6ea6f1f66', 'D', 'Factor H excess', false, 3),
  ('a50845fd-0bfd-5611-b9bd-29dcba49c0b9', 'e45d4690-4001-5ec0-aacf-82b6ea6f1f66', 'E', 'C3 deficiency only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8812f66f-2ca1-5f64-a1dd-7560f60f5482', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 50 year old man has had a splenectomy after trauma. Which organisms is he at MOST increased risk of overwhelming infection from?', 'The spleen is key to clearing encapsulated bacteria. After splenectomy, there is a risk of overwhelming post-splenectomy infection. Prevention is vaccination (pneumococcal, Hib, MenB, MenACWY and annual flu), long-term antibiotic prophylaxis (penicillin V), an emergency antibiotic supply, a patient card and malaria precautions for travel. A blood film shows Howell-Jolly bodies.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
