  ('c8456764-204b-58e7-8039-95c7707d7aea', '8812f66f-2ca1-5f64-a1dd-7560f60f5482', 'A', 'Gram-negative enteric bacteria only', false, 0),
  ('9a1e05e5-8033-5f4c-9830-dc4cef24f572', '8812f66f-2ca1-5f64-a1dd-7560f60f5482', 'B', 'Encapsulated bacteria (Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis)', true, 1),
