  ('c7209562-e94f-529c-ae8d-8162f84b5241', '8812f66f-2ca1-5f64-a1dd-7560f60f5482', 'D', 'Herpes viruses', false, 3),
  ('7803786c-c281-5bb8-ae99-e6fdf1e22ae6', '8812f66f-2ca1-5f64-a1dd-7560f60f5482', 'E', 'Fungi such as Candida', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('572b4108-ed43-5c6f-bfab-cb1cb11f6bb6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 23 year old woman has a type 1 hypersensitivity reaction to peanuts. Which mediator is MOST responsible for the immediate symptoms?', 'Type I hypersensitivity is IgE-mediated mast cell degranulation, releasing histamine, tryptase and leukotrienes within minutes (anaphylaxis, urticaria, asthma). Type II is antibody-mediated cytotoxicity (haemolytic disease, Goodpasture''s), Type III is immune complexes (SLE, serum sickness) and Type IV is delayed T-cell mediated (contact dermatitis, the Mantoux test).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
