  ('5256e8e3-c2c6-531e-9bc9-a0024690289e', '572b4108-ed43-5c6f-bfab-cb1cb11f6bb6', 'A', 'Complement-mediated lysis of red cells', false, 0),
  ('aaf9f6fd-ef00-5f8c-a581-a2af5c43a5d7', '572b4108-ed43-5c6f-bfab-cb1cb11f6bb6', 'B', 'Histamine released from mast cells (IgE-mediated)', true, 1),
  ('63aeda42-a8e5-5305-98d1-983789e8b6a0', '572b4108-ed43-5c6f-bfab-cb1cb11f6bb6', 'C', 'IgG immune complexes', false, 2),
  ('bd1f4f03-67f7-5bb3-828d-b1cd53d2e2bf', '572b4108-ed43-5c6f-bfab-cb1cb11f6bb6', 'D', 'Interferon-gamma', false, 3),
  ('6125e258-ac64-57df-8419-5056b83a5002', '572b4108-ed43-5c6f-bfab-cb1cb11f6bb6', 'E', 'T-cell cytokines (delayed)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1ad2b5a9-a0b6-58a5-a430-74483769bfb1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 4 year old boy has recurrent bacterial infections since 6 months of age (otitis, pneumonia). His serum immunoglobulins are all very low and he has no detectable B cells. His maternal uncle had similar infections. What is the SINGLE most likely diagnosis?', 'Bruton''s agammaglobulinaemia is X-linked (BTK gene). It causes absent B cells and very low immunoglobulins, with recurrent bacterial infections from about 6 months as maternal IgG wanes. Treatment is lifelong immunoglobulin replacement. DiGeorge syndrome (22q11 deletion) causes T-cell deficiency, hypocalcaemia and cardiac defects. Chronic granulomatous disease is a neutrophil oxidative burst defect.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6bba3574-4f90-532f-b309-a62b041bba3c', '1ad2b5a9-a0b6-58a5-a430-74483769bfb1', 'A', 'X-linked (Bruton''s) agammaglobulinaemia', true, 0),
  ('e8b1d076-54a9-5364-bbb1-b78e5b1dc0da', '1ad2b5a9-a0b6-58a5-a430-74483769bfb1', 'B', 'Severe combined immunodeficiency', false, 1),
  ('23fe9745-4f2b-5ef6-bf91-c4a473751d36', '1ad2b5a9-a0b6-58a5-a430-74483769bfb1', 'C', 'Chronic granulomatous disease', false, 2),
  ('6b1b4cfe-f148-5edc-b94d-e259b8077417', '1ad2b5a9-a0b6-58a5-a430-74483769bfb1', 'D', 'Selective IgA deficiency', false, 3),
  ('3807d8d3-46b0-5c59-b924-0856242f87cb', '1ad2b5a9-a0b6-58a5-a430-74483769bfb1', 'E', 'DiGeorge syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('20901148-134c-5cfd-944d-0e56abe33213', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 54 year old man is unable to grip effectively with his right hand following recovery from a general anaesthetic for bowel surgery. At the end of the procedure his right arm was found to be hanging over the edge of the operating table. There is weakness of extension of his right wrist and altered sensation over the dorsum of his first web space. Which is the most likely affected nerve?', 'An arm hanging over the edge of the operating table compresses the radial nerve in the spiral groove of the humerus. This causes wrist drop (weak wrist and finger extension) and sensory loss over the first dorsal web space. It is usually a neurapraxia that recovers within weeks to months, and careful positioning during anaesthesia prevents it.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
