  ('48afa256-f389-5da8-ad44-6dcb69224812', '20901148-134c-5cfd-944d-0e56abe33213', 'B', 'Median', false, 1),
  ('029118cf-55fe-5a08-a265-96e35c2b2623', '20901148-134c-5cfd-944d-0e56abe33213', 'C', 'Musculocutaneous', false, 2),
