insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('59ce7cb4-efff-51f3-bd36-0adc2bbd9449', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 55 year old man has difficulty breathing after being stabbed with a knife in the right side of his neck. The wound is in the right posterior triangle of his neck. His chest movements are asymmetrical. Which nerve is most likely damaged on the injured side?', 'The phrenic nerve (C3-C5) runs over scalenus anterior in the neck and supplies the diaphragm. Injury causes paralysis of the diaphragm on the same side, with asymmetrical chest movement and breathlessness. Diaphragm paralysis can be confirmed with a sniff test under fluoroscopy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
