  ('076149ae-5b21-50cd-832c-876db4c78af6', '59ce7cb4-efff-51f3-bd36-0adc2bbd9449', 'A', 'Greater splanchnic nerve', false, 0),
  ('4a0ad0ca-020f-5e36-a3e3-6e0e0bf36222', '59ce7cb4-efff-51f3-bd36-0adc2bbd9449', 'B', 'Phrenic nerve', true, 1),
  ('07de27e8-4355-536d-8ab1-6a52ce3e83f4', '59ce7cb4-efff-51f3-bd36-0adc2bbd9449', 'C', 'Recurrent laryngeal nerve', false, 2),
  ('4925885c-8f35-55fb-836c-1d0725de627d', '59ce7cb4-efff-51f3-bd36-0adc2bbd9449', 'D', 'Spinal accessory nerve', false, 3),
