insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c7a14bd-c7da-5b24-9126-07125da8bced', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 34 year old woman attends her GP after finding a lump in her left breast 3 weeks ago. It has not changed with her menstrual cycle. On examination there is a 2 cm firm, non-tender lump in the upper outer quadrant. There is no skin change or nipple discharge, and the axilla is normal. What is the SINGLE most appropriate management?', 'NICE recommends a suspected cancer pathway referral for women aged 30 and over with an unexplained breast lump, with or without pain. She will have triple assessment at the breast clinic: clinical examination, imaging (ultrasound if under 40) and core biopsy. GPs should not try to diagnose a lump as benign or arrange imaging themselves.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('05602b2b-a393-5356-ab0c-be8f29c8ecda', '2c7a14bd-c7da-5b24-9126-07125da8bced', 'A', 'Review after her next menstrual period', false, 0),
  ('cb91b009-582c-5200-8f78-c941935086ab', '2c7a14bd-c7da-5b24-9126-07125da8bced', 'B', 'Arrange a mammogram via the GP', false, 1),
  ('556a9ad0-ca2d-5bf5-864b-88a5f3fe1cdf', '2c7a14bd-c7da-5b24-9126-07125da8bced', 'C', 'Reassure; it is most likely a fibroadenoma', false, 2),
  ('786e3428-d300-5793-858a-84df16b09a3a', '2c7a14bd-c7da-5b24-9126-07125da8bced', 'D', 'Suspected cancer pathway (two-week wait) referral to the breast clinic', true, 3),
  ('0586ff0c-daa3-5762-9a30-8c0741357c08', '2c7a14bd-c7da-5b24-9126-07125da8bced', 'E', 'Arrange a routine non-urgent breast clinic referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4a2b2950-cbca-5d2e-982e-b795c033900a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 29 year old breastfeeding woman, 3 weeks after delivery, has 2 days of a painful, red, swollen wedge-shaped area in her left breast with a fever of 38.3°C. There is no fluctuant mass. Breastfeeding is painful. What is the SINGLE most appropriate management?', 'This is lactational mastitis, usually caused by milk stasis, with Staphylococcus aureus infection. Breastfeeding or expressing should continue, because effective milk removal helps resolve it. NICE recommends flucloxacillin for 10-14 days if symptoms do not improve after 12-24 hours of effective milk removal, or if there is infection. A fluctuant mass suggests an abscess that needs ultrasound-guided aspiration or drainage.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('66b031e8-c7a4-5981-8aba-bd24adea1fd5', '4a2b2950-cbca-5d2e-982e-b795c033900a', 'A', 'Oral metronidazole', false, 0),
  ('1355fc38-2319-56b4-91e6-fd7f09f2d44e', '4a2b2950-cbca-5d2e-982e-b795c033900a', 'B', 'Stop breastfeeding from the affected side', false, 1),
  ('15116475-7672-5ef1-a27a-6a2b4e52a640', '4a2b2950-cbca-5d2e-982e-b795c033900a', 'C', 'Incision and drainage', false, 2),
  ('7005d20c-1135-5906-9898-7b6cb1917910', '4a2b2950-cbca-5d2e-982e-b795c033900a', 'D', 'Urgent breast clinic referral for suspected cancer', false, 3),
  ('3988917a-c919-5671-8708-c3b6b66049cb', '4a2b2950-cbca-5d2e-982e-b795c033900a', 'E', 'Continue breastfeeding or expressing from the affected breast, with oral flucloxacillin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('69adfee3-6eb3-5b62-94c0-834824ae12ea', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 52 year old woman has been recalled after routine breast screening shows a cluster of microcalcifications. What is the SINGLE most appropriate next step at the breast clinic?', 'Abnormal screening results lead to triple assessment: clinical examination, imaging (further mammographic views or ultrasound) and biopsy (stereotactic core or vacuum-assisted for calcifications). Microcalcifications may represent ductal carcinoma in situ. The NHS Breast Screening Programme offers mammography every 3 years to women aged 50-71.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1af6c8c3-7a2c-5886-9106-770db7b757a6', '69adfee3-6eb3-5b62-94c0-834824ae12ea', 'A', 'Repeat mammogram in 3 years', false, 0),
  ('39a88534-b0ac-5747-9085-aa95557b2efb', '69adfee3-6eb3-5b62-94c0-834824ae12ea', 'B', 'MRI alone', false, 1),
  ('75853190-d0d1-5695-8660-9b56524b6daa', '69adfee3-6eb3-5b62-94c0-834824ae12ea', 'C', 'Mastectomy without biopsy', false, 2),
  ('5c38f00c-87dc-534e-b6c5-cebae45ea16c', '69adfee3-6eb3-5b62-94c0-834824ae12ea', 'D', 'Reassure; microcalcifications are always benign', false, 3),
  ('51b934f7-ae50-5540-96f5-fc5b7d6341fb', '69adfee3-6eb3-5b62-94c0-834824ae12ea', 'E', 'Triple assessment including stereotactic core biopsy of the calcifications', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17f4a88d-9143-56f1-825f-407615502e9a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 48 year old woman has a biopsy confirming a 2 cm grade 2 invasive ductal carcinoma, oestrogen receptor positive and HER2 negative, with no axillary nodes on ultrasound. What is the SINGLE most appropriate surgical management?', 'Early breast cancer is usually treated with breast-conserving surgery (wide local excision) plus sentinel lymph node biopsy, followed by whole-breast radiotherapy. Mastectomy is considered for large or multifocal tumours or by patient choice. ER-positive disease is treated with adjuvant endocrine therapy (tamoxifen or an aromatase inhibitor). HER2-positive disease receives trastuzumab.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('09401ef4-64a2-5dfe-8dae-5c5a5c5cf93b', '17f4a88d-9143-56f1-825f-407615502e9a', 'A', 'Mastectomy and full axillary clearance', false, 0),
  ('ee95cf15-a9da-50b6-a216-d92eb7e9cc27', '17f4a88d-9143-56f1-825f-407615502e9a', 'B', 'Chemotherapy only', false, 1),
  ('d1a5fffe-4811-50a0-a7a9-3e36374f60a1', '17f4a88d-9143-56f1-825f-407615502e9a', 'C', 'Radiotherapy alone', false, 2),
  ('b2a964e5-ec57-5ada-b3df-5f8b273cd969', '17f4a88d-9143-56f1-825f-407615502e9a', 'D', 'Observation', false, 3),
  ('e325c2e6-55ab-536e-be7e-8f0c51d15ea2', '17f4a88d-9143-56f1-825f-407615502e9a', 'E', 'Wide local excision with sentinel lymph node biopsy, followed by radiotherapy', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8df3e4c9-9159-539d-8bfb-8b228f2f2c01', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 62 year old postmenopausal woman has had breast cancer that is ER positive. She has completed surgery and radiotherapy. Which adjuvant endocrine treatment is MOST appropriate?', 'For postmenopausal women with ER-positive breast cancer, aromatase inhibitors (anastrozole, letrozole, exemestane) are first-line adjuvant endocrine therapy, usually for 5 years or more. They cause bone loss (so DEXA monitoring and bone protection are needed) and arthralgia. Tamoxifen is used in premenopausal women and carries risks of VTE and endometrial cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b12bc99-1598-51a2-bd16-49e826f1f4a6', '8df3e4c9-9159-539d-8bfb-8b228f2f2c01', 'A', 'Goserelin alone', false, 0),
  ('ab308ded-1596-5b41-b4bb-6a03a900db50', '8df3e4c9-9159-539d-8bfb-8b228f2f2c01', 'B', 'An aromatase inhibitor (e.g. letrozole or anastrozole)', true, 1),
  ('ef2c0777-8ce0-5fbb-9005-ebbe4bfe7a6c', '8df3e4c9-9159-539d-8bfb-8b228f2f2c01', 'C', 'Trastuzumab', false, 2),
  ('2dc71da2-1a97-5dbd-abe9-4e2eca8d25fb', '8df3e4c9-9159-539d-8bfb-8b228f2f2c01', 'D', 'Tamoxifen is contraindicated postmenopause', false, 3),
  ('7b9bcce9-9cb1-585b-b5f2-990eb3e8c2c2', '8df3e4c9-9159-539d-8bfb-8b228f2f2c01', 'E', 'No endocrine therapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6dc11f85-71b8-58ea-aa1c-0193f7dc6e71', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 21 year old woman has a 2 cm smooth, firm, rubbery, highly mobile, painless breast lump. Ultrasound shows a well-defined oval solid lesion. Core biopsy confirms the diagnosis. What is the SINGLE most likely diagnosis?', 'Fibroadenomas are benign tumours, common in women under 30. They are smooth, rubbery and very mobile (''breast mouse''). After triple assessment confirms the diagnosis, they can be left alone or excised if large (over 3 cm), growing or if the patient prefers. Phyllodes tumours grow rapidly and can be malignant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2818ff07-737b-592d-a7d2-6cdd081e8550', '6dc11f85-71b8-58ea-aa1c-0193f7dc6e71', 'A', 'Breast cancer', false, 0),
  ('ba93c4a4-d853-59a7-ab18-240309055d88', '6dc11f85-71b8-58ea-aa1c-0193f7dc6e71', 'B', 'Phyllodes tumour', false, 1),
  ('5df037db-6217-5f31-97d9-92a820d3d501', '6dc11f85-71b8-58ea-aa1c-0193f7dc6e71', 'C', 'Fibroadenoma', true, 2),
  ('f9645737-3b3c-5000-aa88-5bc8be84035c', '6dc11f85-71b8-58ea-aa1c-0193f7dc6e71', 'D', 'Breast cyst', false, 3),
  ('d27f8168-29d1-54f9-a32d-25d929e39f71', '6dc11f85-71b8-58ea-aa1c-0193f7dc6e71', 'E', 'Fat necrosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e6c6664d-66bb-5ef1-aa61-735dfea59f04', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 45 year old woman has a smooth, tender, fluctuant breast lump that appeared suddenly. Ultrasound shows a simple cyst. What is the SINGLE most appropriate management?', 'Breast cysts are common in women aged 35-50 near menopause. They are smooth and fluctuant on examination, and simple on ultrasound. Symptomatic cysts can be aspirated. Bloodstained aspirate, a residual mass or recurrence needs further investigation (cytology, biopsy) to exclude malignancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b4d1a575-f9ab-51f5-aa94-6efba064f2c1', 'e6c6664d-66bb-5ef1-aa61-735dfea59f04', 'A', 'Long-term antibiotics', false, 0),
  ('d1c21aa9-a87d-57db-88b1-75c012645901', 'e6c6664d-66bb-5ef1-aa61-735dfea59f04', 'B', 'Aspiration if symptomatic; further investigation if the fluid is bloodstained or the lump persists', true, 1),
  ('abc2db54-cf16-517b-b33c-72295b77f619', 'e6c6664d-66bb-5ef1-aa61-735dfea59f04', 'C', 'Radiotherapy', false, 2),
  ('4ff2eb85-495e-56c2-9cec-b6e23f7e4c81', 'e6c6664d-66bb-5ef1-aa61-735dfea59f04', 'D', 'No assessment needed', false, 3),
  ('626fccb9-a354-508b-9867-08ee5cfd4fe9', 'e6c6664d-66bb-5ef1-aa61-735dfea59f04', 'E', 'Mastectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('846cf449-237a-5485-b89e-5919d861eeeb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 62 year old woman has had a red, scaly, eczema-like rash around her right nipple that has not improved with topical steroids for 6 weeks. The nipple itself is affected. What is the SINGLE most appropriate action?', 'Paget''s disease of the nipple is eczema-like change that starts on the nipple and spreads to the areola. It is usually associated with underlying DCIS or invasive breast cancer. Unilateral nipple eczema that does not respond to treatment needs a suspected cancer referral, with biopsy and imaging. Ordinary eczema usually affects the areola and spares the nipple, and is often bilateral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2ec9b1fb-3148-5dd6-81e1-d1231c5f0762', '846cf449-237a-5485-b89e-5919d861eeeb', 'A', 'Reassure; it is eczema', false, 0),
  ('460b65f9-816e-5fc3-8d0d-c44c6c40a638', '846cf449-237a-5485-b89e-5919d861eeeb', 'B', 'Topical antifungal', false, 1),
  ('5292243b-b0b1-5f24-91a8-0dfa0140387f', '846cf449-237a-5485-b89e-5919d861eeeb', 'C', 'Suspected cancer referral for possible Paget''s disease of the nipple', true, 2),
  ('f3bf6f88-64aa-5f68-bba4-753e00169cfd', '846cf449-237a-5485-b89e-5919d861eeeb', 'D', 'Stronger steroid cream', false, 3),
  ('c61aa3e7-de3a-54d8-8646-cfb0fb106c70', '846cf449-237a-5485-b89e-5919d861eeeb', 'E', 'Antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('37b27bf0-1ce4-582a-9264-ff37eb55d6b6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 45 year old woman has had single-duct bloodstained nipple discharge from her left breast for 1 month. There is no palpable mass. Mammogram and ultrasound show a small intraductal lesion. What is the SINGLE most likely diagnosis?', 'Intraductal papilloma is the commonest cause of bloodstained single-duct nipple discharge. It is benign but needs triple assessment to exclude malignancy. Treatment is microdochectomy (excision of the duct). Duct ectasia causes thick green or cream discharge from multiple ducts in perimenopausal women, often with nipple retraction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2f7815ad-af0c-5c07-9f04-6b6f3b9a579c', '37b27bf0-1ce4-582a-9264-ff37eb55d6b6', 'A', 'Duct ectasia', false, 0),
  ('03333c88-35c8-52d6-8e1e-7fcea99e52bf', '37b27bf0-1ce4-582a-9264-ff37eb55d6b6', 'B', 'Galactorrhoea', false, 1),
  ('9cb4c195-37a5-5394-86e7-fa36f48db31d', '37b27bf0-1ce4-582a-9264-ff37eb55d6b6', 'C', 'Intraductal papilloma', true, 2),
  ('0aeb96c5-6812-54ea-a390-fd77efaf7a18', '37b27bf0-1ce4-582a-9264-ff37eb55d6b6', 'D', 'Breast abscess', false, 3),
  ('915c7ade-fce3-5cc1-ba30-5a527cdc7e72', '37b27bf0-1ce4-582a-9264-ff37eb55d6b6', 'E', 'Paget''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17605152-c8bb-50c7-ae87-21be78904040', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 50 year old woman has a firm breast lump and a bruise after being hit by a car seatbelt 3 weeks ago. The lump is irregular and may be tethered to the skin. What is the SINGLE most appropriate management?', 'Fat necrosis follows trauma (including surgery and seatbelt injuries) and can cause a firm, irregular, tethered lump that looks like cancer clinically and on imaging. Triple assessment with biopsy is needed to confirm the diagnosis. It resolves on its own once malignancy is excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('27f4ecd4-dc27-5de6-97c2-7597b00dddf4', '17605152-c8bb-50c7-ae87-21be78904040', 'A', 'Triple assessment, because fat necrosis can mimic carcinoma', true, 0),
  ('63434f38-dfc7-5f28-a82a-43a6ab3ed2f8', '17605152-c8bb-50c7-ae87-21be78904040', 'B', 'Mastectomy', false, 1),
  ('19d82ac4-21cb-55ad-b697-2b44f001bd67', '17605152-c8bb-50c7-ae87-21be78904040', 'C', 'Reassure without assessment', false, 2),
  ('ac779583-7dc1-5c13-80a7-6a879df84f7f', '17605152-c8bb-50c7-ae87-21be78904040', 'D', 'Antibiotics', false, 3),
  ('028f791e-07bc-54cc-bd0b-d77c6ae23078', '17605152-c8bb-50c7-ae87-21be78904040', 'E', 'Incision and drainage', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('315d9316-2122-54a9-9676-bc2597d8cd2f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 16 year old boy has a tender, firm, disc-like swelling behind both nipples for 4 months. He is otherwise well and his testicular examination is normal. What is the SINGLE most likely diagnosis?', 'Gynaecomastia (enlargement of male glandular breast tissue) is common in puberty and usually resolves within 6 months to 2 years. Pathological causes include drugs (spironolactone, digoxin, anabolic steroids, cannabis), liver disease, hypogonadism, Klinefelter syndrome and testicular tumours (beta-hCG). Unilateral, hard, eccentric lumps in older men need assessment for breast cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d87b081e-da92-50ac-81d4-8c7c4a2c42f1', '315d9316-2122-54a9-9676-bc2597d8cd2f', 'A', 'Physiological pubertal gynaecomastia', true, 0),
  ('88e70791-9067-5a77-86bd-646b2e9758b1', '315d9316-2122-54a9-9676-bc2597d8cd2f', 'B', 'Testicular tumour', false, 1),
  ('6a3d1f36-bde0-53ba-85e0-b32d0491995e', '315d9316-2122-54a9-9676-bc2597d8cd2f', 'C', 'Prolactinoma', false, 2),
  ('6e5bbe81-cbb8-56b1-8096-f92b33c8e6b0', '315d9316-2122-54a9-9676-bc2597d8cd2f', 'D', 'Breast cancer', false, 3),
  ('696a3858-bfff-569e-8375-7cc968a7a603', '315d9316-2122-54a9-9676-bc2597d8cd2f', 'E', 'Klinefelter syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a740618-d11b-5bdb-b65e-51aaf977069b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 38 year old woman has had cyclical bilateral breast pain and lumpiness before her periods for 6 months. Examination shows generalised nodularity with no discrete mass. What is the SINGLE most appropriate management?', 'Cyclical mastalgia is common and linked to hormonal changes. It is not a sign of cancer. Management is reassurance, a supportive bra, and simple analgesia (paracetamol, topical or oral NSAIDs). Specialist drugs (danazol, tamoxifen) are only used for severe resistant cases. Any discrete lump needs assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6f63a8c5-ddcf-5ff2-903e-68a3cc5064b0', '2a740618-d11b-5bdb-b65e-51aaf977069b', 'A', 'Antibiotics', false, 0),
  ('d2314d27-2ee4-5a7c-ab30-8af895eb9df7', '2a740618-d11b-5bdb-b65e-51aaf977069b', 'B', 'Reassurance, a well-fitting bra and simple analgesia (topical NSAIDs)', true, 1),
  ('242720f9-2c0a-54c8-9210-7a4ab1e0800e', '2a740618-d11b-5bdb-b65e-51aaf977069b', 'C', 'Tamoxifen first-line', false, 2),
  ('592b4ca0-f081-52e5-8608-9bbdd5ce0e4a', '2a740618-d11b-5bdb-b65e-51aaf977069b', 'D', 'Mastectomy', false, 3),
  ('8811f2bd-02c9-50e0-8572-78a17137342a', '2a740618-d11b-5bdb-b65e-51aaf977069b', 'E', 'Urgent cancer referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2445a73a-c487-5cc1-9879-f0dcda40c150', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 27 year old woman has a small area of redness on her right breast for 4 weeks. A course of antibiotics, given 3 weeks ago, slightly improved the redness. She has had similar episodes before. She has a red superficial tender lump at the edge of her right areola and 0.5 mL of green fluid is aspirated. Which is the most likely diagnosis?', 'Recurrent periareolar inflammation with a tender lump and discharge in a young woman, often a smoker, is periductal mastitis. It is associated with smoking and can cause recurrent abscesses and mammary duct fistulas. Treatment is antibiotics (such as co-amoxiclav), drainage of any abscess, stopping smoking, and sometimes excision of the affected ducts.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e405bfee-3ff3-549b-a390-336585acb914', '2445a73a-c487-5cc1-9879-f0dcda40c150', 'A', 'Breast abscess', false, 0),
  ('ef8e80f0-2c9e-53ff-8fc7-eb2c09a383d9', '2445a73a-c487-5cc1-9879-f0dcda40c150', 'B', 'Breast cancer', false, 1),
  ('91908a87-396f-5f27-bd11-6c8f175bc25e', '2445a73a-c487-5cc1-9879-f0dcda40c150', 'C', 'Duct papilloma', false, 2),
  ('a0a9b372-b902-5136-9f76-2a9c382b268f', '2445a73a-c487-5cc1-9879-f0dcda40c150', 'D', 'Paget’s disease', false, 3),
  ('01bdfe9b-ffb1-5a72-afbb-0b9d3bf8b068', '2445a73a-c487-5cc1-9879-f0dcda40c150', 'E', 'Periductal mastitis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('819e109b-18c9-5705-a4cd-ea9318793c79', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 71 year old man with metastatic prostate cancer presents with 3 days of worsening thoracic back pain, worse when lying flat, and new weakness in both legs. On examination there is reduced power in both legs and a sensory level at T10. He has not passed urine for 8 hours. What is the SINGLE most appropriate investigation?', 'This is metastatic spinal cord compression, an oncological emergency. NICE recommends MRI of the whole spine, as soon as possible and within 24 hours, because there may be lesions at more than one level. Give dexamethasone 16 mg straight away (with PPI cover) and refer urgently to oncology and spinal surgery for radiotherapy or decompression. Plain X-rays and bone scans do not show the cord.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cfa3d7af-9fa9-55b1-86dc-5a7efcc17f7e', '819e109b-18c9-5705-a4cd-ea9318793c79', 'A', 'Isotope bone scan', false, 0),
  ('e36577be-6d61-511e-85e7-2ba93e630578', '819e109b-18c9-5705-a4cd-ea9318793c79', 'B', 'Urgent MRI of the whole spine', true, 1),
  ('4d4289b6-33a9-5f6f-8b1e-2df0d96752b4', '819e109b-18c9-5705-a4cd-ea9318793c79', 'C', 'CT scan of the abdomen and pelvis', false, 2),
  ('464fa384-dd19-5e59-90ac-cac16cbfe58a', '819e109b-18c9-5705-a4cd-ea9318793c79', 'D', 'Plain X-ray of the thoracic spine', false, 3),
  ('e8d1ee11-2e0e-567c-94f5-62aa4d0faf67', '819e109b-18c9-5705-a4cd-ea9318793c79', 'E', 'Serum PSA', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('eb520afa-2324-5120-ad2a-7b02f361b4eb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 52 year old woman had her first cycle of chemotherapy for breast cancer 9 days ago. She now has a temperature of 38.4°C and feels shivery. Her heart rate is 108 beats/minute and blood pressure 112/70 mmHg. Bloods have been taken. What is the SINGLE most appropriate management?', 'Fever after chemotherapy (typically 7-14 days, at the neutrophil nadir) is neutropenic sepsis until proven otherwise. NICE recommends empirical IV piperacillin-tazobactam within 1 hour of arrival, without waiting for the neutrophil count. Neutropenic sepsis is defined as a neutrophil count of 0.5 x 10^9/L or less with a temperature above 38°C or signs of sepsis. Risk is then assessed (MASCC score) to guide later management.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4170412c-e7cd-56f2-8a20-0206d416568d', 'eb520afa-2324-5120-ad2a-7b02f361b4eb', 'A', 'Give granulocyte colony-stimulating factor only', false, 0),
  ('2d2b131e-7376-5d16-bf2e-7f020168f23b', 'eb520afa-2324-5120-ad2a-7b02f361b4eb', 'B', 'Oral paracetamol and review tomorrow', false, 1),
  ('cac191e2-2c9c-5389-9d5e-aa23a2789a73', 'eb520afa-2324-5120-ad2a-7b02f361b4eb', 'C', 'IV piperacillin-tazobactam within 1 hour, without waiting for the neutrophil count', true, 2),
  ('54b7b835-3460-5917-9d9b-cb03fac8b7a2', 'eb520afa-2324-5120-ad2a-7b02f361b4eb', 'D', 'Oral amoxicillin at home', false, 3),
  ('2f757d4e-f3b9-576c-b564-3bad2130e23b', 'eb520afa-2324-5120-ad2a-7b02f361b4eb', 'E', 'Wait for the neutrophil count before deciding on antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8118573c-ce1e-5566-b7b8-c459d80726d2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 63 year old man with lung cancer has 2 weeks of swelling of his face and neck, which is worse when he bends forward or lies down, with breathlessness and headache. His neck veins are distended and there are dilated veins on his upper chest wall. What is the SINGLE most likely diagnosis?', 'Facial and arm swelling, distended non-pulsatile neck veins and dilated collateral chest wall veins suggest superior vena cava obstruction, most often from lung cancer (especially small cell) or lymphoma. Pemberton''s sign may be positive. Management is to sit the patient up, give dexamethasone and arrange urgent oncology review for endovascular stenting and treatment of the cancer, such as radiotherapy or chemotherapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
