  ('9a34cb68-671e-5625-89a9-d0e92e214814', '8118573c-ce1e-5566-b7b8-c459d80726d2', 'A', 'Angioedema', false, 0),
  ('3e7f7a0f-aa19-5709-9e9e-e154e24f17e3', '8118573c-ce1e-5566-b7b8-c459d80726d2', 'B', 'Pericardial tamponade', false, 1),
  ('b0e4b7c9-e1f3-5b04-88bd-1415cd57ba9a', '8118573c-ce1e-5566-b7b8-c459d80726d2', 'C', 'Heart failure', false, 2),
  ('3988aaa3-a8e5-5a67-8207-4bae319e6d00', '8118573c-ce1e-5566-b7b8-c459d80726d2', 'D', 'Thyroid goitre', false, 3),
  ('01836bfa-5a87-576f-a109-17e086d003d9', '8118573c-ce1e-5566-b7b8-c459d80726d2', 'E', 'Superior vena cava obstruction', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('85b58e24-0cdd-54d1-b918-9ccc718704cf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 66 year old man who smokes has had hoarseness of voice for 4 weeks with no cold or upper respiratory infection. He has no difficulty swallowing and no neck lump. What is the SINGLE most appropriate action?', 'Persistent unexplained hoarseness in people aged 45 and over needs a suspected cancer referral for laryngeal cancer (NICE NG12). Hoarseness can also come from recurrent laryngeal nerve palsy caused by apical lung cancer, so NICE recommends an urgent chest X-ray for people with persistent hoarseness. Smoking and alcohol are major risk factors.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('46210146-e250-5b02-a956-36b29f60bd25', '85b58e24-0cdd-54d1-b918-9ccc718704cf', 'A', 'Prescribe oral antibiotics', false, 0),
  ('2c32407b-609c-5a30-90a4-5cfb1fcb8772', '85b58e24-0cdd-54d1-b918-9ccc718704cf', 'B', 'Reassure and review in 3 months', false, 1),
  ('14c90db3-72c7-5eef-ace1-8fa05b99e449', '85b58e24-0cdd-54d1-b918-9ccc718704cf', 'C', 'Suspected cancer pathway (two-week wait) referral to ENT, with a chest X-ray', true, 2),
  ('b55c2b54-1fe7-5bb4-8d05-b9d5e874c9d4', '85b58e24-0cdd-54d1-b918-9ccc718704cf', 'D', 'Prescribe a PPI and review in 2 months', false, 3),
  ('c1d4ac52-0db7-5eac-b128-68b937aa08be', '85b58e24-0cdd-54d1-b918-9ccc718704cf', 'E', 'Voice therapy referral only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d065a87a-dd38-5471-a692-7198b6b2edda', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 48 year old woman has had chemotherapy for lymphoma (first cycle 2 days ago). She is now oliguric, with potassium 6.8 mmol/L, phosphate 2.6 mmol/L, calcium 1.8 mmol/L and uric acid 0.72 mmol/L. What is the SINGLE most likely diagnosis?', 'Tumour lysis syndrome follows treatment of rapidly proliferating cancers (high-grade lymphoma, leukaemia). Release of cell contents causes hyperkalaemia, hyperphosphataemia, hypocalcaemia, hyperuricaemia and AKI. Prevention is IV hydration and allopurinol, or rasburicase in high-risk patients. Established TLS needs aggressive fluids, rasburicase, treatment of hyperkalaemia and possibly dialysis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('31553bee-5cec-54ec-b031-8a0d06e7e9c0', 'd065a87a-dd38-5471-a692-7198b6b2edda', 'A', 'Neutropenic sepsis', false, 0),
  ('2a46fc0b-974b-5d35-a369-d04282b54748', 'd065a87a-dd38-5471-a692-7198b6b2edda', 'B', 'Addison''s disease', false, 1),
  ('88c46391-889d-5695-9946-f8be8da489ad', 'd065a87a-dd38-5471-a692-7198b6b2edda', 'C', 'Tumour lysis syndrome', true, 2),
  ('5be60e6d-5c89-5a47-b42e-703bb63db2b7', 'd065a87a-dd38-5471-a692-7198b6b2edda', 'D', 'Hypercalcaemia of malignancy', false, 3),
  ('9fcf7d04-327e-5bbd-bcbb-c1c28b54aa49', 'd065a87a-dd38-5471-a692-7198b6b2edda', 'E', 'SIADH', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5fe15450-0ab0-56ac-81ff-4fa4229324b2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 66 year old woman had breast cancer treated 5 years ago. She now has a dry cough and progressive breathlessness. A chest X-ray shows multiple round lesions in both lungs (''cannonball''). What is the SINGLE most likely diagnosis?', 'Multiple well-defined round lesions throughout both lungs suggest haematogenous spread of metastases (breast, renal, colorectal, sarcoma, testicular, melanoma). Breast cancer commonly spreads to bone, lung, liver and brain, sometimes years after treatment. Biopsy confirms it, and treatment is systemic therapy guided by receptor status.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
