  ('e121195f-587f-512e-b165-f9ac39c30646', '5fe15450-0ab0-56ac-81ff-4fa4229324b2', 'A', 'Pneumonia', false, 0),
  ('36f4e804-fc96-547b-aeea-5438975e74eb', '5fe15450-0ab0-56ac-81ff-4fa4229324b2', 'B', 'Tuberculosis', false, 1),
  ('14998f13-9267-5012-b18f-8a6ea9d06f49', '5fe15450-0ab0-56ac-81ff-4fa4229324b2', 'C', 'Sarcoidosis', false, 2),
  ('7f66cecd-8ea0-5357-b83c-f9f5b48cef4e', '5fe15450-0ab0-56ac-81ff-4fa4229324b2', 'D', 'Pulmonary metastases', true, 3),
  ('568d9b42-5bbb-5954-8f2b-2e7d76b3a98a', '5fe15450-0ab0-56ac-81ff-4fa4229324b2', 'E', 'Primary lung cancer', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9558ea99-c249-52fa-bb6e-91688e761d7f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 60 year old man with known prostate cancer has back pain. His PSA has risen to 150. Which investigation is MOST appropriate to look for bone metastases?', 'Prostate cancer commonly spreads to bone, causing sclerotic (osteoblastic) metastases. Isotope bone scans have traditionally been used for staging, and PSMA PET-CT is increasingly used. Treatment of metastatic disease is androgen deprivation therapy (LHRH agonists, with initial anti-androgen cover to prevent flare) plus additional agents. Bone pain can be treated with radiotherapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df056bd5-0d6e-5d72-9716-7e22b3f4c510', '9558ea99-c249-52fa-bb6e-91688e761d7f', 'A', 'Plain chest X-ray', false, 0),
  ('5340ba7b-ebc1-5d4c-b868-25f05b04d5d6', '9558ea99-c249-52fa-bb6e-91688e761d7f', 'B', 'Ultrasound abdomen', false, 1),
  ('33111daf-97a7-59be-ac64-46041c0e1c22', '9558ea99-c249-52fa-bb6e-91688e761d7f', 'C', 'Isotope bone scan (or PSMA PET-CT)', true, 2),
  ('0effc9fb-2f13-5210-97fa-777d1b677e5b', '9558ea99-c249-52fa-bb6e-91688e761d7f', 'D', 'Lumbar puncture', false, 3),
  ('0d7d1b98-6706-5069-ab1f-9dc2b301863a', '9558ea99-c249-52fa-bb6e-91688e761d7f', 'E', 'Serum calcium only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7e4f0c83-6323-582e-9e45-719597c46ae1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 68 year old man with metastatic prostate cancer is starting goserelin (an LHRH agonist). He is also prescribed bicalutamide for the first few weeks. What is the SINGLE main reason for this?', 'LHRH agonists (goserelin, leuprorelin) initially stimulate LH release, causing a surge in testosterone before suppression. In prostate cancer, this ''tumour flare'' can worsen bone pain or cause spinal cord compression or urinary obstruction. An anti-androgen (bicalutamide or cyproterone) is given for the first few weeks to prevent it. LHRH antagonists (degarelix) do not cause flare.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('79d55df4-a10d-54d3-8509-6f8e350b119c', '7e4f0c83-6323-582e-9e45-719597c46ae1', 'A', 'To reduce nausea', false, 0),
  ('f7f2ebfa-c928-570e-81e2-09422c9427df', '7e4f0c83-6323-582e-9e45-719597c46ae1', 'B', 'To prevent tumour flare from the initial testosterone surge', true, 1),
  ('feb8c5e5-b741-58ad-a839-998c09c445bc', '7e4f0c83-6323-582e-9e45-719597c46ae1', 'C', 'To prevent osteoporosis', false, 2),
  ('006ff8a5-c4d9-5de5-a0b9-01296a6b8ec3', '7e4f0c83-6323-582e-9e45-719597c46ae1', 'D', 'To treat anaemia', false, 3),
  ('360ea531-464b-5375-aa42-4a6a6a81140c', '7e4f0c83-6323-582e-9e45-719597c46ae1', 'E', 'To reduce hot flushes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a3f9847-a966-5b2c-87c4-922d0dedfea5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 35 year old woman is starting chemotherapy and asks about side effects. Which chemotherapy agent is MOST associated with cardiotoxicity (cardiomyopathy)?', 'Anthracyclines (doxorubicin) cause dose-dependent cardiomyopathy, so echocardiography is monitored. Other key toxicities: cisplatin (nephrotoxicity, ototoxicity, neuropathy), vincristine (peripheral neuropathy), bleomycin (pulmonary fibrosis), methotrexate (myelosuppression, mucositis, liver), cyclophosphamide (haemorrhagic cystitis) and trastuzumab (reversible cardiomyopathy).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ed142496-9057-5e76-87b3-11a8b804933e', '5a3f9847-a966-5b2c-87c4-922d0dedfea5', 'A', 'Doxorubicin', true, 0),
  ('9ca57769-21e3-556e-999c-e51e25a64323', '5a3f9847-a966-5b2c-87c4-922d0dedfea5', 'B', 'Methotrexate', false, 1),
  ('36cf6dee-bf27-57ab-bf17-97cb2e53e4b0', '5a3f9847-a966-5b2c-87c4-922d0dedfea5', 'C', 'Bleomycin', false, 2),
  ('ecd8ce2a-da84-53ca-8713-b699537545f6', '5a3f9847-a966-5b2c-87c4-922d0dedfea5', 'D', 'Cisplatin', false, 3),
  ('d951eb88-01f2-5ef7-aa01-e253031b8280', '5a3f9847-a966-5b2c-87c4-922d0dedfea5', 'E', 'Vincristine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8ed97851-5399-50c4-815d-a5374ca7319f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 56 year old woman is starting cisplatin-based chemotherapy. Which antiemetic regimen is MOST appropriate to prevent highly emetogenic chemotherapy-induced nausea and vomiting?', 'Cisplatin is highly emetogenic. Prevention uses a triple (or quadruple with olanzapine) regimen: a 5-HT3 antagonist, dexamethasone and an NK1 receptor antagonist (aprepitant). Delayed nausea (24-120 hours) is treated with dexamethasone and aprepitant. Anticipatory nausea may respond to benzodiazepines.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e0a8c377-4199-585d-a5e0-ae7daadcb84a', '8ed97851-5399-50c4-815d-a5374ca7319f', 'A', 'A 5-HT3 antagonist (ondansetron) plus dexamethasone plus an NK1 antagonist (aprepitant)', true, 0),
  ('a025db38-ce23-5224-91ca-c58526531490', '8ed97851-5399-50c4-815d-a5374ca7319f', 'B', 'Cyclizine alone', false, 1),
  ('50bb6ad1-3ece-5f2e-a1ff-e7653c1c1856', '8ed97851-5399-50c4-815d-a5374ca7319f', 'C', 'Metoclopramide alone', false, 2),
  ('f90c0042-e613-50c6-9348-55e3a82b7ae5', '8ed97851-5399-50c4-815d-a5374ca7319f', 'D', 'Haloperidol alone', false, 3),
  ('805b55bf-e976-56b4-8b4f-700b529b5798', '8ed97851-5399-50c4-815d-a5374ca7319f', 'E', 'No prophylaxis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5cc4dccd-6c8b-5baa-b81b-e0b073b3763c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 62 year old man with small cell lung cancer is confused and has nausea and polyuria. His adjusted calcium is 3.2 mmol/L and PTH is suppressed. What is the SINGLE most likely mechanism of hypercalcaemia?', 'Hypercalcaemia of malignancy is mainly caused by PTHrP secretion (especially squamous cell carcinomas of the lung, head and neck and breast) or by osteolytic bone metastases (breast, myeloma). PTH is suppressed. Treatment is IV fluids then IV bisphosphonates, or denosumab if refractory. It indicates a poor prognosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0ff3243b-1ed9-5c39-8245-733d3a4f66fe', '5cc4dccd-6c8b-5baa-b81b-e0b073b3763c', 'A', 'PTHrP secretion or bone metastases (humoral or osteolytic hypercalcaemia of malignancy)', true, 0),
  ('4add1b6f-0075-5e7b-8c06-253d83284f93', '5cc4dccd-6c8b-5baa-b81b-e0b073b3763c', 'B', 'Vitamin D deficiency', false, 1),
  ('2ef123cd-d054-55e1-85f2-9b51abd3ca4e', '5cc4dccd-6c8b-5baa-b81b-e0b073b3763c', 'C', 'Thiazide use', false, 2),
  ('c90a3241-5576-507e-b7eb-941262a59fc4', '5cc4dccd-6c8b-5baa-b81b-e0b073b3763c', 'D', 'Primary hyperparathyroidism', false, 3),
  ('dd249457-5c9b-5b51-a5da-dea643c62edd', '5cc4dccd-6c8b-5baa-b81b-e0b073b3763c', 'E', 'Excess calcium intake', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('40e1579d-c32e-5598-b301-2f41ef2ebb42', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 58 year old woman has had progressive dyspnoea for 3 weeks and has a known breast cancer. A chest X-ray shows a large right pleural effusion. Cytology confirms malignant cells. The effusion recurs quickly after drainage. What is the SINGLE most appropriate management?', 'Recurrent symptomatic malignant pleural effusion is managed with talc pleurodesis (via chest drain or thoracoscopy) or an indwelling pleural catheter for drainage at home. The choice depends on lung re-expansion, prognosis and patient preference. A trapped lung favours an IPC.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
