  ('84e5f006-1c90-595d-b635-bcf1935a52f1', '40e1579d-c32e-5598-b301-2f41ef2ebb42', 'A', 'Talc pleurodesis or an indwelling pleural catheter', true, 0),
  ('40478a79-543f-5413-919f-49982e8dc75a', '40e1579d-c32e-5598-b301-2f41ef2ebb42', 'B', 'Repeated large-volume aspirations every week', false, 1),
  ('60508c5f-9bf7-51a0-85b7-b1f1b046492b', '40e1579d-c32e-5598-b301-2f41ef2ebb42', 'C', 'Surgical lobectomy', false, 2),
  ('274a965b-c690-58d2-84bc-d06d7cb12e6a', '40e1579d-c32e-5598-b301-2f41ef2ebb42', 'D', 'Antibiotics', false, 3),
  ('e84db5ed-9a10-5cd8-b2c1-f120c0bb19d0', '40e1579d-c32e-5598-b301-2f41ef2ebb42', 'E', 'Observation only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9b165cad-63af-58ef-a659-7ac0f02ef2c4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 70 year old man who smokes has had hoarseness, a persistent cough and weight loss. Examination shows a right-sided Horner''s syndrome and wasting of the small muscles of his right hand. What is the SINGLE most likely diagnosis?', 'A Pancoast (superior sulcus) tumour at the lung apex invades the brachial plexus (C8/T1: hand muscle wasting and arm pain), the sympathetic chain (Horner''s syndrome: ptosis, miosis, anhidrosis) and sometimes the recurrent laryngeal nerve (hoarseness). It is usually NSCLC (squamous). Staging is with CT and MRI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
