  ('543f1ca6-fcf9-590e-93f8-90006422366c', '9b165cad-63af-58ef-a659-7ac0f02ef2c4', 'A', 'Pancoast tumour (apical lung cancer)', true, 0),
  ('e1892c37-2312-57af-89e1-f7f150a099bf', '9b165cad-63af-58ef-a659-7ac0f02ef2c4', 'B', 'Cervical rib', false, 1),
  ('42382546-78b3-5d6d-841b-d6ab979d120f', '9b165cad-63af-58ef-a659-7ac0f02ef2c4', 'C', 'Carpal tunnel syndrome', false, 2),
  ('c288a8e0-9f42-516d-bb59-5caa63fd5214', '9b165cad-63af-58ef-a659-7ac0f02ef2c4', 'D', 'Motor neurone disease', false, 3),
  ('bedc4124-6c50-5b8e-b46b-2dd4c0b39025', '9b165cad-63af-58ef-a659-7ac0f02ef2c4', 'E', 'Syringomyelia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8fd9f533-f210-5fec-92ee-54b130984feb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 72 year old woman has had progressive abdominal distension, early satiety and weight loss. CT shows bilateral complex ovarian masses with ascites and omental ''caking''. CA-125 is 1,200. What is the SINGLE most likely diagnosis?', 'Epithelial ovarian cancer often presents late with bloating, early satiety and ascites. Risk factors include BRCA1/2, Lynch syndrome, nulliparity and endometriosis, while the COCP is protective. The Risk of Malignancy Index (RMI = ultrasound score x menopausal status x CA-125) guides referral. Management is cytoreductive surgery and platinum-based chemotherapy, with PARP inhibitors for BRCA-positive disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
