insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3852bfbc-6965-5678-a716-ab244fce6755', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 45 year old man has a painless lump in his neck for 2 months. He smokes and drinks heavily. He has a 3 cm firm, non-tender lymph node in the left upper neck and a hoarse voice. What is the SINGLE most appropriate action?', 'NICE NG12 recommends a suspected cancer referral for head and neck cancer for an unexplained neck lump in people aged 45 and over, or a persistent neck lump at any age, plus persistent oral ulceration or hoarseness. Smoking, alcohol and HPV (oropharyngeal) are risk factors. Assessment is by examination, nasendoscopy, ultrasound-guided FNA and imaging. Excision biopsy is avoided before specialist assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
