  ('69fa4f9b-017e-5064-aae6-3c95657ce0a5', '3852bfbc-6965-5678-a716-ab244fce6755', 'A', 'Reassure and review in 6 months', false, 0),
  ('a7b81b40-23ef-5288-ad3d-ea473cde66e9', '3852bfbc-6965-5678-a716-ab244fce6755', 'B', 'Excision biopsy in the GP surgery', false, 1),
  ('ffc21491-f6ad-541d-9717-f7c5c9688e9c', '3852bfbc-6965-5678-a716-ab244fce6755', 'C', 'Suspected cancer pathway (two-week wait) referral to ENT (head and neck)', true, 2),
  ('ad623f27-03b8-561c-8499-527280e15ee9', '3852bfbc-6965-5678-a716-ab244fce6755', 'D', 'Ultrasound in 3 months', false, 3),
  ('3d273027-ef3f-52bf-9d7b-e499a2a2f638', '3852bfbc-6965-5678-a716-ab244fce6755', 'E', 'Oral antibiotics for 4 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f805d065-e6aa-5dd2-a2ef-4580f0cef6d6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 54 year old woman with a history of breast cancer treated with tamoxifen for 3 years has postmenopausal bleeding. What is the SINGLE most important concern?', 'Tamoxifen (a selective oestrogen receptor modulator) is anti-oestrogenic in breast tissue but partly oestrogenic in the endometrium, increasing the risk of endometrial hyperplasia and cancer. Postmenopausal bleeding on tamoxifen needs urgent investigation (TVUS and hysteroscopy with biopsy). Tamoxifen also increases VTE risk. Aromatase inhibitors are used in postmenopausal women and cause bone loss.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
