  ('67dea40f-f52d-5156-ac36-f2eeab1ced1c', 'f805d065-e6aa-5dd2-a2ef-4580f0cef6d6', 'A', 'Ovarian cancer only', false, 0),
  ('95fcca9e-6141-5fc9-b924-48a17ac59bca', 'f805d065-e6aa-5dd2-a2ef-4580f0cef6d6', 'B', 'Cervical ectropion', false, 1),
  ('8e71b290-c7ab-58aa-aa9f-fd08a9e38862', 'f805d065-e6aa-5dd2-a2ef-4580f0cef6d6', 'C', 'No concern', false, 2),
  ('ced66255-d362-5ee6-879e-cdd7a8fe2c32', 'f805d065-e6aa-5dd2-a2ef-4580f0cef6d6', 'D', 'Atrophic vaginitis only', false, 3),
  ('48bde808-64bd-5b78-993c-e25ceecc3088', 'f805d065-e6aa-5dd2-a2ef-4580f0cef6d6', 'E', 'Endometrial hyperplasia or cancer (tamoxifen has a partial oestrogenic effect on the endometrium)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7e973f3a-4b31-5ccd-a532-24acffbc2e6c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 22 year old man has a painless testicular lump. Ultrasound confirms a solid testicular tumour. Before orchidectomy, what is the SINGLE most appropriate step to discuss?', 'Fertility preservation by sperm banking should be offered before orchidectomy and chemotherapy or radiotherapy. Tumour markers (AFP, beta-hCG, LDH) are measured before and after orchidectomy for staging and follow-up. A CT of the chest, abdomen and pelvis is done for staging. Testicular cancer has excellent cure rates even with metastases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
