  ('f571f1a5-5779-5956-95e7-d01875e6d0cf', '7e973f3a-4b31-5ccd-a532-24acffbc2e6c', 'A', 'Testosterone therapy', false, 0),
  ('345dc332-4ed4-55d1-ad11-919676b2df02', '7e973f3a-4b31-5ccd-a532-24acffbc2e6c', 'B', 'Testicular biopsy', false, 1),
  ('7c497b86-63ad-51c9-894e-6ab4af6c5592', '7e973f3a-4b31-5ccd-a532-24acffbc2e6c', 'C', 'Wait for 3 months', false, 2),
  ('038901af-d278-5e69-afec-73a8633ada73', '7e973f3a-4b31-5ccd-a532-24acffbc2e6c', 'D', 'Sperm banking (fertility preservation) and tumour markers', true, 3),
  ('8d4b8ae5-4eae-58a9-b54e-bfc8e5a770dd', '7e973f3a-4b31-5ccd-a532-24acffbc2e6c', 'E', 'Vasectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2032edfb-3d11-5be0-82b8-fd4a99b100cc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 66 year old man presents with fatigue, weight loss and night sweats. CT shows widespread lymphadenopathy and a mediastinal mass. Which investigation is MOST appropriate to establish the diagnosis?', 'Lymphoma diagnosis needs adequate tissue to assess architecture and immunohistochemistry, so an excision or core biopsy is preferred. FNA alone is not enough. PET-CT is used for staging and response assessment. LDH, beta-2 microglobulin and HIV and hepatitis serology are part of the workup.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
