  ('dd63511b-8cc2-58f9-a46f-cbd0fb3bcc9b', '2032edfb-3d11-5be0-82b8-fd4a99b100cc', 'A', 'Serum LDH', false, 0),
  ('fffe71f5-1be6-5930-9abb-d7474a83acb2', '2032edfb-3d11-5be0-82b8-fd4a99b100cc', 'B', 'Bone marrow aspirate only', false, 1),
  ('f0feb0a1-49f9-56f0-8372-f1c4a126aeba', '2032edfb-3d11-5be0-82b8-fd4a99b100cc', 'C', 'PET-CT alone', false, 2),
  ('db3056f9-e13d-598b-be5e-1c8051b64c86', '2032edfb-3d11-5be0-82b8-fd4a99b100cc', 'D', 'Excision (or core) biopsy of a lymph node', true, 3),
  ('55735740-fab3-513e-ad91-747177a3bc9d', '2032edfb-3d11-5be0-82b8-fd4a99b100cc', 'E', 'FNA cytology alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('09862d1f-194b-5f5a-a20b-1f9dc6213104', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 58 year old woman with metastatic colorectal cancer is offered systemic therapy. Her tumour is RAS wild-type. Which targeted therapy may be added to chemotherapy?', 'Anti-EGFR monoclonal antibodies (cetuximab, panitumumab) are effective in RAS wild-type metastatic colorectal cancer, but not in RAS-mutant tumours. Bevacizumab (anti-VEGF) is another option. Mismatch repair deficient tumours respond to immune checkpoint inhibitors such as pembrolizumab. Molecular testing guides treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
