  ('b0823b53-5f00-53f7-bb67-4939a03c65a6', '09862d1f-194b-5f5a-a20b-1f9dc6213104', 'A', 'Anti-EGFR antibody (cetuximab or panitumumab)', true, 0),
  ('f4326825-5c34-5f53-a188-434a5916d1f1', '09862d1f-194b-5f5a-a20b-1f9dc6213104', 'B', 'Rituximab', false, 1),
  ('0f00f1f7-7150-5b15-810a-2c130dd58d1c', '09862d1f-194b-5f5a-a20b-1f9dc6213104', 'C', 'Tamoxifen', false, 2),
  ('b4e61587-a53a-5d9f-82fd-f823b4191e89', '09862d1f-194b-5f5a-a20b-1f9dc6213104', 'D', 'Imatinib', false, 3),
  ('eeb0be1c-ac57-525a-87ec-4af8e4f825df', '09862d1f-194b-5f5a-a20b-1f9dc6213104', 'E', 'Trastuzumab', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c6f51e0a-257d-56bf-b07e-77f2ebcc38b9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 65 year old man has had worsening localised lumbar back pain and is seen in the Emergency Department. He.is has noted increasing difficultly in passing urine for last 6 hours. He has multiple myeloma. He has numbness of his skin at waist level. Which is the most appropriate investigation?', 'Back pain, new urinary difficulty and a sensory level in a patient with myeloma suggest metastatic (malignant) spinal cord compression. Urgent MRI of the spine (ideally whole spine) within 24 hours is the investigation of choice, with dexamethasone and urgent oncology referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2e348663-a1c2-5e66-bc8a-927c4e9f96a4', 'c6f51e0a-257d-56bf-b07e-77f2ebcc38b9', 'A', 'Electromyogram', false, 0),
  ('896a8113-5001-584d-8ffa-7e43dc620765', 'c6f51e0a-257d-56bf-b07e-77f2ebcc38b9', 'B', 'Lumbar X-ray', false, 1),
  ('8fe9a58a-990e-5f1c-8664-4a5250dffa73', 'c6f51e0a-257d-56bf-b07e-77f2ebcc38b9', 'C', 'MRI scan of lumbar spine', true, 2),
  ('fedc9f5d-85f4-56af-b969-f819f6ce7696', 'c6f51e0a-257d-56bf-b07e-77f2ebcc38b9', 'D', 'Myelogram', false, 3),
  ('54b34e8b-cf1f-5481-bc77-068746ca1a31', 'c6f51e0a-257d-56bf-b07e-77f2ebcc38b9', 'E', 'Nerve conduction studies', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f481a6d1-ff11-51fe-ac63-8b0522965b5a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 63 year old man presents with 40 minutes of crushing central chest pain radiating to his jaw, with sweating and nausea. His heart rate is 52 beats/minute. A 12-lead ECG shows 3 mm ST elevation in leads II, III and aVF with reciprocal ST depression in leads I and aVL. Which coronary artery is MOST likely to be occluded?', 'ST elevation in the inferior leads (II, III, aVF) indicates an inferior STEMI, most often due to occlusion of the right coronary artery (RCA). The bradycardia supports this, because the RCA supplies the sinoatrial node in about 60% of people and the atrioventricular node in about 90%. The LAD is linked to anterior changes (V1-V4), the circumflex to lateral changes (I, aVL, V5-V6), and left main stem occlusion to widespread changes with ST elevation in aVR.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fd698665-a419-521d-9251-41c9bf609187', 'f481a6d1-ff11-51fe-ac63-8b0522965b5a', 'A', 'Right coronary artery', true, 0),
  ('28070f01-d4aa-508d-94b3-7c3277a638a7', 'f481a6d1-ff11-51fe-ac63-8b0522965b5a', 'B', 'Left circumflex artery', false, 1),
  ('c2447c83-a0a3-50ea-863a-fb54b937662f', 'f481a6d1-ff11-51fe-ac63-8b0522965b5a', 'C', 'Left anterior descending artery', false, 2),
  ('1b6d96ef-3f4a-5db6-8f8b-317277dac072', 'f481a6d1-ff11-51fe-ac63-8b0522965b5a', 'D', 'Left main stem', false, 3),
  ('04e3600a-a0fc-5188-96ef-e3a5471a0441', 'f481a6d1-ff11-51fe-ac63-8b0522965b5a', 'E', 'Obtuse marginal artery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ad4fadcd-dbeb-52a5-89e7-5f8b6d3f959c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 72 year old woman attends her GP with palpitations and mild breathlessness on exertion for the past week. Her pulse is irregularly irregular at 128 beats/minute and her blood pressure is 138/84 mmHg. An ECG confirms atrial fibrillation. She has hypertension and type 2 diabetes. She is not breathless at rest and has no chest pain. What is the SINGLE most appropriate initial management of her heart rate?', 'She is haemodynamically stable and her AF started more than 48 hours ago, so rate control is first-line. NICE recommends a standard beta-blocker (not sotalol) or a rate-limiting calcium channel blocker (diltiazem or verapamil). Digoxin is reserved for sedentary patients or as add-on therapy. Cardioversion is not appropriate without at least 3 weeks of anticoagulation, or for unstable patients. Her CHA2DS2-VASc score is 4 (female, age 65-74, hypertension, diabetes), so she should also be offered a DOAC.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7b21a691-0b65-5d36-bad6-72a9dff5be15', 'ad4fadcd-dbeb-52a5-89e7-5f8b6d3f959c', 'A', 'Oral digoxin', false, 0),
  ('d53e21bf-3139-519f-ae71-f112da8ae997', 'ad4fadcd-dbeb-52a5-89e7-5f8b6d3f959c', 'B', 'Oral flecainide', false, 1),
  ('0ca7b38a-149c-54cd-b1e3-788593123361', 'ad4fadcd-dbeb-52a5-89e7-5f8b6d3f959c', 'C', 'IV amiodarone', false, 2),
  ('16387583-be5c-5e1a-9125-c77517171daf', 'ad4fadcd-dbeb-52a5-89e7-5f8b6d3f959c', 'D', 'Urgent DC cardioversion', false, 3),
  ('e15af550-a262-55f2-b1ed-ada40075c3a1', 'ad4fadcd-dbeb-52a5-89e7-5f8b6d3f959c', 'E', 'Oral bisoprolol', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('02bda421-355d-5335-acd5-4689c30b9860', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 58 year old man of Black African family origin attends a review after ambulatory blood pressure monitoring showed a daytime average of 152/96 mmHg. He has no diabetes, no chronic kidney disease and no history of cardiovascular disease. He has already made lifestyle changes over 3 months. What is the SINGLE most appropriate first-line antihypertensive?', 'An average daytime ABPM of 150/95 mmHg or above is stage 2 hypertension, and drug treatment should be offered. NICE recommends a calcium channel blocker such as amlodipine as first-line for people of Black African or African-Caribbean family origin without type 2 diabetes. ACE inhibitors are less effective in this group, and if a second drug is needed NICE suggests an ARB in preference to an ACE inhibitor. A thiazide-like diuretic is used if a CCB is not suitable. Beta-blockers are not first-line for hypertension.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('69839490-ec85-5b37-afde-68d9c47dbe16', '02bda421-355d-5335-acd5-4689c30b9860', 'A', 'Amlodipine', true, 0),
  ('bd889712-bc01-5447-a719-a2babd6ddeef', '02bda421-355d-5335-acd5-4689c30b9860', 'B', 'Bisoprolol', false, 1),
  ('a5f168ec-9dd6-5e85-be4b-eb8975b5cf19', '02bda421-355d-5335-acd5-4689c30b9860', 'C', 'Losartan', false, 2),
  ('2640e73f-83e2-5ac3-842d-0f15c70ed2fa', '02bda421-355d-5335-acd5-4689c30b9860', 'D', 'Ramipril', false, 3),
