insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f445a989-608c-5b7a-8934-6655d18ff069', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 78 year old man presents with exertional chest tightness and two episodes of dizziness while climbing stairs. On examination there is an ejection systolic murmur loudest in the right second intercostal space, radiating to the carotids, with a quiet second heart sound and a slow-rising pulse. What is the SINGLE most likely diagnosis?', 'Angina, exertional syncope and breathlessness are the classic triad of severe aortic stenosis. Signs include an ejection systolic murmur at the right upper sternal edge radiating to the carotids, a slow-rising pulse, narrow pulse pressure and a soft or absent S2. Diagnosis is by echocardiography. Symptomatic severe AS is treated with valve replacement (surgical or TAVI). Mitral regurgitation causes a pansystolic murmur radiating to the axilla.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6902dcd7-4591-5203-a681-ac9ecb78db39', 'f445a989-608c-5b7a-8934-6655d18ff069', 'A', 'Aortic regurgitation', false, 0),
  ('96578a98-3901-59ba-b2a8-abb02aee4564', 'f445a989-608c-5b7a-8934-6655d18ff069', 'B', 'Mitral stenosis', false, 1),
  ('c99f0cc0-8c72-5dde-a7d6-1b1c646c2774', 'f445a989-608c-5b7a-8934-6655d18ff069', 'C', 'Mitral regurgitation', false, 2),
  ('c8417fd3-1d40-5fc4-b39b-ccf800e261ba', 'f445a989-608c-5b7a-8934-6655d18ff069', 'D', 'Hypertrophic obstructive cardiomyopathy', false, 3),
