insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2dfa176e-5d6a-51a0-9c0e-60420b0cc258', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 34 year old man who injects drugs presents with 2 weeks of fevers, night sweats and fatigue. He has splinter haemorrhages and a new pansystolic murmur heard best at the left lower sternal edge that is louder on inspiration. His CRP is 160 mg/L. What is the SINGLE most appropriate initial investigation?', 'Suspected infective endocarditis (here likely tricuspid valve, typical in people who inject drugs, often due to Staphylococcus aureus) is diagnosed with the modified Duke criteria. Three sets of blood cultures from separate sites, ideally before antibiotics, are the most important first step, followed by echocardiography (transthoracic first, then transoesophageal if needed). In a stable patient, antibiotics can wait until cultures are taken.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('16b77447-e99c-536a-a4f7-f42a73b27c7c', '2dfa176e-5d6a-51a0-9c0e-60420b0cc258', 'A', 'Chest X-ray', false, 0),
  ('9fe2a837-4494-5f69-a587-e74befbeffa6', '2dfa176e-5d6a-51a0-9c0e-60420b0cc258', 'B', 'Three sets of blood cultures from separate venepuncture sites before antibiotics', true, 1),
  ('e09e7aff-f9aa-554d-afce-2411fe16a037', '2dfa176e-5d6a-51a0-9c0e-60420b0cc258', 'C', 'Single set of blood cultures after starting antibiotics', false, 2),
  ('8e043e79-365c-5a84-9dc4-0efa05531499', '2dfa176e-5d6a-51a0-9c0e-60420b0cc258', 'D', 'Rheumatoid factor', false, 3),
  ('857f9e9f-8834-532e-96a8-c0b633e63e15', '2dfa176e-5d6a-51a0-9c0e-60420b0cc258', 'E', 'Transthoracic echocardiogram before any blood tests', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('45e8220a-73dd-5b6c-baed-ed6d6b04e92e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 76 year old woman with known ischaemic heart disease presents with acute breathlessness that woke her from sleep. She is sitting upright, sweaty and has frothy pink sputum. Oxygen saturation is 88% on air, blood pressure 168/94 mmHg and there are widespread bilateral crackles. A chest X-ray shows bilateral alveolar shadowing and upper lobe diversion. Oxygen has been started. What is the SINGLE most appropriate drug treatment?', 'This is acute pulmonary oedema from acute heart failure. Management includes sitting up, controlled oxygen (if saturations are below 94%) and an IV loop diuretic such as furosemide. IV nitrates may be added if systolic BP is high. NICE advises against routine opioids. Starting a beta-blocker during acute decompensation can worsen it, and IV fluids are contraindicated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cb5b53dc-1126-5021-826a-76c06cea4cab', '45e8220a-73dd-5b6c-baed-ed6d6b04e92e', 'A', 'Oral bisoprolol', false, 0),
  ('fd30ae54-3d65-5c46-90da-53b444bb8dc3', '45e8220a-73dd-5b6c-baed-ed6d6b04e92e', 'B', 'Oral ramipril', false, 1),
  ('95c3161d-e696-5f87-bf7c-e8bc8dce2df3', '45e8220a-73dd-5b6c-baed-ed6d6b04e92e', 'C', 'IV furosemide', true, 2),
  ('cd52b9be-2e84-59e1-ba44-a935edcfaa73', '45e8220a-73dd-5b6c-baed-ed6d6b04e92e', 'D', 'IV 0.9% sodium chloride bolus', false, 3),
  ('d60067ec-318f-58a2-8460-47bccb41fc05', '45e8220a-73dd-5b6c-baed-ed6d6b04e92e', 'E', 'IV morphine as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('05919016-3879-50b6-b1ba-f6a7e9047b50', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 25 year old man presents with sharp central chest pain that is worse when lying flat and eased by sitting forward. He had a viral illness 1 week ago. On auscultation there is a scratchy sound at the left sternal edge. His ECG shows widespread saddle-shaped ST elevation with PR depression. Troponin is normal. What is the SINGLE most appropriate treatment?', 'This is acute pericarditis, most often viral. Widespread saddle-shaped ST elevation and PR depression that do not match a coronary territory distinguish it from STEMI. First-line treatment is a high-dose NSAID (or aspirin) with a PPI, plus colchicine to reduce recurrence. Steroids are second-line because they increase the risk of recurrence. An echo should be done to look for an effusion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9881c046-992a-5298-969d-d89c77eea803', '05919016-3879-50b6-b1ba-f6a7e9047b50', 'A', 'Oral prednisolone as first-line', false, 0),
  ('0660c2d8-a2ee-5e29-9c2a-21d97a09e071', '05919016-3879-50b6-b1ba-f6a7e9047b50', 'B', 'NSAID (such as ibuprofen) with colchicine', true, 1),
  ('b83c9cdc-0da6-5063-a9c8-2ad1c8cd049c', '05919016-3879-50b6-b1ba-f6a7e9047b50', 'C', 'Primary PCI', false, 2),
  ('b84f8285-a7ea-5c20-81ff-55b67d5ddeaa', '05919016-3879-50b6-b1ba-f6a7e9047b50', 'D', 'Thrombolysis', false, 3),
  ('1a5d3e58-d747-5e37-9907-01724fc35fd2', '05919016-3879-50b6-b1ba-f6a7e9047b50', 'E', 'IV heparin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fd07a534-23b9-5f0c-953d-21e182634bc6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 62 year old man with poorly controlled hypertension presents with sudden-onset, severe ''tearing'' chest pain radiating to his back between the shoulder blades. His blood pressure is 182/96 mmHg in the right arm and 140/80 mmHg in the left arm. ECG shows left ventricular hypertrophy only. What is the SINGLE most appropriate investigation?', 'Tearing pain radiating to the back with a blood pressure difference of more than 20 mmHg between the arms suggests aortic dissection. CT angiography is the investigation of choice in a stable patient (transoesophageal echo if unstable). Thrombolysis and anticoagulation must be avoided. Type A dissections (ascending aorta) need emergency surgery, and type B dissections are usually managed with blood pressure control.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f18f74df-33e9-5d4d-befa-cb9d71fc538e', 'fd07a534-23b9-5f0c-953d-21e182634bc6', 'A', 'CT angiography of the aorta', true, 0),
  ('4a3f9878-5d73-5b1c-950e-b5a09b7da607', 'fd07a534-23b9-5f0c-953d-21e182634bc6', 'B', 'Coronary angiography', false, 1),
  ('c58eab1d-2bd8-568a-9cbe-ad7cdd00b023', 'fd07a534-23b9-5f0c-953d-21e182634bc6', 'C', 'Serial troponins only', false, 2),
  ('666caca1-a769-5859-8411-1af3e63f920b', 'fd07a534-23b9-5f0c-953d-21e182634bc6', 'D', 'Exercise tolerance test', false, 3),
  ('3e88d43b-19f5-5d41-9329-d5edce81c858', 'fd07a534-23b9-5f0c-953d-21e182634bc6', 'E', 'D-dimer', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('46e7c398-3d08-591b-bf51-f0d0d23e5c71', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 28 year old woman presents with sudden-onset palpitations. Her heart rate is 186 beats/minute and regular, blood pressure 118/76 mmHg, and she has no chest pain or breathlessness. The ECG shows a narrow-complex regular tachycardia without visible P waves. A modified Valsalva manoeuvre has been tried without success. What is the SINGLE most appropriate next step?', 'This is a stable supraventricular tachycardia (SVT). After vagal manoeuvres fail, give IV adenosine as a rapid bolus into a large vein (6 mg, then 12 mg, then a further 12 mg) with ECG monitoring, warning her about transient chest tightness and flushing. Adenosine should be avoided in asthma (verapamil is an alternative). Synchronised DC cardioversion is for haemodynamically unstable patients with shock, syncope, ischaemia or heart failure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b91f812f-72ae-505b-aa01-1d9855764182', '46e7c398-3d08-591b-bf51-f0d0d23e5c71', 'A', 'Carotid sinus massage only', false, 0),
  ('a4b67cfa-f8c4-5e3d-9cb4-ad582748aa65', '46e7c398-3d08-591b-bf51-f0d0d23e5c71', 'B', 'IV amiodarone', false, 1),
  ('83ce023e-8172-5b08-9492-3adf2b844ab3', '46e7c398-3d08-591b-bf51-f0d0d23e5c71', 'C', 'IV adenosine by rapid bolus', true, 2),
  ('91bf8876-a992-58d9-8590-ab6784925fc3', '46e7c398-3d08-591b-bf51-f0d0d23e5c71', 'D', 'Oral bisoprolol and discharge', false, 3),
  ('48a4e21b-a587-5a92-8fa3-a7131f01d0e3', '46e7c398-3d08-591b-bf51-f0d0d23e5c71', 'E', 'Synchronised DC cardioversion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7ee7ad49-598d-5e20-88f6-eff90be8cc93', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'An 81 year old man presents with two episodes of collapse. His heart rate is 34 beats/minute and blood pressure 92/58 mmHg. He is pale and dizzy. His ECG shows regular P waves at 80/minute and regular broad QRS complexes at 34/minute with no relationship between them. What is the SINGLE most appropriate initial drug treatment?', 'This is complete (third-degree) heart block with adverse features (shock, syncope). The Resuscitation Council bradycardia algorithm advises IV atropine 500 micrograms, repeated up to 3 mg. If there is no response, use transcutaneous pacing or an isoprenaline or adrenaline infusion while arranging transvenous and then permanent pacing. Complete heart block is a risk for asystole, so a permanent pacemaker is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c2b89bbb-14f3-57c9-8837-ed368d77ebc4', '7ee7ad49-598d-5e20-88f6-eff90be8cc93', 'A', 'IV digoxin', false, 0),
  ('82c38e11-5522-5ba6-8123-fcae1f948cad', '7ee7ad49-598d-5e20-88f6-eff90be8cc93', 'B', 'IV atropine 500 micrograms', true, 1),
  ('eea309cf-330f-55b8-874a-d865ddd018e4', '7ee7ad49-598d-5e20-88f6-eff90be8cc93', 'C', 'Oral bisoprolol', false, 2),
  ('a7923e16-712d-5b80-adc8-1774837b5691', '7ee7ad49-598d-5e20-88f6-eff90be8cc93', 'D', 'IV amiodarone', false, 3),
  ('f4a6ab5a-bdd2-5905-8bf5-5d552f112f6d', '7ee7ad49-598d-5e20-88f6-eff90be8cc93', 'E', 'IV adenosine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('adf20090-e891-5cfe-9587-8824cee66a54', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 58 year old man has central chest pain at rest for 30 minutes. His ECG shows ST depression in V4-V6 and his high-sensitivity troponin is raised. He is pain-free after GTN. He has had aspirin 300 mg. His GRACE score predicts a 6-month mortality of 5%. What is the SINGLE most appropriate further management?', 'This is NSTEMI. NICE recommends coronary angiography within 72 hours for patients with an intermediate or higher risk of adverse events (predicted 6-month mortality over 3%). Antithrombotic therapy (dual antiplatelets, fondaparinux) is given first. Thrombolysis is not used in NSTEMI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('035f0218-0216-5f97-8462-e273cd0c51a5', 'adf20090-e891-5cfe-9587-8824cee66a54', 'A', 'Immediate thrombolysis', false, 0),
  ('6f05c4fe-b4d6-5c63-bb56-040b92303fc8', 'adf20090-e891-5cfe-9587-8824cee66a54', 'B', 'Coronary angiography (with PCI if indicated) within 72 hours', true, 1),
  ('5dabe134-3cf1-528b-b458-8d597bd82597', 'adf20090-e891-5cfe-9587-8824cee66a54', 'C', 'Emergency CABG', false, 2),
  ('85cb02c2-a38e-5fa3-a864-e7fbb424b9aa', 'adf20090-e891-5cfe-9587-8824cee66a54', 'D', 'Oral warfarin', false, 3),
  ('59e20fb8-4b79-51fd-8b0d-c5262d83caf0', 'adf20090-e891-5cfe-9587-8824cee66a54', 'E', 'Discharge with outpatient exercise ECG', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('eae9dffd-b809-5366-84d0-8937f48d462c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 61 year old man has crushing chest pain for 2 hours. His ECG shows ST elevation in V1-V4. The nearest PCI centre can deliver primary PCI within 90 minutes of diagnosis. What is the SINGLE most appropriate reperfusion strategy?', 'NICE recommends primary PCI for acute STEMI presenting within 12 hours of onset if it can be delivered within 120 minutes of when fibrinolysis could have been given. Thrombolysis is offered if PCI cannot be delivered in that time. Anterior ST elevation (V1-V4) indicates a LAD occlusion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e29da71-c814-5eaa-8024-693bf100e1de', 'eae9dffd-b809-5366-84d0-8937f48d462c', 'A', 'IV thrombolysis with alteplase', false, 0),
  ('a02270c7-95f6-5e92-ad61-c3081f01db2c', 'eae9dffd-b809-5366-84d0-8937f48d462c', 'B', 'Medical management with aspirin only', false, 1),
  ('f4a6dbe6-f3db-521e-9494-09c1d11508f1', 'eae9dffd-b809-5366-84d0-8937f48d462c', 'C', 'Primary percutaneous coronary intervention', true, 2),
  ('12d89c94-3a6e-5a64-be41-2bc799e8731d', 'eae9dffd-b809-5366-84d0-8937f48d462c', 'D', 'Fondaparinux only', false, 3),
  ('1f062795-8ed3-5294-b9d6-5e9a37a45b9c', 'eae9dffd-b809-5366-84d0-8937f48d462c', 'E', 'CABG', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b70abe88-e3ad-56ec-a71f-f853b9ae5beb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 66 year old woman was discharged after an anterior STEMI treated with PCI 3 days ago. Which combination of medication is MOST appropriate for long-term secondary prevention?', 'After an MI, NICE recommends dual antiplatelet therapy (aspirin plus a P2Y12 inhibitor such as ticagrelor or prasugrel) usually for 12 months, an ACE inhibitor, a beta-blocker and atorvastatin 80 mg. Cardiac rehabilitation and lifestyle change are also offered. An aldosterone antagonist is added if there is heart failure with reduced ejection fraction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('361419be-4881-5730-a5dc-7f8b74dcc42f', 'b70abe88-e3ad-56ec-a71f-f853b9ae5beb', 'A', 'Aspirin alone', false, 0),
  ('1b9c7115-ff64-5318-a5b0-0306f0c48a5b', 'b70abe88-e3ad-56ec-a71f-f853b9ae5beb', 'B', 'Digoxin and furosemide', false, 1),
  ('5abf00d8-f0f0-5f07-b11d-10a374a5d2ec', 'b70abe88-e3ad-56ec-a71f-f853b9ae5beb', 'C', 'Warfarin and a statin', false, 2),
  ('dba59ebb-a696-53cf-ba3f-cdb2338aae75', 'b70abe88-e3ad-56ec-a71f-f853b9ae5beb', 'D', 'Clopidogrel and a calcium channel blocker only', false, 3),
  ('045afc55-69e7-5ee0-a9b5-0d3b7d721743', 'b70abe88-e3ad-56ec-a71f-f853b9ae5beb', 'E', 'Dual antiplatelet therapy, ACE inhibitor, beta-blocker and high-intensity statin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5ff9f75d-a954-55d9-bc3f-26439b8fb29c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 70 year old man with heart failure with reduced ejection fraction (EF 30%) is breathless on mild exertion despite furosemide. He has no contraindications to treatment. Which drug combination is MOST likely to improve his prognosis?', 'In HFrEF, first-line prognostic drugs are an ACE inhibitor (or ARB) plus a heart failure beta-blocker (bisoprolol, carvedilol or nebivolol), started at a low dose and increased slowly. An MRA (spironolactone) and an SGLT2 inhibitor (dapagliflozin) are added. Loop diuretics relieve symptoms but do not improve mortality. Verapamil and diltiazem should be avoided.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dde4ccdb-1352-5975-ac0b-54f2e1550f1c', '5ff9f75d-a954-55d9-bc3f-26439b8fb29c', 'A', 'Nitrates only', false, 0),
  ('6b48812d-effa-50a8-9d5f-57b4f76c399b', '5ff9f75d-a954-55d9-bc3f-26439b8fb29c', 'B', 'Furosemide and digoxin', false, 1),
  ('b3d0c075-aba2-5472-bfeb-c141ba0d5771', '5ff9f75d-a954-55d9-bc3f-26439b8fb29c', 'C', 'Amlodipine and diltiazem', false, 2),
  ('34201bf2-e39f-5133-80a5-cd8f3478c55f', '5ff9f75d-a954-55d9-bc3f-26439b8fb29c', 'D', 'Verapamil and furosemide', false, 3),
  ('2f7364c3-fb98-5ee8-90f9-79a389925594', '5ff9f75d-a954-55d9-bc3f-26439b8fb29c', 'E', 'ACE inhibitor (or ARB) and a beta-blocker licensed for heart failure', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ce4f4079-14db-53a4-982f-a1c3fdef9d3e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 71 year old woman has been breathless on exertion for 3 months with ankle swelling. She has no previous cardiac history. Her GP suspects heart failure. What is the SINGLE most appropriate first investigation?', 'NICE recommends measuring NT-proBNP in suspected heart failure. A level above 2000 ng/L needs specialist assessment and echocardiography within 2 weeks, and 400-2000 ng/L within 6 weeks. Obesity, ACE inhibitors and beta-blockers can lower NT-proBNP. A normal level makes heart failure unlikely.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8ad23ac1-6313-5371-9929-c9befc62404d', 'ce4f4079-14db-53a4-982f-a1c3fdef9d3e', 'A', 'Exercise tolerance test', false, 0),
  ('79e79c1f-0a9b-58b1-862e-01cf4f4ca87b', 'ce4f4079-14db-53a4-982f-a1c3fdef9d3e', 'B', 'CT pulmonary angiogram', false, 1),
  ('3e279cb2-cd04-50fa-89bd-c016c7c9f9c7', 'ce4f4079-14db-53a4-982f-a1c3fdef9d3e', 'C', 'Serum NT-proBNP', true, 2),
  ('76a9d04f-d384-5208-bb65-d64ea1987bfb', 'ce4f4079-14db-53a4-982f-a1c3fdef9d3e', 'D', 'Coronary angiogram', false, 3),
  ('687bcd61-f5db-5b3b-a487-5c331e69302f', 'ce4f4079-14db-53a4-982f-a1c3fdef9d3e', 'E', '24-hour Holter monitor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ce736465-9c0a-549c-91ff-f2176b701de0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 45 year old woman has palpitations and is found to be in atrial fibrillation of uncertain duration. She is haemodynamically stable. She has no cardiovascular risk factors. Her CHA2DS2-VASc score is 1 (female sex only). What is the SINGLE most appropriate advice about anticoagulation?', 'Female sex alone (a CHA2DS2-VASc score of 1 in women) does not justify anticoagulation. NICE recommends offering anticoagulation for a score of 2 or above, and considering it for men with a score of 1. Aspirin is not recommended for stroke prevention in AF.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6636ef1d-68ed-5c13-a7ca-842491fcc66c', 'ce736465-9c0a-549c-91ff-f2176b701de0', 'A', 'Anticoagulation is not needed for stroke prevention on the basis of female sex alone', true, 0),
  ('92c97012-bbef-5b8d-9dee-1f85d3cc6523', 'ce736465-9c0a-549c-91ff-f2176b701de0', 'B', 'Start warfarin with a target INR of 3.5', false, 1),
  ('e3c0faca-027d-5fd1-993a-72f160ab7d36', 'ce736465-9c0a-549c-91ff-f2176b701de0', 'C', 'Start a DOAC lifelong', false, 2),
  ('1c7994d1-3337-51d2-93d7-feb88472447d', 'ce736465-9c0a-549c-91ff-f2176b701de0', 'D', 'Start aspirin 75 mg daily', false, 3),
  ('fa48be67-d62a-5c42-89be-b986836348d8', 'ce736465-9c0a-549c-91ff-f2176b701de0', 'E', 'Start dual antiplatelet therapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ffa46a9d-bc70-5e03-9fe6-70a2bf31e6c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 63 year old man with atrial fibrillation is being considered for anticoagulation. He has hypertension and type 2 diabetes, and he had a TIA last year. He has normal kidney function. What is the SINGLE most appropriate anticoagulant?', 'His CHA2DS2-VASc score is 4 (hypertension, diabetes, TIA x2), so anticoagulation is indicated. NICE recommends a DOAC (apixaban, dabigatran, edoxaban or rivaroxaban) first-line. Warfarin is used if DOACs are contraindicated, such as with mechanical valves or moderate-severe mitral stenosis. Bleeding risk is assessed with the ORBIT tool.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('19c0346a-82b5-5254-bccb-ac4e781b06f9', 'ffa46a9d-bc70-5e03-9fe6-70a2bf31e6c2', 'A', 'No anticoagulant', false, 0),
  ('fb2d3600-77ae-5334-982d-1a0129468b31', 'ffa46a9d-bc70-5e03-9fe6-70a2bf31e6c2', 'B', 'Clopidogrel', false, 1),
  ('075377f5-282f-5a43-a9cd-aab0ad80cdf5', 'ffa46a9d-bc70-5e03-9fe6-70a2bf31e6c2', 'C', 'Aspirin', false, 2),
  ('a7c14774-e90b-5d0c-b708-9509efe806b0', 'ffa46a9d-bc70-5e03-9fe6-70a2bf31e6c2', 'D', 'A direct oral anticoagulant such as apixaban', true, 3),
  ('0f0b3309-b3bb-56ff-b4ec-01f59d05dd75', 'ffa46a9d-bc70-5e03-9fe6-70a2bf31e6c2', 'E', 'Low molecular weight heparin long-term', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6a50b06a-0a94-5440-b2bd-f1bc69afe247', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 76 year old woman has atrial fibrillation with a ventricular rate of 145 beats/minute. Her BP is 74/40 mmHg, and she is confused and clammy. What is the SINGLE most appropriate immediate management?', 'A tachyarrhythmia with adverse features (shock, syncope, myocardial ischaemia or heart failure) needs synchronised DC cardioversion (up to 3 shocks) under sedation or anaesthesia, per Resuscitation Council UK. If unsuccessful, IV amiodarone 300 mg is given. Adenosine has no role in AF.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e2022d4a-9500-57c9-81bc-6c3a59cd12b3', '6a50b06a-0a94-5440-b2bd-f1bc69afe247', 'A', 'Synchronised DC cardioversion', true, 0),
  ('a6c31838-8c29-5c3e-8a7b-ccab12391303', '6a50b06a-0a94-5440-b2bd-f1bc69afe247', 'B', 'Oral bisoprolol', false, 1),
  ('fad8de46-4bd5-5032-9849-cea22e402f2f', '6a50b06a-0a94-5440-b2bd-f1bc69afe247', 'C', 'IV digoxin', false, 2),
  ('9348661a-e909-5ea9-90d6-5d0a92cf3ebc', '6a50b06a-0a94-5440-b2bd-f1bc69afe247', 'D', 'IV adenosine', false, 3),
  ('c6848b80-de6d-5026-8c6a-122d5f9136ad', '6a50b06a-0a94-5440-b2bd-f1bc69afe247', 'E', 'Oral apixaban only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9099ab37-86c9-55e8-87b8-ca5916acd71b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 58 year old man collapses in the coronary care unit. He is unresponsive with no pulse. The monitor shows a broad-complex regular tachycardia at 200 beats/minute. CPR has started and the defibrillator is attached. What is the SINGLE most appropriate next step?', 'Pulseless ventricular tachycardia is a shockable rhythm. Give an unsynchronised shock immediately, then 2 minutes of CPR. Adrenaline 1 mg and amiodarone 300 mg are given after the third shock. Synchronised cardioversion is for VT with a pulse and adverse features.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('73d97a7e-052f-53c3-9e23-76eaafdffe83', '9099ab37-86c9-55e8-87b8-ca5916acd71b', 'A', 'Synchronised cardioversion', false, 0),
  ('84d695ec-d431-5303-97c2-15a666364641', '9099ab37-86c9-55e8-87b8-ca5916acd71b', 'B', 'Deliver an unsynchronised shock (defibrillation)', true, 1),
  ('fed4853e-cacd-5f14-b337-840169bf808c', '9099ab37-86c9-55e8-87b8-ca5916acd71b', 'C', 'IV amiodarone before any shock', false, 2),
  ('4f947ade-c03b-5a66-9058-a3341832f9a6', '9099ab37-86c9-55e8-87b8-ca5916acd71b', 'D', 'IV adenosine 6 mg', false, 3),
  ('40eeff27-b34d-50f4-b199-450c21cdc808', '9099ab37-86c9-55e8-87b8-ca5916acd71b', 'E', 'IV atropine 500 micrograms', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('24a58b88-3795-5c05-a38c-47d36eb408b4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 55 year old woman is in cardiac arrest. The rhythm is asystole. CPR is ongoing and IV access has been obtained. What is the SINGLE most appropriate drug to give now?', 'Asystole and PEA are non-shockable rhythms. Give adrenaline 1 mg IV as soon as access is gained, then every 3-5 minutes, while continuing CPR and treating reversible causes (4 Hs and 4 Ts). Atropine is no longer recommended in asystole. Amiodarone is for shockable rhythms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('30fd0a29-d634-5630-8c80-21403c19b821', '24a58b88-3795-5c05-a38c-47d36eb408b4', 'A', 'IV adenosine 6 mg', false, 0),
  ('a6dee13b-8e08-5942-8b09-6c79679cff5f', '24a58b88-3795-5c05-a38c-47d36eb408b4', 'B', 'IV atropine 3 mg', false, 1),
  ('0c98dc58-0083-5a11-a9c1-bdc049ddbdd6', '24a58b88-3795-5c05-a38c-47d36eb408b4', 'C', 'IV amiodarone 300 mg', false, 2),
  ('4c6780b6-0240-5665-848b-515944c0df89', '24a58b88-3795-5c05-a38c-47d36eb408b4', 'D', 'IV calcium chloride routinely', false, 3),
  ('7f944561-d47e-5d6f-9340-6cef3a19149c', '24a58b88-3795-5c05-a38c-47d36eb408b4', 'E', 'IV adrenaline 1 mg', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c37f0578-5f5a-5825-bd0f-470eed8b2f54', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 24 year old man has had palpitations for 2 hours. He is haemodynamically stable. His ECG shows a short PR interval and a slurred upstroke of the QRS complex (delta wave) during sinus rhythm. What is the SINGLE most likely diagnosis?', 'A short PR interval with a delta wave indicates pre-excitation through an accessory pathway (bundle of Kent), which is Wolff-Parkinson-White syndrome. AV nodal blocking drugs (adenosine, verapamil, digoxin) should be avoided in pre-excited AF. Definitive treatment is catheter ablation of the pathway.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4a36dd96-1600-518d-91d9-bd44f99df655', 'c37f0578-5f5a-5825-bd0f-470eed8b2f54', 'A', 'Wolff-Parkinson-White syndrome', true, 0),
  ('5a242399-9ebc-522d-a7db-8712299a7106', 'c37f0578-5f5a-5825-bd0f-470eed8b2f54', 'B', 'Brugada syndrome', false, 1),
  ('286733c8-59b9-5d30-9a1d-fd1da08e38b7', 'c37f0578-5f5a-5825-bd0f-470eed8b2f54', 'C', 'Long QT syndrome', false, 2),
  ('5286d11f-1c40-5c57-8b76-529a4dfedead', 'c37f0578-5f5a-5825-bd0f-470eed8b2f54', 'D', 'Hypertrophic cardiomyopathy', false, 3),
  ('e0ce2f6e-e8be-507b-a59b-7a17cc0ff1e9', 'c37f0578-5f5a-5825-bd0f-470eed8b2f54', 'E', 'First-degree heart block', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('009c5edf-92e1-5af1-84ec-39b7742550ad', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 19 year old footballer collapses during a match and recovers quickly. His father died suddenly aged 35. On examination there is an ejection systolic murmur that gets louder with the Valsalva manoeuvre and on standing. His ECG shows left ventricular hypertrophy with deep Q waves. What is the SINGLE most likely diagnosis?', 'Hypertrophic cardiomyopathy is autosomal dominant and a leading cause of sudden cardiac death in young athletes. The murmur of left ventricular outflow obstruction gets louder when preload falls (Valsalva, standing) and quieter on squatting. Echocardiography confirms it. Management includes avoiding competitive sport, beta-blockers, an ICD if high risk, and screening first-degree relatives.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7fba7cb2-d1a9-5ffd-9a41-0f1e7c9a5bda', '009c5edf-92e1-5af1-84ec-39b7742550ad', 'A', 'Aortic stenosis', false, 0),
  ('8a1a8976-06de-51cb-96c9-083ffd861b9c', '009c5edf-92e1-5af1-84ec-39b7742550ad', 'B', 'Hypertrophic cardiomyopathy', true, 1),
  ('0aade1bc-8f65-5c17-b661-1fdb41232d32', '009c5edf-92e1-5af1-84ec-39b7742550ad', 'C', 'Arrhythmogenic right ventricular cardiomyopathy', false, 2),
  ('bda654d7-02ae-51f3-aa8e-c24f58e34100', '009c5edf-92e1-5af1-84ec-39b7742550ad', 'D', 'Dilated cardiomyopathy', false, 3),
  ('d5e1ba6d-a02d-5819-9e0f-908c5ed5756d', '009c5edf-92e1-5af1-84ec-39b7742550ad', 'E', 'Mitral valve prolapse', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('25d78d67-ac05-5955-8c46-f2478974ea1c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 64 year old woman with rheumatic fever in childhood is breathless and has palpitations. On examination she has malar flush, an irregularly irregular pulse and a low-pitched rumbling mid-diastolic murmur at the apex with an opening snap. What is the SINGLE most likely valve lesion?', 'Rheumatic heart disease is the commonest cause of mitral stenosis. It causes a mid-diastolic rumble at the apex (best heard in the left lateral position with the bell), an opening snap, malar flush and AF. Moderate-severe mitral stenosis with AF needs warfarin rather than a DOAC. Treatment options include percutaneous balloon valvotomy or valve replacement.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a3763810-25f7-52be-9bc8-56e7a62f1814', '25d78d67-ac05-5955-8c46-f2478974ea1c', 'A', 'Mitral stenosis', true, 0),
  ('9e28c1a8-bc28-5038-8783-5cb09b7bb90e', '25d78d67-ac05-5955-8c46-f2478974ea1c', 'B', 'Aortic stenosis', false, 1),
  ('ec30d161-55f8-5a9c-95aa-515a252a1c1b', '25d78d67-ac05-5955-8c46-f2478974ea1c', 'C', 'Aortic regurgitation', false, 2),
  ('c9a33b83-4036-52cf-a113-e752e9ed6d82', '25d78d67-ac05-5955-8c46-f2478974ea1c', 'D', 'Mitral regurgitation', false, 3),
  ('5ce7e526-d7b9-5821-807e-f7eb1474667c', '25d78d67-ac05-5955-8c46-f2478974ea1c', 'E', 'Tricuspid regurgitation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c091ebfe-3bcb-5613-94ce-6aa0feaf9abf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 68 year old man has a collapsing (water-hammer) pulse, a wide pulse pressure and an early diastolic murmur at the left sternal edge, heard best sitting forward in expiration. What is the SINGLE most likely diagnosis?', 'An early diastolic decrescendo murmur at the left sternal edge with a collapsing pulse and wide pulse pressure indicates aortic regurgitation. Causes include aortic root dilatation (Marfan syndrome, hypertension), bicuspid valve, endocarditis and rheumatic disease. An Austin Flint murmur may be heard. Severe symptomatic disease needs valve replacement.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e730a5cb-16e9-5624-879e-d8d6cff71e1c', 'c091ebfe-3bcb-5613-94ce-6aa0feaf9abf', 'A', 'Mitral stenosis', false, 0),
  ('0d27e002-ec44-5bac-9384-a305d3eef52a', 'c091ebfe-3bcb-5613-94ce-6aa0feaf9abf', 'B', 'Ventricular septal defect', false, 1),
  ('6a3a2ed4-b0f9-58fb-b6b0-fe59767d4c49', 'c091ebfe-3bcb-5613-94ce-6aa0feaf9abf', 'C', 'Aortic regurgitation', true, 2),
  ('d7910258-6827-52da-9afa-9033c5985a1b', 'c091ebfe-3bcb-5613-94ce-6aa0feaf9abf', 'D', 'Patent ductus arteriosus', false, 3),
  ('53fc972a-6fdc-5373-8fb7-950c732d899e', 'c091ebfe-3bcb-5613-94ce-6aa0feaf9abf', 'E', 'Aortic stenosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8224829e-7be3-5bbe-8a04-ed68e498a226', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 40 year old woman develops breathlessness and pleuritic chest pain 3 days after a viral illness. She has a quiet heart, a raised JVP that rises on inspiration, BP 82/60 mmHg with a 15 mmHg drop on inspiration, and low-voltage QRS complexes on ECG. What is the SINGLE most appropriate immediate management?', 'Hypotension, a raised JVP and muffled heart sounds (Beck''s triad) with pulsus paradoxus and a rising JVP on inspiration (Kussmaul''s sign) indicate cardiac tamponade. Echo confirms it, and urgent pericardiocentesis is life-saving. Diuretics and nitrates reduce preload and can cause collapse.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('79b1503c-d6e0-5302-aec4-473e932064aa', '8224829e-7be3-5bbe-8a04-ed68e498a226', 'A', 'Urgent echocardiography-guided pericardiocentesis', true, 0),
  ('1f2f8981-ebdc-5da0-a12e-d3f0e666f29c', '8224829e-7be3-5bbe-8a04-ed68e498a226', 'B', 'IV furosemide', false, 1),
  ('2834b4bb-492b-5573-91b6-900a917afbb3', '8224829e-7be3-5bbe-8a04-ed68e498a226', 'C', 'Sublingual GTN', false, 2),
  ('0308d932-e3a8-56ca-bb75-13fdda4ba39c', '8224829e-7be3-5bbe-8a04-ed68e498a226', 'D', 'IV beta-blocker', false, 3),
  ('b78e1ab7-abe8-5528-9e74-8c75544e573e', '8224829e-7be3-5bbe-8a04-ed68e498a226', 'E', 'Thrombolysis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9f2c1ef7-609e-56dc-aa66-17860b6b7b2d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 50 year old man has a BP of 192/124 mmHg. He has a severe headache and blurred vision. Fundoscopy shows bilateral papilloedema and flame haemorrhages. His creatinine is raised. What is the SINGLE most appropriate management?', 'This is a hypertensive emergency (accelerated or malignant hypertension) with end-organ damage (papilloedema, AKI). NICE advises same-day specialist referral. BP is lowered in a controlled way with IV agents such as labetalol or GTN, by no more than about 25% in the first hours, to avoid cerebral or renal hypoperfusion. Sublingual nifedipine is dangerous.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('199b4e6b-6549-5bd3-b39c-62867464e1ad', '9f2c1ef7-609e-56dc-aa66-17860b6b7b2d', 'A', 'Reduce BP to normal within 1 hour with sublingual nifedipine', false, 0),
  ('f225da20-8fbc-537f-a056-1e46741376b2', '9f2c1ef7-609e-56dc-aa66-17860b6b7b2d', 'B', 'Admit for controlled reduction of BP with IV antihypertensives', true, 1),
  ('362a8e95-90ce-50b8-84ba-0cb60394b2b6', '9f2c1ef7-609e-56dc-aa66-17860b6b7b2d', 'C', 'Discharge with lifestyle advice', false, 2),
  ('fffdced6-9b43-5a6b-901f-de9a1cd34b1b', '9f2c1ef7-609e-56dc-aa66-17860b6b7b2d', 'D', 'Ambulatory BP monitoring', false, 3),
  ('167fd3f4-64ad-5ae8-a231-1b2493b09a3e', '9f2c1ef7-609e-56dc-aa66-17860b6b7b2d', 'E', 'Start oral amlodipine and review in 2 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5acb88a8-7057-5900-9d3f-a2d2897710d5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 52 year old woman is on amlodipine 10 mg and ramipril 10 mg, but her clinic BP remains 152/94 mmHg with home readings around 148/90 mmHg. She takes her medication reliably. Her potassium is 4.0 mmol/L. What is the SINGLE most appropriate next step?', 'NICE step 3 is an ACE inhibitor (or ARB) plus a calcium channel blocker plus a thiazide-like diuretic (indapamide). If BP remains uncontrolled on optimal doses (resistant hypertension), step 4 is low-dose spironolactone if potassium is 4.5 mmol/L or below, or an alpha- or beta-blocker if above. Adherence should be confirmed first.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('85650ed5-fa4d-5b56-be2f-7f60aebe3687', '5acb88a8-7057-5900-9d3f-a2d2897710d5', 'A', 'Add indapamide (a thiazide-like diuretic)', true, 0),
  ('dedeb2a0-dab3-5612-9550-bce3f1ac8a7b', '5acb88a8-7057-5900-9d3f-a2d2897710d5', 'B', 'Stop amlodipine', false, 1),
  ('efed2010-fcfb-5d76-92fb-d2429d8309a8', '5acb88a8-7057-5900-9d3f-a2d2897710d5', 'C', 'Add doxazosin', false, 2),
  ('9d30fc7f-e322-55e7-b783-892456121b59', '5acb88a8-7057-5900-9d3f-a2d2897710d5', 'D', 'Add bisoprolol', false, 3),
  ('7bc144e7-bbcc-5632-8dfa-711c2158ea1f', '5acb88a8-7057-5900-9d3f-a2d2897710d5', 'E', 'Add spironolactone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8af6ce50-2b05-5eb0-8117-4615b79ebcf4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 24 year old woman has BP 168/104 mmHg. She has muscle weakness and cramps. Her potassium is 2.9 mmol/L and sodium 144 mmol/L. She takes no medication. What is the SINGLE most appropriate first investigation for the most likely cause?', 'Hypertension with hypokalaemia suggests primary hyperaldosteronism (Conn''s syndrome), the commonest secondary cause of hypertension. Screening is with the aldosterone-to-renin ratio (high aldosterone, suppressed renin). Adrenal imaging and venous sampling follow. Treatment is spironolactone or adrenalectomy for an adenoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d6d68ff2-3e72-5d9b-94fc-78e5747d0ae1', '8af6ce50-2b05-5eb0-8117-4615b79ebcf4', 'A', 'Renal artery Doppler', false, 0),
  ('dc575fab-b826-5349-9587-caa29a10ed3f', '8af6ce50-2b05-5eb0-8117-4615b79ebcf4', 'B', '24-hour urinary catecholamines', false, 1),
  ('46445d67-e6e4-597d-9bfb-7a3c9a6aae4d', '8af6ce50-2b05-5eb0-8117-4615b79ebcf4', 'C', 'Plasma aldosterone-to-renin ratio', true, 2),
  ('ff214e2a-36a7-50c6-97f3-144d82efd6c1', '8af6ce50-2b05-5eb0-8117-4615b79ebcf4', 'D', 'Thyroid function tests', false, 3),
  ('275a9a06-e349-5485-9c78-051f9c4adee9', '8af6ce50-2b05-5eb0-8117-4615b79ebcf4', 'E', 'Overnight dexamethasone suppression test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('14b0206f-392b-5b9e-b03e-bd3182dbb15e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 45 year old woman has episodes of headache, palpitations and sweating with BP up to 220/120 mmHg during the attacks. She has lost weight. Her mother had thyroid cancer and a parathyroid adenoma. What is the SINGLE most appropriate investigation?', 'Paroxysmal headache, palpitations and sweating with hypertension suggest phaeochromocytoma. A family history of medullary thyroid cancer and hyperparathyroidism suggests MEN2. Plasma free metanephrines (or 24-hour urinary metanephrines) are the screening test. Before surgery, alpha-blockade (phenoxybenzamine) is given first, then a beta-blocker, to avoid an unopposed alpha crisis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6daaf527-e75e-520a-a4a9-b2e3109f3f4c', '14b0206f-392b-5b9e-b03e-bd3182dbb15e', 'A', 'Serum cortisol', false, 0),
  ('42972079-bfb5-58b8-970e-30a92301e984', '14b0206f-392b-5b9e-b03e-bd3182dbb15e', 'B', 'Thyroid function tests', false, 1),
  ('4cd8cdc1-6fcc-5a9d-952a-22f3d5ef8fa0', '14b0206f-392b-5b9e-b03e-bd3182dbb15e', 'C', 'Echocardiogram', false, 2),
  ('43e54b0a-e0e2-5908-a203-7fdf6515c44e', '14b0206f-392b-5b9e-b03e-bd3182dbb15e', 'D', 'Plasma free metanephrines', true, 3),
  ('5507fc26-1cdf-5c80-87d7-ddb4f50d8c79', '14b0206f-392b-5b9e-b03e-bd3182dbb15e', 'E', 'Aldosterone-to-renin ratio', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b33ef240-60c8-5a51-b550-7b4d864fdccd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 59 year old smoker has cramping pain in his right calf after walking 200 metres, relieved by rest. His foot pulses are weak. Ankle-brachial pressure index is 0.65 on the right. There is no rest pain or tissue loss. What is the SINGLE most appropriate initial management?', 'This is intermittent claudication from peripheral arterial disease (ABPI 0.5-0.9). NICE recommends a supervised exercise programme, risk factor control (stopping smoking, atorvastatin 80 mg, BP and diabetes control) and an antiplatelet (clopidogrel 75 mg). Revascularisation is considered if symptoms stay disabling. Compression is contraindicated in arterial disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('88bf11ee-dff2-5580-b25c-69ea560b114f', 'b33ef240-60c8-5a51-b550-7b4d864fdccd', 'A', 'Urgent femoral-popliteal bypass', false, 0),
  ('dabf9199-c265-58a9-86be-fe8b05dbfe76', 'b33ef240-60c8-5a51-b550-7b4d864fdccd', 'B', 'Oral warfarin', false, 1),
  ('0325ff96-e22d-55b3-8c57-106550daf171', 'b33ef240-60c8-5a51-b550-7b4d864fdccd', 'C', 'Supervised exercise programme, smoking cessation, atorvastatin and clopidogrel', true, 2),
  ('4fa99cfc-e054-58c8-8f89-e34614a41662', 'b33ef240-60c8-5a51-b550-7b4d864fdccd', 'D', 'Compression stockings', false, 3),
  ('7d1ce020-850b-51a4-a4d4-e80a7af924ea', 'b33ef240-60c8-5a51-b550-7b4d864fdccd', 'E', 'Below-knee amputation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('960c8eb7-ff19-5dda-b457-77796f9f1cce', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 72 year old woman has a 3 cm leg ulcer above the medial malleolus. It is shallow and sloughy with irregular edges. There is haemosiderin staining, lipodermatosclerosis and varicose veins. Her foot pulses are palpable and ABPI is 0.95. What is the SINGLE most appropriate management?', 'A shallow ulcer over the gaiter area with signs of venous hypertension is a venous leg ulcer. Once arterial disease is excluded (ABPI 0.8-1.3), the mainstay is high-compression multilayer bandaging, with leg elevation and treatment of underlying venous reflux. Antibiotics are only for clinical infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f703c819-e9ca-5fa1-8399-91edbfab4022', '960c8eb7-ff19-5dda-b457-77796f9f1cce', 'A', 'Surgical debridement and skin graft first', false, 0),
  ('e172f3e9-7bb5-5aa3-9f2a-bb70bacd7ec2', '960c8eb7-ff19-5dda-b457-77796f9f1cce', 'B', 'Oral antibiotics long-term', false, 1),
  ('9021c89b-17ee-5337-aeb1-1744c39806ac', '960c8eb7-ff19-5dda-b457-77796f9f1cce', 'C', 'Topical steroid cream', false, 2),
  ('a951a00e-817c-50eb-b162-2d66758dad6e', '960c8eb7-ff19-5dda-b457-77796f9f1cce', 'D', 'Multilayer compression bandaging', true, 3),
  ('028212aa-755b-5813-8114-e56800f90d81', '960c8eb7-ff19-5dda-b457-77796f9f1cce', 'E', 'Below-knee amputation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d4cd0981-b456-580a-a7f4-fa6d606ab662', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 72 year old man has a small abdominal aortic aneurysm found on screening. It measures 4.9 cm on ultrasound. He has no symptoms. What is the SINGLE most appropriate management?', 'NHS AAA screening: 3.0-4.4 cm is scanned yearly, 4.5-5.4 cm every 3 months. Referral for repair (usually within 8 weeks) is for 5.5 cm or more, growth over 1 cm per year, or symptoms. Risk factor modification (stopping smoking, statin, antiplatelet, BP control) reduces growth and cardiovascular events.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ebf16487-8c9d-54e6-b189-0bf465c5dc1e', 'd4cd0981-b456-580a-a7f4-fa6d606ab662', 'A', 'Surveillance every 5 years', false, 0),
  ('40d7f93c-7027-522c-bd45-a8b2ae45d3cf', 'd4cd0981-b456-580a-a7f4-fa6d606ab662', 'B', 'Discharge with no follow-up', false, 1),
  ('95ceeafe-a3cb-5aa9-b4eb-516a110599fc', 'd4cd0981-b456-580a-a7f4-fa6d606ab662', 'C', 'Immediate open repair', false, 2),
  ('5e007e5c-d5bf-5198-83c4-90c7ea6566a9', 'd4cd0981-b456-580a-a7f4-fa6d606ab662', 'D', 'Endovascular repair this week', false, 3),
  ('583502f5-f00f-5001-8a0b-18324d5d0ea3', 'd4cd0981-b456-580a-a7f4-fa6d606ab662', 'E', 'Ultrasound surveillance every 3 months and cardiovascular risk management', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5346fc7b-b379-598f-a5df-88f7f833c4ef', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 31 year old woman develops severe breathlessness 5 weeks after delivering her first baby. She has orthopnoea, bibasal crackles and a raised JVP. Echocardiogram shows a dilated left ventricle with an ejection fraction of 30%. She has no previous heart disease. What is the SINGLE most likely diagnosis?', 'Peripartum cardiomyopathy is heart failure with reduced ejection fraction (usually under 45%) in the last month of pregnancy or within 5 months of delivery, with no other cause. Management is standard heart failure treatment, adapted for breastfeeding, plus anticoagulation if EF is very low. Bromocriptine may be considered. Future pregnancies carry a high risk of recurrence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7b3574f9-9f6c-5327-ad31-3b974a3a3643', '5346fc7b-b379-598f-a5df-88f7f833c4ef', 'A', 'Peripartum cardiomyopathy', true, 0),
  ('c0e4e6e1-462f-5170-bafe-cd280ffe472b', '5346fc7b-b379-598f-a5df-88f7f833c4ef', 'B', 'Mitral stenosis', false, 1),
  ('ae1660ef-6cef-56e9-a06c-e4230b01a093', '5346fc7b-b379-598f-a5df-88f7f833c4ef', 'C', 'Amniotic fluid embolism', false, 2),
  ('420a216c-b579-51f1-bc55-b5345de99541', '5346fc7b-b379-598f-a5df-88f7f833c4ef', 'D', 'Hypertrophic cardiomyopathy', false, 3),
  ('5a18a750-12e3-5d4b-a05b-f34a916477e5', '5346fc7b-b379-598f-a5df-88f7f833c4ef', 'E', 'Pulmonary embolism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2af1d85a-0f9d-5504-8628-cfeedf9c875c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 34 year old woman has a fever for 2 weeks after a dental procedure. She has a known bicuspid aortic valve. She has a new early diastolic murmur, splinter haemorrhages, painless red macules on her palms and haematuria. Blood cultures grow viridans streptococci. What are the painless palmar lesions called?', 'Janeway lesions are painless macules on the palms and soles from septic emboli. Osler''s nodes are painful nodules on the finger pulps (immune complex), and Roth spots are retinal haemorrhages with pale centres. Viridans streptococci typically cause subacute endocarditis after dental work. NICE does not recommend routine antibiotic prophylaxis for dental procedures.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cf7b458b-25ff-52e0-b8e2-dfe2bc9113ac', '2af1d85a-0f9d-5504-8628-cfeedf9c875c', 'A', 'Janeway lesions', true, 0),
  ('0ff34e04-3100-5d6c-ba2e-888f45a755a3', '2af1d85a-0f9d-5504-8628-cfeedf9c875c', 'B', 'Erythema nodosum', false, 1),
  ('2bd720e9-5aea-525c-bd00-50d8a7c20584', '2af1d85a-0f9d-5504-8628-cfeedf9c875c', 'C', 'Splinter haemorrhages', false, 2),
  ('0069155d-41a3-5669-987c-766629959912', '2af1d85a-0f9d-5504-8628-cfeedf9c875c', 'D', 'Roth spots', false, 3),
  ('e716c458-4533-5d6f-b771-19e5453dbf72', '2af1d85a-0f9d-5504-8628-cfeedf9c875c', 'E', 'Osler''s nodes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('08b0a930-1fc0-585b-93c0-60746e60ee3a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 66 year old man has an ECG showing a PR interval of 0.26 seconds with every P wave followed by a QRS complex. He has no symptoms and a heart rate of 64 beats/minute. What is the SINGLE most appropriate management?', 'A PR interval over 0.2 seconds with 1:1 conduction is first-degree heart block. It is usually benign in an asymptomatic patient and needs no specific treatment, apart from reviewing AV nodal blocking drugs (beta-blockers, calcium channel blockers, digoxin). Pacemakers are for Mobitz II, complete heart block or symptomatic bradycardia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('453a36b0-f869-520e-b65d-7c0e0b798f24', '08b0a930-1fc0-585b-93c0-60746e60ee3a', 'A', 'Temporary transvenous pacing', false, 0),
  ('9e7df9d7-c4f2-5b87-9b26-2eb192ef4ee4', '08b0a930-1fc0-585b-93c0-60746e60ee3a', 'B', 'No treatment; review medications and monitor', true, 1),
  ('a414e041-ddc2-5d5b-a128-6f9d51d499b6', '08b0a930-1fc0-585b-93c0-60746e60ee3a', 'C', 'IV isoprenaline', false, 2),
  ('a68fe120-32fa-5a69-be1a-6b7bc512e6cc', '08b0a930-1fc0-585b-93c0-60746e60ee3a', 'D', 'Permanent pacemaker', false, 3),
  ('8d2795eb-706e-5a39-912d-4cc8bf726e78', '08b0a930-1fc0-585b-93c0-60746e60ee3a', 'E', 'IV atropine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('680a8249-daa6-5fea-b92f-032a1b5f5873', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 74 year old woman feels light-headed. Her ECG shows a constant PR interval with intermittent P waves not followed by QRS complexes, in a 2:1 or 3:1 pattern, with broad QRS complexes. What is the SINGLE most likely rhythm?', 'In Mobitz II, the PR interval is constant with intermittently dropped beats. It is usually infranodal and carries a high risk of progressing to complete heart block, so a permanent pacemaker is indicated. In Mobitz I (Wenckebach), the PR interval gets longer until a beat is dropped, and it is often benign.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
