  ('be43cd79-6706-5d53-b1cc-2b7ee24c5ddb', '680a8249-daa6-5fea-b92f-032a1b5f5873', 'A', 'Atrial flutter with variable block', false, 0),
  ('9c2acfe2-f6a5-55cd-96db-f11c476de675', '680a8249-daa6-5fea-b92f-032a1b5f5873', 'B', 'Mobitz type II second-degree heart block', true, 1),
  ('909cdaba-9de0-54d6-8204-021db67222f8', '680a8249-daa6-5fea-b92f-032a1b5f5873', 'C', 'First-degree heart block', false, 2),
  ('fd33ff57-9009-5a9f-8cb6-39a08896d4fd', '680a8249-daa6-5fea-b92f-032a1b5f5873', 'D', 'Mobitz type I (Wenckebach)', false, 3),
  ('bed5f553-31a4-58a3-87c1-b3694aa9b48b', '680a8249-daa6-5fea-b92f-032a1b5f5873', 'E', 'Sinus arrhythmia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cc31b154-2b16-5f0f-92e4-898e8998f402', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 34 year old man with no past history has a heart rate of 150 beats/minute. His ECG shows a regular narrow-complex tachycardia with a sawtooth baseline in leads II, III and aVF. What is the SINGLE most likely diagnosis?', 'Sawtooth flutter waves (atrial rate about 300/minute) in the inferior leads with a regular ventricular rate of 150 (2:1 block) indicate atrial flutter. A heart rate of exactly 150 should raise suspicion of it. Management is similar to AF (rate control, anticoagulation by CHA2DS2-VASc), but catheter ablation of the cavotricuspid isthmus is very effective.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7b39a7e2-ca4f-5954-aee2-365f4217f6f5', 'cc31b154-2b16-5f0f-92e4-898e8998f402', 'A', 'Ventricular tachycardia', false, 0),
  ('bf90a23a-eee0-5ee9-a78a-8ba10e7b65e0', 'cc31b154-2b16-5f0f-92e4-898e8998f402', 'B', 'Atrial flutter with 2:1 block', true, 1),
  ('e4ae3e56-1e72-5c0f-8ee2-6dbc484ba864', 'cc31b154-2b16-5f0f-92e4-898e8998f402', 'C', 'AV nodal re-entrant tachycardia', false, 2),
  ('fdc91201-217f-52ba-bb59-376608e79131', 'cc31b154-2b16-5f0f-92e4-898e8998f402', 'D', 'Atrial fibrillation', false, 3),
  ('fc342662-ab3c-5429-bb01-522510a28a1d', 'cc31b154-2b16-5f0f-92e4-898e8998f402', 'E', 'Sinus tachycardia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bbab5435-0e3c-5ee5-8cd2-3dbb4ae5cb3e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 62 year old woman with ischaemic heart disease has stable angina that occurs when walking uphill. She is taking aspirin and atorvastatin and uses a GTN spray. Her heart rate is 78 beats/minute and BP 136/82 mmHg. What is the SINGLE most appropriate first-line regular anti-anginal drug?', 'NICE recommends a beta-blocker or a calcium channel blocker as first-line regular treatment for stable angina, with sublingual GTN for attacks. If one is not enough, combine a beta-blocker with a dihydropyridine CCB (such as amlodipine). Long-acting nitrates, ivabradine, nicorandil and ranolazine are second-line.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
