  ('28ac2457-2c03-5149-91f8-a8bc5aeac414', 'bbab5435-0e3c-5ee5-8cd2-3dbb4ae5cb3e', 'A', 'Bisoprolol', true, 0),
  ('58633ebe-f786-5e1e-b9bf-b3fa72e8e86e', 'bbab5435-0e3c-5ee5-8cd2-3dbb4ae5cb3e', 'B', 'Isosorbide mononitrate in combination with nicorandil', false, 1),
  ('a657ff06-b050-5f32-aec3-cec842e41fef', 'bbab5435-0e3c-5ee5-8cd2-3dbb4ae5cb3e', 'C', 'Ivabradine', false, 2),
  ('851be319-bd9c-5fda-b5f7-2606ddd51625', 'bbab5435-0e3c-5ee5-8cd2-3dbb4ae5cb3e', 'D', 'Ranolazine', false, 3),
  ('ee644040-aee9-537c-b64c-5091dee2cb68', 'bbab5435-0e3c-5ee5-8cd2-3dbb4ae5cb3e', 'E', 'Nicorandil', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('502e7729-d700-5197-bcd3-debf1f63ae69', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 66 year old man has typical exertional chest pain relieved by rest. He has never been investigated. His resting ECG is normal. According to NICE, what is the SINGLE most appropriate first-line diagnostic test for suspected stable angina?', 'NICE (CG95, updated) recommends 64-slice or above CT coronary angiography as the first-line test for typical or atypical angina, or non-anginal chest pain with ECG changes. Functional imaging (stress echo, perfusion MRI or SPECT) is used if CTCA is non-diagnostic. Exercise ECG is no longer recommended for diagnosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
