  ('4c19abe1-e4cb-5001-9ff5-ceb23ce4e2fb', '502e7729-d700-5197-bcd3-debf1f63ae69', 'A', 'Exercise tolerance test', false, 0),
  ('768de9b9-cd93-5096-b074-5ae94b9a6538', '502e7729-d700-5197-bcd3-debf1f63ae69', 'B', 'CT coronary angiography', true, 1),
  ('76b98126-a4c4-5a26-8b85-ca703d747cc2', '502e7729-d700-5197-bcd3-debf1f63ae69', 'C', 'Invasive coronary angiography', false, 2),
