insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7172a7ef-2e2a-57e5-95fd-d2b72cc3ae5b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 52 year old woman has a fasting total cholesterol of 9.4 mmol/L and LDL of 7.1 mmol/L. She has tendon xanthomas on her Achilles tendons. Her father had an MI aged 45. What is the SINGLE most likely diagnosis?', 'Tendon xanthomas, a very high LDL and premature coronary disease in a first-degree relative suggest familial hypercholesterolaemia (Simon Broome or Dutch Lipid Clinic criteria). It is usually autosomal dominant (LDL receptor mutation). Refer to a lipid clinic for genetic testing, high-intensity statin treatment and cascade testing of relatives.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d3337f08-b20d-541b-b151-829bb5044878', '7172a7ef-2e2a-57e5-95fd-d2b72cc3ae5b', 'A', 'Type 2 diabetes', false, 0),
  ('76e742b2-9a50-5694-be2c-be71f88ad4a4', '7172a7ef-2e2a-57e5-95fd-d2b72cc3ae5b', 'B', 'Familial combined hyperlipidaemia', false, 1),
  ('66c17daa-3c3f-56cf-a328-632ec1fffccc', '7172a7ef-2e2a-57e5-95fd-d2b72cc3ae5b', 'C', 'Familial hypercholesterolaemia', true, 2),
  ('ceb3c1ca-cbaf-5409-bdee-1e42d2281f23', '7172a7ef-2e2a-57e5-95fd-d2b72cc3ae5b', 'D', 'Nephrotic syndrome', false, 3),
  ('3326fe6e-577a-5aac-b121-4dcf48e595ef', '7172a7ef-2e2a-57e5-95fd-d2b72cc3ae5b', 'E', 'Hypothyroidism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('146b4f79-17ad-5425-afd4-6d40186d6cc2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 75 year old man had a drug-eluting stent 4 months ago and takes aspirin and ticagrelor. His dentist plans a single tooth extraction. What is the SINGLE most appropriate advice?', 'Stopping dual antiplatelet therapy early after a coronary stent risks stent thrombosis, which can be fatal. Simple dental extractions carry a low bleeding risk and can be done with local measures (packing, sutures, tranexamic acid mouthwash) while continuing antiplatelets. Any interruption should be discussed with cardiology.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('11ae4efc-754d-55ce-8f84-d5d0fb58ebcf', '146b4f79-17ad-5425-afd4-6d40186d6cc2', 'A', 'Stop aspirin for 10 days', false, 0),
  ('7524ec5c-c7a6-53b8-85f1-a158d032ef42', '146b4f79-17ad-5425-afd4-6d40186d6cc2', 'B', 'Continue both antiplatelet drugs and use local haemostatic measures', true, 1),
  ('7bab4426-655c-5b63-a2db-be43ea43c5a9', '146b4f79-17ad-5425-afd4-6d40186d6cc2', 'C', 'Stop both antiplatelets for 7 days', false, 2),
  ('a41ff990-299f-5664-9830-df11847f0ad7', '146b4f79-17ad-5425-afd4-6d40186d6cc2', 'D', 'Postpone all dental treatment for 2 years', false, 3),
  ('d93fe5a4-8a1d-5932-b830-567b94ea913e', '146b4f79-17ad-5425-afd4-6d40186d6cc2', 'E', 'Switch to warfarin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('62507bc3-39d3-54bc-bf87-0bf7f1ddad92', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 22 year old woman has palpitations, and her ECG shows sinus tachycardia of 112 beats/minute. Before treating, which investigation is MOST important to identify a reversible cause?', 'Sinus tachycardia is usually secondary: anaemia, thyrotoxicosis, infection, dehydration, anxiety, pain, pregnancy or stimulants. Thyroid function and a full blood count are key initial tests. Treatment targets the cause. Rate-limiting drugs are only for symptomatic inappropriate sinus tachycardia after investigation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
