  ('57d358eb-45d4-5a23-b671-930ab225dde2', '62507bc3-39d3-54bc-bf87-0bf7f1ddad92', 'A', 'Thyroid function tests', true, 0),
  ('fd6f8382-abd8-565d-92a0-68285e2ab1fe', '62507bc3-39d3-54bc-bf87-0bf7f1ddad92', 'B', 'Coronary angiography', false, 1),
  ('bf1da460-282d-519c-a96c-fb13cb8c932a', '62507bc3-39d3-54bc-bf87-0bf7f1ddad92', 'C', 'Echocardiogram', false, 2),
  ('5c997e75-c898-54a7-84b7-05aacbd57342', '62507bc3-39d3-54bc-bf87-0bf7f1ddad92', 'D', 'Electrophysiology study', false, 3),
