insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7b71b3dc-8467-557c-a000-fc1cbeaa1630', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 32 year old man is noted on examination to have a continuous ''machinery'' murmur below the left clavicle and bounding pulses. He was born at 30 weeks'' gestation. What is the SINGLE most likely diagnosis?', 'A continuous ''machinery'' murmur in the left infraclavicular area with bounding pulses and a wide pulse pressure is typical of patent ductus arteriosus, which is more common in premature babies and with maternal rubella. In preterm neonates, NSAIDs (indometacin or ibuprofen) can close it. Larger or persistent ducts are closed percutaneously or surgically.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4cd03e7b-3970-557e-b363-bd2fe440546e', '7b71b3dc-8467-557c-a000-fc1cbeaa1630', 'A', 'Patent ductus arteriosus', true, 0),
  ('a00ed22c-94c6-50c3-9cbf-9fb117552880', '7b71b3dc-8467-557c-a000-fc1cbeaa1630', 'B', 'Coarctation of the aorta', false, 1),
  ('0aaa353c-86b7-508c-9478-71608b8027cd', '7b71b3dc-8467-557c-a000-fc1cbeaa1630', 'C', 'Atrial septal defect', false, 2),
  ('a8314d7d-b238-5257-80f6-20cce11d6f0a', '7b71b3dc-8467-557c-a000-fc1cbeaa1630', 'D', 'Tetralogy of Fallot', false, 3),
  ('4bfff296-4a74-5065-98a1-f552daa009bf', '7b71b3dc-8467-557c-a000-fc1cbeaa1630', 'E', 'Ventricular septal defect', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('823fd76b-4399-53fe-aa34-31be8357afde', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 23 year old man has hypertension found at a medical. His right arm BP is 162/94 mmHg. His femoral pulses are weak and delayed compared with his radial pulses. There is a systolic murmur over his back. A chest X-ray shows rib notching. What is the SINGLE most likely diagnosis?', 'Radio-femoral delay, upper limb hypertension, a murmur heard between the scapulae and rib notching (from collateral intercostal arteries) are features of coarctation of the aorta. It is associated with Turner syndrome and bicuspid aortic valve. Treatment is balloon angioplasty with stenting or surgical repair.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f5766c07-f6a5-5f05-ac05-a92bebd6d0ad', '823fd76b-4399-53fe-aa34-31be8357afde', 'A', 'Coarctation of the aorta', true, 0),
  ('363b8913-8846-5d77-880a-f6fc53bc107a', '823fd76b-4399-53fe-aa34-31be8357afde', 'B', 'Renal artery stenosis', false, 1),
  ('48d77e02-60f3-50b4-aed6-75bdd6a05d34', '823fd76b-4399-53fe-aa34-31be8357afde', 'C', 'Phaeochromocytoma', false, 2),
  ('9a87cd94-400f-53c6-a7aa-204a8a8227c2', '823fd76b-4399-53fe-aa34-31be8357afde', 'D', 'Takayasu arteritis', false, 3),
  ('bc7b4431-756e-5750-b44a-0b4da65ecf0a', '823fd76b-4399-53fe-aa34-31be8357afde', 'E', 'Aortic dissection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6ebaed11-5c38-5a35-ba07-a60c554153c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 47 year old man has central chest pain at rest. His ECG shows ST elevation and T wave inversion in multiple leads. He took cocaine 1 hour ago. He is agitated and his BP is 178/102 mmHg. What is the SINGLE most appropriate initial drug treatment?', 'Cocaine causes coronary vasospasm, thrombosis and sympathetic overstimulation. First-line treatment is a benzodiazepine for agitation and hypertension, with GTN and aspirin. Beta-blockers should be avoided acutely because they can cause unopposed alpha stimulation and worsen spasm. Persistent ST elevation needs primary PCI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('666f1b2d-f760-583a-9204-25af2b42f779', '6ebaed11-5c38-5a35-ba07-a60c554153c2', 'A', 'Oral bisoprolol', false, 0),
  ('a51e5919-eedb-55df-8b99-823818f60a80', '6ebaed11-5c38-5a35-ba07-a60c554153c2', 'B', 'IV adenosine', false, 1),
  ('5bebbf0f-7596-51c0-adc5-020d2e7927eb', '6ebaed11-5c38-5a35-ba07-a60c554153c2', 'C', 'Immediate thrombolysis without further assessment', false, 2),
  ('84ada58a-1b95-5264-a80f-08d1fc2a76ac', '6ebaed11-5c38-5a35-ba07-a60c554153c2', 'D', 'IV benzodiazepine (such as lorazepam) and GTN', true, 3),
  ('1ed3cf4b-ee74-59c8-817c-b052960db286', '6ebaed11-5c38-5a35-ba07-a60c554153c2', 'E', 'IV propranolol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('89d91715-0c92-5580-8bcb-36f5bb8eff79', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 64 year old man has retrosternal chest pain for 1 hour and is seen in the Emergency Department. He had similar pain 12 hours earlier that lasted for 3 hours. His pulse rate is 40 bpm and BP 120/60 mmHg. He is currently pain free after administration of sublingual glyceryl trinitrate. He has also been given oral aspirin. Which is the most appropriate immediate test?', 'Ongoing or recent chest pain with bradycardia suggests an acute coronary syndrome, possibly an inferior MI with heart block. A 12-lead ECG must be done immediately (within 10 minutes) to identify STEMI, which needs emergency reperfusion. Troponin and other tests come afterwards.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('46774a86-daf9-5ae0-82f8-d6341c065219', '89d91715-0c92-5580-8bcb-36f5bb8eff79', 'A', 'Angiogram', false, 0),
  ('207769ce-ce86-590f-bb59-eadfa9f75352', '89d91715-0c92-5580-8bcb-36f5bb8eff79', 'B', 'Chest X-ray', false, 1),
  ('60b3314b-a509-5c64-a409-3dff63de13e9', '89d91715-0c92-5580-8bcb-36f5bb8eff79', 'C', 'Creatine kinase level', false, 2),
  ('9b3aed92-a035-5343-9860-1a859f606fcf', '89d91715-0c92-5580-8bcb-36f5bb8eff79', 'D', 'ECG', true, 3),
  ('a8faa5ba-9d03-57f6-9f9d-b97df07081b4', '89d91715-0c92-5580-8bcb-36f5bb8eff79', 'E', 'Troponin level', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a0b5eaaa-dc0e-5b94-bc0e-33e7f3c944cb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 27 year old man has recurrent episodes of fainting and is seen in the cardiology clinic. His pulse rate is 74 bpm and BP 110/60 mmHg. Cardiac examination is normal.  [The ECG (an image in the original paper) shows a prolonged corrected QT interval.] Which is the most likely cause of his syncope?', 'Recurrent syncope in a young man with a prolonged corrected QT interval on ECG suggests long QT syndrome, which predisposes to torsades de pointes. Management includes avoiding QT-prolonging drugs, beta-blockers and sometimes an ICD. (The original question shows an ECG image; it is described in the text here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a0a19a52-f3e5-556d-9f61-326f970ac43a', 'a0b5eaaa-dc0e-5b94-bc0e-33e7f3c944cb', 'A', 'Long QT syndrome', true, 0),
  ('e63397d0-8802-5711-a256-3076c160aaa8', 'a0b5eaaa-dc0e-5b94-bc0e-33e7f3c944cb', 'B', 'Paroxysmal atrial fibrillation', false, 1),
  ('41341eee-f2fa-55fd-820b-2bca146613f5', 'a0b5eaaa-dc0e-5b94-bc0e-33e7f3c944cb', 'C', 'Sick sinus syndrome', false, 2),
  ('63a3365c-a1b9-5c8d-a04b-e511cb5ac74b', 'a0b5eaaa-dc0e-5b94-bc0e-33e7f3c944cb', 'D', 'Trifascicular block', false, 3),
  ('b368dfb1-4beb-56cf-9d73-587c69e03dbb', 'a0b5eaaa-dc0e-5b94-bc0e-33e7f3c944cb', 'E', 'Wolff-Parkinson-White syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('782e0f70-e680-55b7-81a5-a171dc504178', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 61 year old man is breathless at rest and is brought to the Emergency Department. He has a worsening cough and shortness of breath on walking for 4 months. He is an ex-smoker with a 40 pack-year history. His pulse rate is 105 bpm, irregular and BP 100/65 mmHg. He has bilateral inspiratory crepitations in the lung bases with scattered wheeze. Investigation:  [The chest X-ray (an image in the original paper) shows cardiomegaly, upper lobe venous diversion, interstitial oedema and small bilateral pleural effusions.] Which is the most likely diagnosis?', 'Breathlessness, irregular tachycardia (likely AF), bibasal crackles and wheeze (''cardiac asthma'') with typical X-ray changes (cardiomegaly, upper lobe diversion, interstitial oedema, effusions) indicate left ventricular failure. Management includes diuretics and treating the AF. (The original question shows a chest X-ray image; it is described in the text here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('96894003-bc2b-52f4-9777-131d2bec662c', '782e0f70-e680-55b7-81a5-a171dc504178', 'A', 'Bronchopneumonia', false, 0),
  ('6576d504-d776-5c8a-bc5d-1b957afec806', '782e0f70-e680-55b7-81a5-a171dc504178', 'B', 'Chronic obstructive pulmonary disease', false, 1),
  ('5b7262d6-4bf1-54e2-9018-cf15957af2f3', '782e0f70-e680-55b7-81a5-a171dc504178', 'C', 'Left ventricular failure', true, 2),
  ('d1ed4b16-4ccc-5e3c-b90f-d2515b19fcd4', '782e0f70-e680-55b7-81a5-a171dc504178', 'D', 'Pulmonary embolus', false, 3),
  ('ff9c2648-9a90-5f6f-b1a0-bb142b41ac81', '782e0f70-e680-55b7-81a5-a171dc504178', 'E', 'Pulmonary fibrosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ddc4e56f-cbae-51be-890c-d5f560676791', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old boy is brought to the Emergency Department with a fever for 6 days that has not responded to paracetamol. On examination he has bilateral non-purulent conjunctival injection, red cracked lips, a strawberry tongue, a polymorphous rash on his trunk and swollen, red hands and feet. He has a single enlarged cervical lymph node. What is the SINGLE most important investigation to arrange?', 'Fever for 5 days or more plus conjunctivitis, mucosal changes, rash, extremity changes and cervical lymphadenopathy is Kawasaki disease. The most important complication is coronary artery aneurysm, so an echocardiogram is essential at diagnosis and during follow-up. Treatment is IV immunoglobulin and aspirin, which is one of the few situations where aspirin is used in children.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9d46c218-0c44-5a42-aa31-023deaac363a', 'ddc4e56f-cbae-51be-890c-d5f560676791', 'A', 'Echocardiogram', true, 0),
  ('62e079e7-2525-5549-8a73-fee77bfe1129', 'ddc4e56f-cbae-51be-890c-d5f560676791', 'B', 'Antistreptolysin O titre', false, 1),
  ('4147cabf-c53c-53db-89fb-2e31ca56cb7f', 'ddc4e56f-cbae-51be-890c-d5f560676791', 'C', 'Throat swab', false, 2),
  ('bdee8654-c564-54dc-82b1-61d0189637cc', 'ddc4e56f-cbae-51be-890c-d5f560676791', 'D', 'Blood cultures', false, 3),
  ('6b31f8d4-1456-5057-9836-be16a817d747', 'ddc4e56f-cbae-51be-890c-d5f560676791', 'E', 'Lumbar puncture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('95e23eb7-8fdb-57a7-b405-bf1100519d91', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 week old boy is brought to his GP with a 4-day history of forceful vomiting after every feed. The vomit is milky and contains no bile. Between episodes he feeds hungrily. He has had fewer wet nappies. On examination during a test feed, a small firm mass is palpable in the right upper quadrant. Which of the following blood gas findings is MOST likely?', 'Projectile non-bilious vomiting in a hungry infant aged 2 to 8 weeks with an olive-shaped mass is pyloric stenosis. Repeated loss of gastric acid (HCl) causes hypochloraemic metabolic alkalosis. Hypokalaemia follows from the kidneys exchanging potassium to retain sodium and water when the infant is dehydrated. The diagnosis is confirmed by ultrasound. These derangements are corrected with IV fluids before Ramstedt pyloromyotomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b11cdaee-e5bf-579d-b49e-3faec1073cca', '95e23eb7-8fdb-57a7-b405-bf1100519d91', 'A', 'Hyperchloraemic metabolic acidosis', false, 0),
  ('8d04734f-1b96-5ed5-adbe-a49fb9c140ec', '95e23eb7-8fdb-57a7-b405-bf1100519d91', 'B', 'Respiratory acidosis', false, 1),
  ('cc606922-b53a-5216-af93-54cbb9429109', '95e23eb7-8fdb-57a7-b405-bf1100519d91', 'C', 'Respiratory alkalosis', false, 2),
  ('15daa9b1-0788-577c-8bf1-235217f68c20', '95e23eb7-8fdb-57a7-b405-bf1100519d91', 'D', 'Hypochloraemic, hypokalaemic metabolic alkalosis', true, 3),
  ('3914bb68-0c34-59d9-a41e-eef9a360f089', '95e23eb7-8fdb-57a7-b405-bf1100519d91', 'E', 'Hyperkalaemic metabolic acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('afb5e1ca-b8f7-5f9b-ad68-23748f6f3e68', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 month old girl is brought to the Emergency Department by her father, who says she rolled off the sofa onto a carpeted floor earlier today. She cries when her left leg is moved. An X-ray shows a spiral fracture of the left femoral shaft. She is not yet crawling or pulling to stand. There are some small bruises on her upper arms. What is the SINGLE most appropriate next step?', 'A long-bone fracture in a non-mobile infant, with an explanation that does not fit the injury and unexplained bruising, strongly suggests non-accidental injury. The child must be kept safe: admit and involve the senior paediatrician and safeguarding team, who will arrange a skeletal survey, CT head, ophthalmology review and a referral to children''s social care. Investigations should happen as an inpatient, not as an outpatient. Police involvement is coordinated through the safeguarding process.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cd7f8a20-c000-54cf-a56b-9eabcf9f8f7c', 'afb5e1ca-b8f7-5f9b-ad68-23748f6f3e68', 'A', 'Arrange an outpatient skeletal survey', false, 0),
  ('a6992f0b-3e36-50c9-a570-6ff04c45fca3', 'afb5e1ca-b8f7-5f9b-ad68-23748f6f3e68', 'B', 'Send a bone profile and discharge with follow-up', false, 1),
  ('e0b7ca2b-266c-514f-ba6d-ad94f06c9d1f', 'afb5e1ca-b8f7-5f9b-ad68-23748f6f3e68', 'C', 'Apply a cast and discharge with analgesia', false, 2),
  ('abd22920-a6d1-59b0-9a6c-fef4949a6e9c', 'afb5e1ca-b8f7-5f9b-ad68-23748f6f3e68', 'D', 'Contact the police before any further assessment', false, 3),
  ('87e68ba7-ce7b-540d-9125-4a50cbe30477', 'afb5e1ca-b8f7-5f9b-ad68-23748f6f3e68', 'E', 'Admit and refer to the paediatric team under safeguarding procedures', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d44e1b49-5bd1-53ae-9579-c4dc33096d57', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 month old boy is brought to his GP with a 3-day history of runny nose, cough and mild difficulty feeding. He is taking about 80% of his usual feeds and has normal wet nappies. On examination there are fine bilateral inspiratory crackles and a mild wheeze. Respiratory rate is 44 breaths/minute, oxygen saturation 96% on air and there is no recession. What is the SINGLE most appropriate management?', 'This is mild bronchiolitis, usually caused by RSV. Management is supportive: small frequent feeds, nasal saline if needed, and clear advice on red flags (worsening breathing, poor feeding under 50-75%, fewer wet nappies, apnoea). NICE advises against salbutamol, corticosteroids, antibiotics and hypertonic saline for bronchiolitis. Admission is considered for apnoea, oxygen saturation below 92%, severe respiratory distress or inadequate fluid intake.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('15eebf96-73ca-5d8e-8ac6-ebab55fb02bf', 'd44e1b49-5bd1-53ae-9579-c4dc33096d57', 'A', 'Nebulised hypertonic saline', false, 0),
  ('d697b8ec-7c8e-540a-8663-65442f1e31cd', 'd44e1b49-5bd1-53ae-9579-c4dc33096d57', 'B', 'Oral amoxicillin', false, 1),
  ('9aadf9fd-53c0-5f0b-8b76-02798242b65c', 'd44e1b49-5bd1-53ae-9579-c4dc33096d57', 'C', 'Inhaled salbutamol', false, 2),
  ('8901c368-dd90-58cf-828d-cbac9590d1c9', 'd44e1b49-5bd1-53ae-9579-c4dc33096d57', 'D', 'Supportive care at home with safety-netting advice', true, 3),
  ('cee95c25-064b-5c00-bb32-8ac003b4a67b', 'd44e1b49-5bd1-53ae-9579-c4dc33096d57', 'E', 'Oral prednisolone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bd8c3f67-a5b6-55cc-b0f8-4e63c38019e6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 year old boy is brought in at night with a barking cough, a hoarse voice and noisy breathing that started after 2 days of coryza. He has inspiratory stridor only when upset, with mild subcostal recession. He is alert, drinking well and his oxygen saturation is 97% on air. What is the SINGLE most appropriate treatment?', 'This is mild croup (laryngotracheobronchitis), usually caused by parainfluenza virus. NICE CKS recommends a single dose of oral dexamethasone (0.15 mg/kg) for all children with croup, and most mild cases can go home with safety-netting. Nebulised adrenaline is used for severe croup with significant distress while senior help is sought. Avoid examining the throat if epiglottitis is a possibility.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e11e6b3a-7174-5f42-9aac-debe61805f44', 'bd8c3f67-a5b6-55cc-b0f8-4e63c38019e6', 'A', 'Nebulised salbutamol', false, 0),
  ('fec3fbf3-e94d-5b14-b5b7-d9166e1037cd', 'bd8c3f67-a5b6-55cc-b0f8-4e63c38019e6', 'B', 'Single dose of oral dexamethasone 0.15 mg/kg', true, 1),
  ('ca1fa1a3-9a27-5c25-8a09-6f7cfa61d7ea', 'bd8c3f67-a5b6-55cc-b0f8-4e63c38019e6', 'C', 'No treatment', false, 2),
  ('6034f4ed-a805-55b2-a656-cce3ef366094', 'bd8c3f67-a5b6-55cc-b0f8-4e63c38019e6', 'D', 'Nebulised adrenaline and admission to intensive care', false, 3),
  ('a75eadc9-4856-5160-aa7b-3caa39cad70d', 'bd8c3f67-a5b6-55cc-b0f8-4e63c38019e6', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a84c415a-bdb3-5906-8877-fb7f5069c9f5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 20 month old girl has a generalised tonic-clonic seizure lasting 2 minutes at home while she has a fever of 39.2°C from a viral upper respiratory infection. In the Emergency Department 1 hour later she is alert, playing and has no neck stiffness, rash or focal neurology. This is her first seizure. What is the SINGLE most likely diagnosis?', 'Simple febrile seizures occur between 6 months and 5 years, are generalised, last under 15 minutes, do not recur within 24 hours and are followed by full recovery. Management is to treat the cause of the fever and reassure parents. Antipyretics improve comfort but do not prevent further seizures, and there is only a slightly increased risk of epilepsy. Complex febrile seizures are focal, last over 15 minutes or recur within the same illness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('950abc99-8d60-55ac-b4a9-c1c4cad85f0e', 'a84c415a-bdb3-5906-8877-fb7f5069c9f5', 'A', 'Encephalitis', false, 0),
  ('0f450d2e-96a2-52b0-a84d-19adea4315c0', 'a84c415a-bdb3-5906-8877-fb7f5069c9f5', 'B', 'Epilepsy', false, 1),
  ('d12f6a0d-f772-50a3-b799-25b498accec0', 'a84c415a-bdb3-5906-8877-fb7f5069c9f5', 'C', 'Complex febrile seizure', false, 2),
  ('51cc85bd-bcee-5bd8-9686-efdd0cb79fe7', 'a84c415a-bdb3-5906-8877-fb7f5069c9f5', 'D', 'Simple febrile seizure', true, 3),
  ('9e5e5320-c22c-55e6-aae6-3b547aaeff53', 'a84c415a-bdb3-5906-8877-fb7f5069c9f5', 'E', 'Bacterial meningitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('910d2cba-51cc-5f58-a683-5575d307a4aa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 9 month old boy has episodes of inconsolable crying every 15-20 minutes, during which he draws his knees up to his chest and goes pale. Between episodes he is lethargic. He has vomited twice and passed a stool mixed with dark red blood and mucus. A sausage-shaped mass is felt in the right upper quadrant. What is the SINGLE most appropriate investigation?', 'Intermittent colicky pain with drawing up of the legs, ''redcurrant jelly'' stool and a sausage-shaped mass in an infant aged 6-18 months is intussusception. Ultrasound shows a ''target'' sign. After resuscitation, first-line treatment is air (pneumatic) enema reduction under radiological guidance, unless there is peritonitis or perforation, in which case surgery is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('38709f00-5581-5260-a1c6-2d7daa22f31d', '910d2cba-51cc-5f58-a683-5575d307a4aa', 'A', 'Abdominal CT with contrast as first-line', false, 0),
  ('14556cde-5d8d-5f9c-9231-dbefe8033261', '910d2cba-51cc-5f58-a683-5575d307a4aa', 'B', 'Stool culture only', false, 1),
  ('281edac7-d1ba-5e86-803e-7e1083efbe81', '910d2cba-51cc-5f58-a683-5575d307a4aa', 'C', 'Abdominal ultrasound', true, 2),
  ('22d3177f-f094-57bf-bafa-1166f215903f', '910d2cba-51cc-5f58-a683-5575d307a4aa', 'D', 'Barium swallow', false, 3),
  ('25535a44-3d8a-5d45-bdd3-de7d0a1f6008', '910d2cba-51cc-5f58-a683-5575d307a4aa', 'E', 'Upper GI endoscopy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5f7dc287-3e96-50c3-8022-b508f218317c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'At the 6-week baby check, a girl born by breech delivery has a ''clunk'' felt on Barlow and Ortolani manoeuvres of the left hip. Her mother also had hip problems as a child. What is the SINGLE most appropriate management?', 'Developmental dysplasia of the hip is suggested by an unstable hip on Barlow (dislocates) or Ortolani (relocates) tests. Risk factors include breech presentation, family history, female sex and being firstborn. An unstable hip at the 6-week check needs urgent ultrasound and orthopaedic review. Babies with breech presentation or a family history get a screening ultrasound by 6 weeks even if the examination is normal. Treatment is usually a Pavlik harness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('62629ddb-3053-5ded-bbaf-c25e939983f9', '5f7dc287-3e96-50c3-8022-b508f218317c', 'A', 'Reassure; it will resolve without treatment', false, 0),
  ('ac2a2be8-7d7e-5b10-bc74-2ffd27bf6b5c', '5f7dc287-3e96-50c3-8022-b508f218317c', 'B', 'Repeat examination at 1 year', false, 1),
  ('36304530-2ef7-5aff-ab65-286c8ebf9b1d', '5f7dc287-3e96-50c3-8022-b508f218317c', 'C', 'Hip X-ray at 6 months', false, 2),
  ('18ce3457-78f9-5836-92d5-4e7292c9e5b3', '5f7dc287-3e96-50c3-8022-b508f218317c', 'D', 'Urgent referral for hip ultrasound and orthopaedic review', true, 3),
  ('3e7b80f1-2d6e-5278-87ee-c3c059c5615d', '5f7dc287-3e96-50c3-8022-b508f218317c', 'E', 'Refer to physiotherapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('000e6dec-b070-5081-9b6b-81a80c7934f4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A baby boy born at 38 weeks is noted to be jaundiced at 18 hours of age. His mother is blood group O Rh-positive and the baby is group A Rh-positive. His serum bilirubin is above the phototherapy threshold for his age. What is the SINGLE most likely cause?', 'Jaundice within the first 24 hours of life is always pathological, and haemolysis is the most common cause. ABO incompatibility (a mother with group O and a baby with group A or B) is now more common than rhesus disease, and the direct antiglobulin (Coombs) test is usually positive. He needs urgent bilirubin monitoring and phototherapy, with exchange transfusion if levels are very high. Physiological jaundice appears after 24 hours. Prolonged jaundice (over 14 days) needs investigation for biliary atresia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f99d3968-737c-50e5-87bb-7debe61a9ee0', '000e6dec-b070-5081-9b6b-81a80c7934f4', 'A', 'Breast milk jaundice', false, 0),
  ('bfc56170-0cf6-5c99-aacd-3f9d396a9a90', '000e6dec-b070-5081-9b6b-81a80c7934f4', 'B', 'ABO haemolytic disease of the newborn', true, 1),
  ('60082d23-2367-5ccd-b6d3-2772ac42783a', '000e6dec-b070-5081-9b6b-81a80c7934f4', 'C', 'Gilbert''s syndrome', false, 2),
  ('e923d575-a427-588a-a4e1-6e0bf1bf090a', '000e6dec-b070-5081-9b6b-81a80c7934f4', 'D', 'Biliary atresia', false, 3),
  ('ee3cbde3-db69-5736-ac61-47be7ed1fa8a', '000e6dec-b070-5081-9b6b-81a80c7934f4', 'E', 'Physiological jaundice', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cc52e7f1-8a1c-5563-99c4-bc9f5aee331e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 week old boy has not passed meconium for the first 48 hours of life and now has abdominal distension and bilious vomiting. Rectal examination produces a forceful gush of stool and gas. He has Down syndrome. What is the SINGLE most appropriate investigation to confirm the diagnosis?', 'Delayed passage of meconium (over 48 hours), distension and an ''explosive'' gush on rectal examination suggest Hirschsprung''s disease, the absence of ganglion cells in the distal bowel. It is more common in boys and in Down syndrome. A rectal suction biopsy showing absent ganglion cells is diagnostic. Treatment is bowel washouts and later surgical resection (pull-through). Watch for Hirschsprung-associated enterocolitis. Meconium ileus suggests cystic fibrosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5fbcff3e-464b-5daa-955b-ba5a22820c14', 'cc52e7f1-8a1c-5563-99c4-bc9f5aee331e', 'A', 'Abdominal ultrasound', false, 0),
  ('888a4431-898d-5b2f-b07d-d088f6668779', 'cc52e7f1-8a1c-5563-99c4-bc9f5aee331e', 'B', 'Barium swallow', false, 1),
  ('15f5245c-fde4-5921-ac9d-e28cfb140d2e', 'cc52e7f1-8a1c-5563-99c4-bc9f5aee331e', 'C', 'Thyroid function tests', false, 2),
  ('7aacb6b3-60d8-583e-989d-a36ce5016efb', 'cc52e7f1-8a1c-5563-99c4-bc9f5aee331e', 'D', 'Rectal suction biopsy', true, 3),
  ('afcc812e-0737-539f-bcb7-503f1970a3ef', 'cc52e7f1-8a1c-5563-99c4-bc9f5aee331e', 'E', 'Sweat test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('33cd302e-0771-5f57-864d-ecca70e26c9b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 year old boy has a raised purpuric rash over his buttocks and the backs of his legs, swollen painful ankles and colicky abdominal pain. He had a sore throat 2 weeks ago. His platelet count is normal. Urine dipstick shows blood +. Blood pressure is normal. What is the SINGLE most likely diagnosis?', 'A palpable purpuric rash on the buttocks and legs with a normal platelet count, arthralgia, abdominal pain and renal involvement in a child after an infection is IgA vasculitis (HSP). It is usually self-limiting. Monitor blood pressure and urinalysis regularly for at least 6 months for nephritis. ITP causes a non-palpable petechial rash with a low platelet count. Complications include intussusception.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d89df79d-a02a-567e-aea8-0bd367b521f7', '33cd302e-0771-5f57-864d-ecca70e26c9b', 'A', 'Meningococcal septicaemia', false, 0),
  ('f7c4b448-46f6-5b9d-b245-06fbe2f3da44', '33cd302e-0771-5f57-864d-ecca70e26c9b', 'B', 'Acute lymphoblastic leukaemia', false, 1),
  ('84e74950-c2a8-5edf-be3f-e40c934e0d51', '33cd302e-0771-5f57-864d-ecca70e26c9b', 'C', 'Immune thrombocytopenic purpura', false, 2),
  ('d9e163ff-91a1-52db-bde1-4c84650796db', '33cd302e-0771-5f57-864d-ecca70e26c9b', 'D', 'Henoch-Schönlein purpura (IgA vasculitis)', true, 3),
  ('95f0192d-fc56-59f3-b755-217a7130783f', '33cd302e-0771-5f57-864d-ecca70e26c9b', 'E', 'Non-accidental injury', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cf8e3d6f-34f0-5bcf-bcef-c14148186ce6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A mother is worried about her 12 month old son''s development. He pulls to stand and walks holding onto furniture, has a mature pincer grip, says ''mama'' and ''dada'' to the right parent, and waves bye-bye. He cannot yet walk on his own. What is the SINGLE most appropriate response?', 'At 12 months, typical milestones are cruising (walking around furniture), a mature pincer grip, 1-3 words with meaning, waving and understanding simple commands. Walking on their own is usual by 12-15 months. A red flag is not walking by 18 months, which needs referral and a creatine kinase in boys to exclude Duchenne muscular dystrophy. He is developing normally.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2a442017-21b6-58f4-9b1d-4ee3922b3516', 'cf8e3d6f-34f0-5bcf-bcef-c14148186ce6', 'A', 'Refer urgently to a paediatric neurologist', false, 0),
  ('4c2a44c6-1787-5328-8cc5-ba2062153ea4', 'cf8e3d6f-34f0-5bcf-bcef-c14148186ce6', 'B', 'Arrange a creatine kinase level', false, 1),
  ('e3177a0c-8ed9-530e-b126-3e36f9ec1dea', 'cf8e3d6f-34f0-5bcf-bcef-c14148186ce6', 'C', 'Arrange a hearing test', false, 2),
  ('46c7e45a-67b8-531b-8488-385e9f6335af', 'cf8e3d6f-34f0-5bcf-bcef-c14148186ce6', 'D', 'Refer to physiotherapy', false, 3),
  ('29fd5766-290a-5e6b-8c77-cc52a441487c', 'cf8e3d6f-34f0-5bcf-bcef-c14148186ce6', 'E', 'Reassure: his development is appropriate for his age', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e9834c0c-b02c-50e7-80ce-f6930a91595d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 year old unvaccinated girl presents with 4 days of high fever, cough, coryza and red eyes, followed by a red maculopapular rash that started behind her ears and spread down her body. On examination there are small white spots on the buccal mucosa opposite the molars. What is the SINGLE most likely diagnosis?', 'Prodromal fever with cough, coryza and conjunctivitis, Koplik''s spots and a maculopapular rash spreading from behind the ears downwards is measles. It is a notifiable disease, so the local health protection team must be informed. Complications include otitis media, pneumonia (the most common cause of death), encephalitis and, years later, subacute sclerosing panencephalitis. Unvaccinated contacts may be offered MMR or immunoglobulin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('36ab7282-1ccd-5e09-90b6-628381f65f00', 'e9834c0c-b02c-50e7-80ce-f6930a91595d', 'A', 'Rubella', false, 0),
  ('fc3ae883-f8a3-555b-98aa-6eadfa3dd0c0', 'e9834c0c-b02c-50e7-80ce-f6930a91595d', 'B', 'Scarlet fever', false, 1),
  ('60b9f19c-ed21-5307-8966-e05c7c60f985', 'e9834c0c-b02c-50e7-80ce-f6930a91595d', 'C', 'Roseola infantum', false, 2),
  ('61541489-2239-53c0-bf7a-901d10d3784a', 'e9834c0c-b02c-50e7-80ce-f6930a91595d', 'D', 'Measles', true, 3),
  ('9bc53a4b-d8b1-5fcc-83eb-de81ea085229', 'e9834c0c-b02c-50e7-80ce-f6930a91595d', 'E', 'Chickenpox', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('20c4c7e0-0b49-58e2-b6cb-61729992d260', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old girl is brought in with a sudden high fever and sore throat over 4 hours. She is sitting upright and leaning forward, drooling, with soft inspiratory stridor and looks toxic. She has not had all her childhood immunisations. What is the SINGLE most appropriate immediate action?', 'This is acute epiglottitis, often caused by Haemophilus influenzae type b in unvaccinated children, and it can cause sudden complete airway obstruction. Do not examine the throat, lie the child down, cannulate or cause distress. Call senior anaesthetic, ENT and paediatric help to secure the airway in theatre. IV ceftriaxone is given once the airway is secured, and close contacts need prophylaxis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('32b2621e-6db5-56b0-aaba-91b4347ae95a', '20c4c7e0-0b49-58e2-b6cb-61729992d260', 'A', 'Give oral dexamethasone and discharge', false, 0),
  ('e24076ab-6a69-504a-81a7-8e63c394a44d', '20c4c7e0-0b49-58e2-b6cb-61729992d260', 'B', 'Arrange a lateral neck X-ray in radiology', false, 1),
  ('ac5b24e2-aedb-5e7c-9bb1-c0b6bc1a9b5a', '20c4c7e0-0b49-58e2-b6cb-61729992d260', 'C', 'Lie her flat and take blood cultures', false, 2),
  ('77049d3b-c40c-57ef-b769-bfdb0dab34f4', '20c4c7e0-0b49-58e2-b6cb-61729992d260', 'D', 'Examine her throat with a tongue depressor', false, 3),
  ('f55d7e3a-b57b-5796-84d1-13fde10039da', '20c4c7e0-0b49-58e2-b6cb-61729992d260', 'E', 'Keep her calm with her parent and call senior anaesthetic and ENT help immediately', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('855d42b8-df90-5535-9898-e21b29784544', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 month old baby has 2 weeks of coughing fits ending in a high-pitched inspiratory sound and vomiting. During the fits she goes red and once went blue. Between episodes she is well. Her mother was not vaccinated in pregnancy. What is the SINGLE most appropriate treatment?', 'Paroxysmal cough with an inspiratory ''whoop'', post-tussive vomiting and cyanosis is whooping cough (pertussis), caused by Bordetella pertussis. Infants under 6 months are at high risk and usually need admission. A macrolide (clarithromycin in infants over 1 month, azithromycin under 1 month) is given if the cough started within the last 21 days to reduce spread. Pertussis is notifiable. Pregnant women are offered the vaccine from 16 weeks to protect their newborns.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ea77f56f-ba59-5165-87e5-4bbb4604c4b7', '855d42b8-df90-5535-9898-e21b29784544', 'A', 'No treatment; it is viral', false, 0),
  ('7df86747-ecc7-5ea8-902a-98df328bedbf', '855d42b8-df90-5535-9898-e21b29784544', 'B', 'Oral prednisolone', false, 1),
  ('5d476cb4-bc44-5bd4-a7f9-da20f9f4696f', '855d42b8-df90-5535-9898-e21b29784544', 'C', 'Oral clarithromycin', true, 2),
  ('92d114e3-027f-586f-aa1d-e6d6ac0306e5', '855d42b8-df90-5535-9898-e21b29784544', 'D', 'Nebulised salbutamol', false, 3),
  ('25f1f0b0-4744-5fd0-b7fe-795f59a4c1e4', '855d42b8-df90-5535-9898-e21b29784544', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('71100557-7e77-5826-b25f-def0f25f305e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A baby boy born at 29 weeks'' gestation develops grunting, nasal flaring, intercostal recession and cyanosis within 2 hours of birth. His mother did not receive antenatal steroids. A chest X-ray shows a diffuse ''ground-glass'' appearance with air bronchograms. What is the SINGLE most likely diagnosis?', 'Respiratory distress soon after birth in a premature baby, with ground-glass lungs and air bronchograms, is RDS caused by surfactant deficiency. Antenatal corticosteroids given to the mother reduce its incidence. Management is respiratory support with CPAP or ventilation and endotracheal surfactant. Transient tachypnoea of the newborn is more common after caesarean section at term and resolves within a few days.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('52984af5-ea4d-5a84-88f3-05ff7375c0ed', '71100557-7e77-5826-b25f-def0f25f305e', 'A', 'Transient tachypnoea of the newborn', false, 0),
  ('a4038b7d-74d0-5db0-9a92-901fe3395af4', '71100557-7e77-5826-b25f-def0f25f305e', 'B', 'Congenital diaphragmatic hernia', false, 1),
  ('8142bedb-c946-5256-a7be-f2f3663cd481', '71100557-7e77-5826-b25f-def0f25f305e', 'C', 'Group B streptococcal pneumonia', false, 2),
  ('5d9ea744-c72d-5427-96ca-afb4f99923f1', '71100557-7e77-5826-b25f-def0f25f305e', 'D', 'Meconium aspiration syndrome', false, 3),
  ('144d9de3-a2f2-57c6-b62a-a08e0f592d2a', '71100557-7e77-5826-b25f-def0f25f305e', 'E', 'Neonatal respiratory distress syndrome (surfactant deficiency)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('20463aba-f29a-52ca-8221-411efad76407', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 week old baby girl has been vomiting bright green fluid for 6 hours. She was previously well and feeding. Her abdomen is mildly distended, and she is irritable. What is the SINGLE most appropriate investigation?', 'Bilious vomiting in a neonate is malrotation with volvulus until proven otherwise, a surgical emergency because the midgut can become ischaemic within hours. An urgent upper GI contrast study shows the abnormal position of the duodenojejunal flexure. Treatment is an emergency Ladd''s procedure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
