  ('c6137df3-25ee-577e-8b7b-bdb8683c2e26', '20463aba-f29a-52ca-8221-411efad76407', 'A', 'Observation and repeat feeds', false, 0),
  ('64d8511e-2098-55a5-862d-faf18650d746', '20463aba-f29a-52ca-8221-411efad76407', 'B', 'Stool culture', false, 1),
  ('c9dd75fb-a3c5-5c50-8a09-0e1346230c05', '20463aba-f29a-52ca-8221-411efad76407', 'C', 'Barium enema', false, 2),
  ('45e07bb7-73cc-56e7-b9d2-0bf4434fafd3', '20463aba-f29a-52ca-8221-411efad76407', 'D', 'Abdominal ultrasound for pyloric stenosis', false, 3),
  ('d9697613-7a74-5307-9287-ca7188731586', '20463aba-f29a-52ca-8221-411efad76407', 'E', 'Urgent upper GI contrast study', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a2883d49-148e-5552-bcae-d401ab64198c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 year old boy has a fever of 39°C, irritability and pulls at his right ear. He has a 2-day history of coryza. He has had three similar episodes this year. He is eating and drinking normally. Which feature would MOST strongly indicate immediate antibiotics?', 'Most acute otitis media resolves without antibiotics. NICE recommends immediate antibiotics if the child is systemically unwell, at high risk of complications, has otorrhoea after perforation, or is under 2 with bilateral infection. Amoxicillin for 5-7 days is first-line, or clarithromycin in penicillin allergy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0bad712e-afc4-51db-a016-cc40182acb7a', 'a2883d49-148e-5552-bcae-d401ab64198c', 'A', 'Pulling at the ear', false, 0),
  ('d2529284-6dab-5a9d-a5ee-d24ab987969a', 'a2883d49-148e-5552-bcae-d401ab64198c', 'B', 'Previous episodes', false, 1),
  ('430d9eb1-a482-5cfa-a1e9-a7e9f0c047ac', 'a2883d49-148e-5552-bcae-d401ab64198c', 'C', 'Discharge from the ear (otorrhoea)', true, 2),
  ('9a39e1fe-f0f5-5f98-87d8-9d9527ce5814', 'a2883d49-148e-5552-bcae-d401ab64198c', 'D', 'Coryza', false, 3),
  ('5166e1da-5d06-5580-88b2-412b15070742', 'a2883d49-148e-5552-bcae-d401ab64198c', 'E', 'Fever of 38.5°C', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7188290a-7672-5796-809b-f95b76989cd7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 year old girl has a fever of 39.5°C. Her mother reports that she is not responding normally to social cues and is difficult to wake. Her capillary refill is 4 seconds. Using the NICE traffic light system, what is the SINGLE most appropriate action?', 'NICE traffic light: red features (not responding to social cues, cannot be woken or does not stay awake, weak high-pitched cry, grunting, reduced skin turgor, non-blanching rash, bulging fontanelle, neck stiffness, seizures, or age under 3 months with temperature 38°C or above) need urgent referral to paediatric specialist care. Amber features need safety-netting or referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c2a829b3-d15d-5c5a-b663-b1066295f7da', '7188290a-7672-5796-809b-f95b76989cd7', 'A', 'Review in the GP practice in 48 hours', false, 0),
  ('50298f13-99fe-5b07-970d-37f463ad0195', '7188290a-7672-5796-809b-f95b76989cd7', 'B', 'Advise paracetamol and safety-net', false, 1),
  ('dfa970fa-794e-5a37-ab7d-1dbac09a806b', '7188290a-7672-5796-809b-f95b76989cd7', 'C', 'Urgent face-to-face assessment and referral to paediatrics (red features)', true, 2),
  ('1d1c7e52-407b-59ab-9d80-ece617231830', '7188290a-7672-5796-809b-f95b76989cd7', 'D', 'Prescribe oral antibiotics and discharge', false, 3),
  ('3741e3c8-cfab-5312-958e-5a41874696f9', '7188290a-7672-5796-809b-f95b76989cd7', 'E', 'Arrange a urine sample in 1 week', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('988c28de-9f32-5af8-a081-3348183ca09b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 9 year old girl has had a sore throat for 2 days, fever and tender anterior cervical lymph nodes. Her tonsils have exudate and she has no cough. What is her FeverPAIN score and the SINGLE most appropriate management?', 'FeverPAIN scores 1 point each for Fever, Purulence, Attend rapidly (within 3 days), Inflamed tonsils and No cough or coryza. She scores 5 (fever, exudate, attended within 3 days, inflamed tonsils, no cough). NICE: a score of 4-5 means consider an immediate antibiotic (phenoxymethylpenicillin for 5-10 days), 2-3 means a back-up prescription, and 0-1 means no antibiotic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d9dab425-fa96-572c-b327-986f3ae9f0e7', '988c28de-9f32-5af8-a081-3348183ca09b', 'A', 'FeverPAIN 5: IV antibiotics', false, 0),
  ('acb5d530-b33b-522d-aa41-3cfbbce8e6d9', '988c28de-9f32-5af8-a081-3348183ca09b', 'B', 'FeverPAIN 1: no antibiotic', false, 1),
  ('f2e053bb-31b9-5cb5-ace4-3b4af662636c', '988c28de-9f32-5af8-a081-3348183ca09b', 'C', 'FeverPAIN 3: amoxicillin', false, 2),
  ('a04db4a7-73fa-5775-a2d0-b0015a1d4ce8', '988c28de-9f32-5af8-a081-3348183ca09b', 'D', 'FeverPAIN 2: no antibiotic', false, 3),
  ('b36356f1-1f1e-5007-a9cc-54a0771f465a', '988c28de-9f32-5af8-a081-3348183ca09b', 'E', 'FeverPAIN 5: consider an immediate antibiotic (phenoxymethylpenicillin)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('373d6d26-f620-5e24-9359-adb27d57b430', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 15 month old girl has had a high fever for 3 days followed by a widespread rash. She now looks well, the fever settled before the rash appeared, and the rash is maculopapular on her trunk. What is the SINGLE most likely diagnosis?', 'Roseola (sixth disease, HHV-6/7) typically affects children aged 6 months to 2 years. A high fever for 3-5 days is followed, as the fever settles, by a pink maculopapular rash on the trunk. Febrile seizures can occur. It is self-limiting and needs only supportive care.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('96724005-163d-581c-bd63-98e30a9ccb19', '373d6d26-f620-5e24-9359-adb27d57b430', 'A', 'Rubella', false, 0),
  ('d5caf8f9-5ff0-5672-a626-bb54a7da3051', '373d6d26-f620-5e24-9359-adb27d57b430', 'B', 'Scarlet fever', false, 1),
  ('d7909d3b-7e03-51b3-99f5-733bafb32275', '373d6d26-f620-5e24-9359-adb27d57b430', 'C', 'Kawasaki disease', false, 2),
  ('4531696b-9fd7-5de3-af6f-c8856dd7899e', '373d6d26-f620-5e24-9359-adb27d57b430', 'D', 'Measles', false, 3),
  ('6dffab42-ba5d-5b6e-ae61-a31d7f0405a9', '373d6d26-f620-5e24-9359-adb27d57b430', 'E', 'Roseola infantum (HHV-6)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('05337875-2732-567a-b128-e3a2933e183d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 year old boy has bright red cheeks, as if he has been slapped, followed by a lacy reticular rash on his arms. He is otherwise well. His mother is 14 weeks pregnant. What is the SINGLE most appropriate advice for his mother?', 'Slapped cheek syndrome (erythema infectiosum) is caused by parvovirus B19. Infection before 20 weeks of pregnancy can cause fetal anaemia, hydrops fetalis and miscarriage. A pregnant contact needs urgent serology, and if infected, referral to fetal medicine for monitoring. The child is no longer infectious once the rash appears, so he does not need to stay off school.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f82dec2a-ca5f-5fee-8344-aeb19136062d', '05337875-2732-567a-b128-e3a2933e183d', 'A', 'Advise termination of pregnancy', false, 0),
  ('1a8021f7-93bf-5cbb-9ebf-630e1f89af1b', '05337875-2732-567a-b128-e3a2933e183d', 'B', 'Give her IV aciclovir', false, 1),
  ('f4709093-b314-59fc-af7d-907859dc82ae', '05337875-2732-567a-b128-e3a2933e183d', 'C', 'Check her parvovirus B19 IgG and IgM serology', true, 2),
  ('54ce32cf-00bf-54c0-827b-fab48889c297', '05337875-2732-567a-b128-e3a2933e183d', 'D', 'Give her the MMR vaccine', false, 3),
  ('49111b13-0796-5483-b726-5b8d8e261850', '05337875-2732-567a-b128-e3a2933e183d', 'E', 'No action needed as the infection is mild', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b9f625a9-bd3e-5931-bf3b-014ab791823e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old boy has had a sore throat and fever for 2 days. He now has a rough, sandpaper-like red rash that started on his neck and chest and spares the area around the mouth. His tongue is red with prominent papillae. What is the SINGLE most appropriate management?', 'Scarlet fever is caused by group A Streptococcus. It causes a sandpaper rash, circumoral pallor, a strawberry tongue and Pastia''s lines. It is notifiable. Treatment is phenoxymethylpenicillin for 10 days (azithromycin in penicillin allergy), and children should stay off school until 24 hours after starting antibiotics. Complications include rheumatic fever and post-streptococcal glomerulonephritis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('11c8a339-2d4a-514e-bffb-d7e06d2c44d5', 'b9f625a9-bd3e-5931-bf3b-014ab791823e', 'A', 'Oral phenoxymethylpenicillin for 10 days and notify UKHSA', true, 0),
  ('343ce1d1-3251-5a76-b98c-b6fa179835e2', 'b9f625a9-bd3e-5931-bf3b-014ab791823e', 'B', 'Oral aciclovir', false, 1),
  ('e0236cbb-ac37-5eb1-b10a-8755043e4283', 'b9f625a9-bd3e-5931-bf3b-014ab791823e', 'C', 'IV ceftriaxone', false, 2),
  ('793e9008-f6a5-539f-99fd-1f615c054bd3', 'b9f625a9-bd3e-5931-bf3b-014ab791823e', 'D', 'Oral clarithromycin for 3 days only', false, 3),
  ('51743840-4871-519b-a97f-f2d977b21a6a', 'b9f625a9-bd3e-5931-bf3b-014ab791823e', 'E', 'No antibiotics; it is viral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b96cc7db-a9bd-5c2b-a020-056a77b77907', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 year old boy has a few days of fever followed by an itchy rash of crops of papules, vesicles and crusted lesions on his trunk and face at different stages. He is otherwise well. When can he return to school?', 'Chickenpox (varicella-zoster virus) is infectious from 1-2 days before the rash until all lesions have crusted. Management is supportive (paracetamol, calamine, fluids), and NSAIDs should be avoided because of the risk of invasive group A strep. Aciclovir is for immunocompromised children, neonates or severe disease. Pregnant contacts without immunity need assessment for VZIG or antivirals.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ffa21f5f-3b52-5dee-af9d-8202f65be7ba', 'b96cc7db-a9bd-5c2b-a020-056a77b77907', 'A', 'Once all the scabs have fallen off', false, 0),
  ('7521fa86-b1d4-5909-a2da-f092d2739805', 'b96cc7db-a9bd-5c2b-a020-056a77b77907', 'B', 'Once all the lesions have crusted over, usually about 5 days after the rash appeared', true, 1),
  ('7fc6a837-e83e-5f6c-80ab-f5b6fb75abb0', 'b96cc7db-a9bd-5c2b-a020-056a77b77907', 'C', 'After 24 hours of antibiotics', false, 2),
  ('60451d22-aeac-5e0c-92b1-b157149f1551', 'b96cc7db-a9bd-5c2b-a020-056a77b77907', 'D', 'After 21 days', false, 3),
  ('f0716415-4ae1-54c5-98a2-4f9f8b898af1', 'b96cc7db-a9bd-5c2b-a020-056a77b77907', 'E', 'Immediately', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8f7da124-cb70-543f-a4ac-a66c77f99488', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 9 month old baby has a widespread itchy, dry, red rash on his cheeks and the extensor surfaces of his limbs. There are no signs of infection. His mother has asthma. Emollients have been tried. What is the SINGLE most appropriate additional treatment for flares?', 'Atopic eczema in infants affects the face and extensor surfaces. Management is generous emollients as soap substitutes, plus topical steroids for flares, stepped by severity and site. Mild potency (hydrocortisone 1%) is used on the face, and moderate potency for short courses on the body. Topical calcineurin inhibitors are second-line and not licensed under 2 years.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1488a805-f12f-5755-b498-4e578fc94862', '8f7da124-cb70-543f-a4ac-a66c77f99488', 'A', 'Mild topical corticosteroid (1% hydrocortisone) for facial flares', true, 0),
  ('81208d96-42e9-5670-9d1b-1268769f3579', '8f7da124-cb70-543f-a4ac-a66c77f99488', 'B', 'Potent topical steroid on the face', false, 1),
  ('fead0180-59ee-5d99-83b2-5f5b45c3535a', '8f7da124-cb70-543f-a4ac-a66c77f99488', 'C', 'Topical tacrolimus as first-line in infants', false, 2),
  ('63f086b5-54a3-5cce-b36c-562b40c4650e', '8f7da124-cb70-543f-a4ac-a66c77f99488', 'D', 'Oral prednisolone', false, 3),
  ('c0440e00-c4ed-517e-b27f-09b56c801538', '8f7da124-cb70-543f-a4ac-a66c77f99488', 'E', 'Oral antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1b817c36-7b3b-5b76-8d4a-e59ac9adaa11', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 week old exclusively breastfed baby is still jaundiced. He is feeding well and gaining weight. His stools are pale and chalky and his urine is dark yellow. His conjugated bilirubin is raised. What is the SINGLE most likely diagnosis?', 'Prolonged jaundice (over 14 days at term) with pale stools, dark urine and conjugated hyperbilirubinaemia suggests biliary atresia. It needs urgent paediatric hepatology referral, because the Kasai portoenterostomy has better outcomes if done before 60 days of age. Breast milk jaundice is unconjugated with normal stools.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6b4193d6-7174-5db8-9225-56dc7ac53b62', '1b817c36-7b3b-5b76-8d4a-e59ac9adaa11', 'A', 'Biliary atresia', true, 0),
  ('664439be-d3a7-53e3-ad0d-5ee66e48c019', '1b817c36-7b3b-5b76-8d4a-e59ac9adaa11', 'B', 'Breast milk jaundice', false, 1),
  ('5360c9a9-f78d-5bb0-8195-fbd75eebb8c2', '1b817c36-7b3b-5b76-8d4a-e59ac9adaa11', 'C', 'Gilbert''s syndrome', false, 2),
  ('f745e7bf-a4e0-58b5-9262-eccb8943658d', '1b817c36-7b3b-5b76-8d4a-e59ac9adaa11', 'D', 'ABO incompatibility', false, 3),
  ('844ef82d-a0e4-51ed-a100-74563d7cbc1b', '1b817c36-7b3b-5b76-8d4a-e59ac9adaa11', 'E', 'Physiological jaundice', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6321f3c5-ef69-553d-b873-61b47273184f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 14 month old boy is brought in after his mother found him with an open bottle of her iron tablets. She thinks he took up to 10 tablets 1 hour ago. He has vomited once. What is the SINGLE most appropriate first step?', 'Iron overdose is potentially dangerous in young children, causing GI toxicity, then shock, metabolic acidosis and liver failure. Activated charcoal does not bind iron. Management follows TOXBASE: assess the elemental iron ingested per kg, check a serum iron level about 4 hours after ingestion and an abdominal X-ray, and give IV desferrioxamine if significant. Safeguarding and accident prevention advice should be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1ad85a49-9ff9-5c4e-a609-7d01f53cad49', '6321f3c5-ef69-553d-b873-61b47273184f', 'A', 'Give IV naloxone', false, 0),
  ('2c9fd325-e398-5256-bd33-c435db94a06e', '6321f3c5-ef69-553d-b873-61b47273184f', 'B', 'Give activated charcoal', false, 1),
  ('4c86e3bc-01b3-585a-8176-368578dc1a7d', '6321f3c5-ef69-553d-b873-61b47273184f', 'C', 'Induce vomiting with ipecacuanha', false, 2),
  ('e3155491-bac2-5c01-a9b6-f68e70d58dc2', '6321f3c5-ef69-553d-b873-61b47273184f', 'D', 'Discharge as iron is non-toxic', false, 3),
  ('fe4489b5-1d5b-56c8-bdc8-f62d29f2f93a', '6321f3c5-ef69-553d-b873-61b47273184f', 'E', 'Check a serum iron level at 4 hours and seek TOXBASE/NPIS advice', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8aaef9cf-5788-5b7b-8096-278678810b16', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old boy has a fever and has been limping for 2 days. He refuses to bear weight on his right leg. His temperature is 38.9°C, CRP is 95 mg/L and WCC 17 x 10^9/L. The right hip is held flexed and externally rotated with very limited movement. What is the SINGLE most likely diagnosis?', 'Kocher criteria for septic arthritis: non-weight bearing, fever over 38.5°C, ESR over 40 and WCC over 12. Meeting all four gives a very high probability. He needs urgent orthopaedic referral, ultrasound, joint aspiration and IV antibiotics. Transient synovitis usually follows a viral illness, with a well child and mild or no fever.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4e45eea3-c145-58b8-aa34-063ccb53e1e5', '8aaef9cf-5788-5b7b-8096-278678810b16', 'A', 'Juvenile idiopathic arthritis', false, 0),
  ('64bb39df-79c5-5481-b8ea-a904b995b0db', '8aaef9cf-5788-5b7b-8096-278678810b16', 'B', 'Transient synovitis', false, 1),
  ('c50088c4-2085-5860-b7d9-386bded0b885', '8aaef9cf-5788-5b7b-8096-278678810b16', 'C', 'Perthes disease', false, 2),
  ('b2808fec-74a2-5cfa-980f-9a6434a045f9', '8aaef9cf-5788-5b7b-8096-278678810b16', 'D', 'Slipped upper femoral epiphysis', false, 3),
  ('cdffef1f-0c45-5329-8ce6-833779c2a4c7', '8aaef9cf-5788-5b7b-8096-278678810b16', 'E', 'Septic arthritis of the hip', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d671e1ad-66b3-5ec3-abca-6cc57e2c5f92', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 year old boy has had a limp and intermittent pain in his left hip and knee for 6 weeks. He is afebrile and well. Hip movements, especially abduction and internal rotation, are reduced. A hip X-ray shows flattening and sclerosis of the left femoral head. What is the SINGLE most likely diagnosis?', 'Perthes disease is avascular necrosis of the femoral epiphysis, most common in boys aged 4-8. It presents with an insidious limp and hip or knee pain. X-ray shows femoral head flattening, sclerosis and fragmentation. Management ranges from observation and physiotherapy to surgical containment, depending on age and severity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('82c14181-4a49-55da-a594-768d66f00efc', 'd671e1ad-66b3-5ec3-abca-6cc57e2c5f92', 'A', 'Transient synovitis', false, 0),
  ('6f5c5d98-6dc9-578a-81fe-096ddc762922', 'd671e1ad-66b3-5ec3-abca-6cc57e2c5f92', 'B', 'Septic arthritis', false, 1),
  ('d11f69e8-2559-5844-b1f6-5803c289e809', 'd671e1ad-66b3-5ec3-abca-6cc57e2c5f92', 'C', 'Perthes disease', true, 2),
  ('c8164260-f8bf-5d83-aedd-bbeca66dc86d', 'd671e1ad-66b3-5ec3-abca-6cc57e2c5f92', 'D', 'Slipped upper femoral epiphysis', false, 3),
  ('96545ed8-bae6-5d0f-9b48-08a762e83163', 'd671e1ad-66b3-5ec3-abca-6cc57e2c5f92', 'E', 'Developmental dysplasia of the hip', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d735a570-1b5d-5fea-82f2-de6ec73c9c69', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 13 year old overweight boy has had pain in his right knee and a limp for 3 weeks. On examination, when his hip is flexed it rotates externally, and internal rotation is reduced. What is the SINGLE most likely diagnosis?', 'SUFE typically affects overweight adolescent boys during the growth spurt. Hip pathology can present as knee pain (referred via the obturator nerve). Obligatory external rotation on hip flexion is classic. A frog-leg lateral X-ray shows the slip. Management is non-weight bearing and urgent surgical fixation in situ. The other hip should be monitored or fixed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb2a3d85-3883-5ddc-b356-d4f792c51362', 'd735a570-1b5d-5fea-82f2-de6ec73c9c69', 'A', 'Slipped upper femoral epiphysis', true, 0),
  ('f6e184a8-b10d-5828-a42a-8584c3d0f40c', 'd735a570-1b5d-5fea-82f2-de6ec73c9c69', 'B', 'Osgood-Schlatter disease', false, 1),
  ('bf9ec8b3-bda1-58ce-80c1-05d687212b7b', 'd735a570-1b5d-5fea-82f2-de6ec73c9c69', 'C', 'Transient synovitis', false, 2),
  ('5430a1b9-04ff-547f-b61e-a317e790a6c7', 'd735a570-1b5d-5fea-82f2-de6ec73c9c69', 'D', 'Perthes disease', false, 3),
  ('e6cd1ef4-e142-50d5-8b73-3b5f0388ecd5', 'd735a570-1b5d-5fea-82f2-de6ec73c9c69', 'E', 'Patellofemoral pain syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ab67786a-49cb-5ae3-a5ad-7d1a4015778c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 13 year old boy who plays football has pain and a tender lump just below his left knee, worse after running and kneeling. X-ray shows fragmentation of the tibial tuberosity. What is the SINGLE most appropriate management?', 'Osgood-Schlatter disease is a traction apophysitis of the tibial tuberosity at the patellar tendon insertion in active adolescents. It is self-limiting and usually resolves at skeletal maturity. Management is supportive: analgesia, ice, reducing aggravating activity and quadriceps stretching.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df09f323-6825-50f0-b69c-c3793019e34a', 'ab67786a-49cb-5ae3-a5ad-7d1a4015778c', 'A', 'Rest, ice, analgesia and activity modification', true, 0),
  ('4931d575-41c8-5b4b-94ec-d133f0addf0f', 'ab67786a-49cb-5ae3-a5ad-7d1a4015778c', 'B', 'Surgical excision', false, 1),
  ('ee3eeb61-6675-5486-85ec-36ecf1cf2190', 'ab67786a-49cb-5ae3-a5ad-7d1a4015778c', 'C', 'Above-knee cast for 6 weeks', false, 2),
  ('f0013fc1-c365-5467-bcb1-fda79fc9ea87', 'ab67786a-49cb-5ae3-a5ad-7d1a4015778c', 'D', 'IV antibiotics', false, 3),
  ('58b2aef4-7f3e-574e-958c-283732a4a772', 'ab67786a-49cb-5ae3-a5ad-7d1a4015778c', 'E', 'Urgent orthopaedic referral for suspected sarcoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('897fdfd5-9e07-5f6b-9675-e9a12ee85d5a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 year old girl has had swelling around her eyes for 3 days. Ten days ago she had a sore throat. Her urine is cola-coloured and her BP is 128/84 mmHg. Urine dipstick shows blood 3+ and protein 1+. Her complement C3 is low. What is the SINGLE most likely diagnosis?', 'Nephritic syndrome (haematuria, hypertension, oedema, oliguria) 1-3 weeks after a streptococcal throat or skin infection, with low C3 and a raised ASO titre, is post-streptococcal glomerulonephritis. Management is supportive, with fluid restriction and diuretics or antihypertensives as needed. Most children recover fully. IgA nephropathy causes haematuria within 1-2 days of an infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f89886c3-e6ef-526a-bee8-b2463599c06f', '897fdfd5-9e07-5f6b-9675-e9a12ee85d5a', 'A', 'IgA nephropathy', false, 0),
  ('4611f39c-a433-504b-b654-fe70911e5c69', '897fdfd5-9e07-5f6b-9675-e9a12ee85d5a', 'B', 'Minimal change disease', false, 1),
  ('53cd99d5-9a98-5477-9cf5-53a2dcb392ea', '897fdfd5-9e07-5f6b-9675-e9a12ee85d5a', 'C', 'Henoch-Schönlein purpura', false, 2),
  ('8b741dee-1e71-586f-a9e7-8c7288a02dde', '897fdfd5-9e07-5f6b-9675-e9a12ee85d5a', 'D', 'Haemolytic uraemic syndrome', false, 3),
  ('784c393b-1550-5428-9f6c-474d697dd1a4', '897fdfd5-9e07-5f6b-9675-e9a12ee85d5a', 'E', 'Post-streptococcal glomerulonephritis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a4fe5831-7788-5fe1-a609-8e6d622f2551', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old girl has a fever of 39°C and vomiting. She has no other source of infection. A clean-catch urine dipstick shows positive leukocytes and nitrites. She is well hydrated. What is the SINGLE most appropriate management?', 'Fever with a positive urine test in a young child suggests upper UTI (acute pyelonephritis). NICE recommends sending urine for culture and starting oral antibiotics (such as cefalexin or co-amoxiclav) for 7-10 days. IV antibiotics are needed if the child is under 3 months or very unwell. Imaging depends on age, response and recurrence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('02fc8182-b5f7-54c3-b473-7662fe3b5f98', 'a4fe5831-7788-5fe1-a609-8e6d622f2551', 'A', 'Urgent DMSA scan before treatment', false, 0),
  ('63478e29-0d0d-5758-8001-342a76fd2202', 'a4fe5831-7788-5fe1-a609-8e6d622f2551', 'B', 'No antibiotics until culture result', false, 1),
  ('3e8276be-4320-5219-b8dc-582d4ceb9079', 'a4fe5831-7788-5fe1-a609-8e6d622f2551', 'C', 'Trimethoprim for 3 days', false, 2),
  ('c875b40b-4941-5197-9415-30017c3ce2b3', 'a4fe5831-7788-5fe1-a609-8e6d622f2551', 'D', 'Admit for IV antibiotics in all cases', false, 3),
  ('63226d7f-fa0b-5121-81f1-281c89508fcf', 'a4fe5831-7788-5fe1-a609-8e6d622f2551', 'E', 'Send urine for culture and start oral antibiotics (e.g. cefalexin or co-amoxiclav) for 7-10 days as upper UTI', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3071e1fa-26f9-5c80-b92f-f720c7ba5f2f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 month old baby has a fever of 38.2°C. She is feeding slightly less but otherwise appears well. What is the SINGLE most appropriate management?', 'Under NICE''s traffic light system, any infant under 3 months with a temperature of 38°C or above is a red feature, needing urgent referral for full assessment, including a septic screen. Infants under 1 month, or 1-3 months who appear unwell or have a low WCC, need parenteral antibiotics. Serious bacterial infection is hard to rule out clinically at this age.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c18806ca-2584-5ba6-8c06-e000f8da69f1', '3071e1fa-26f9-5c80-b92f-f720c7ba5f2f', 'A', 'Reassure as fever is common in infants', false, 0),
  ('5644c6cf-6191-5cf6-baa0-bac8501c04e4', '3071e1fa-26f9-5c80-b92f-f720c7ba5f2f', 'B', 'Urgent referral to paediatrics for assessment and investigation', true, 1),
  ('ad08d8d5-d157-571c-9d8f-eb4894b39c55', '3071e1fa-26f9-5c80-b92f-f720c7ba5f2f', 'C', 'Prescribe oral amoxicillin', false, 2),
  ('03665ea2-bc04-5fb7-a3bb-f8b5d21d2443', '3071e1fa-26f9-5c80-b92f-f720c7ba5f2f', 'D', 'Review in 1 week', false, 3),
  ('41b85438-4a32-58fc-ac10-3218b19c97f8', '3071e1fa-26f9-5c80-b92f-f720c7ba5f2f', 'E', 'Advise paracetamol and safety-net', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e967f93c-221a-5393-92dc-80e075920777', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old girl has abdominal pain most days for 4 months, often before school. It is periumbilical, does not wake her at night, and her growth and examination are normal. She has no red flag features. What is the SINGLE most likely diagnosis?', 'Recurrent abdominal pain in school-age children is usually functional, especially periumbilical pain without red flags (weight loss, faltering growth, nocturnal pain, blood in stool, vomiting, fever or a family history of IBD). Management is reassurance, education and addressing stressors. Simple tests (FBC, coeliac screen, urinalysis) may be done to reassure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
