  ('dbbba74d-4498-5bd8-aabe-1682b6131f16', 'e967f93c-221a-5393-92dc-80e075920777', 'A', 'Functional abdominal pain', true, 0),
  ('4f96a8b3-f36e-5ec6-875d-5c15efd1f88c', 'e967f93c-221a-5393-92dc-80e075920777', 'B', 'Appendicitis', false, 1),
  ('000235b1-94f5-5b07-b9c1-47c28d89c818', 'e967f93c-221a-5393-92dc-80e075920777', 'C', 'Crohn''s disease', false, 2),
  ('9d334366-c83f-57a1-b457-48a9b4241ee4', 'e967f93c-221a-5393-92dc-80e075920777', 'D', 'Intussusception', false, 3),
