insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fa7ea76f-5f26-5f27-8943-a0721c51e75f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 year old boy has been constipated for 6 months, passing hard stools twice a week with pain and soiling of his pants. Examination shows a palpable faecal mass, with no red flags. What is the SINGLE most appropriate initial management?', 'NICE recommends disimpaction with an escalating dose of oral macrogol (Movicol Paediatric Plain), adding a stimulant laxative if needed. This is followed by maintenance macrogol for several weeks after a regular pattern is established, with dietary advice, toileting routine and behavioural support. Rectal treatments are only used if oral treatment fails.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5f5b8ce4-3075-5f2b-9c1f-4b51a149bddd', 'fa7ea76f-5f26-5f27-8943-a0721c51e75f', 'A', 'Enema as first-line', false, 0),
  ('dd36a57a-438e-5c4c-9e93-e83e884be2ff', 'fa7ea76f-5f26-5f27-8943-a0721c51e75f', 'B', 'Refer for anal manometry', false, 1),
  ('971cc7c4-385a-5328-952e-6168bc0323eb', 'fa7ea76f-5f26-5f27-8943-a0721c51e75f', 'C', 'Senna alone', false, 2),
  ('b8ffcea0-7b2c-5840-95c8-a621c56ea25e', 'fa7ea76f-5f26-5f27-8943-a0721c51e75f', 'D', 'Disimpaction with an escalating dose of polyethylene glycol (Movicol Paediatric Plain)', true, 3),
  ('23b27f20-e8ad-5e34-9f6a-faad106368c6', 'fa7ea76f-5f26-5f27-8943-a0721c51e75f', 'E', 'Lactulose only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9ff3ad3b-253f-5ec8-a22f-f7ad85b316f1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old boy is brought in with a 2-day history of diarrhoea and vomiting. He has sunken eyes, dry mucous membranes, reduced skin turgor and is lethargic. His capillary refill is 4 seconds and he is tachycardic. What is the SINGLE most appropriate management?', 'Signs of shock (prolonged CRT, tachycardia, lethargy, mottled or cold peripheries) in gastroenteritis need an IV bolus of 0.9% saline (10-20 mL/kg) then IV rehydration. Clinical dehydration without shock is treated with oral rehydration solution (50 mL/kg over 4 hours plus maintenance), using a nasogastric tube if needed. Antidiarrhoeals are not recommended in children.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8c7c73ed-0038-51d9-bf8a-b2eed3a96da2', '9ff3ad3b-253f-5ec8-a22f-f7ad85b316f1', 'A', 'Oral antibiotics', false, 0),
  ('e211bb96-c53b-5fa1-9312-38f34d7ac621', '9ff3ad3b-253f-5ec8-a22f-f7ad85b316f1', 'B', 'Wait for stool culture results', false, 1),
  ('2cbb6cdf-04a5-5b05-83ca-097ba98dda48', '9ff3ad3b-253f-5ec8-a22f-f7ad85b316f1', 'C', 'Loperamide', false, 2),
  ('2cabe0f8-6b35-5df8-ac64-ed95e6f693ae', '9ff3ad3b-253f-5ec8-a22f-f7ad85b316f1', 'D', 'Oral rehydration solution at home', false, 3),
  ('476d653d-77e0-5ed6-8949-17a89937ce52', '9ff3ad3b-253f-5ec8-a22f-f7ad85b316f1', 'E', 'IV fluid bolus of 0.9% sodium chloride for shock, then rehydration', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2b636394-636a-52db-a5dc-8df4b7b1cae3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A newborn baby is noted to have a ''clunk'' in his left hip and his foot is fixed in a downward and inward position. The foot cannot be corrected to a neutral position. What is the SINGLE most appropriate management for the foot?', 'Congenital talipes equinovarus (clubfoot) is a fixed deformity: plantarflexed, inverted and adducted. It is associated with DDH. The Ponseti method (serial manipulation and casting, often an Achilles tenotomy, then a foot abduction brace) is first-line. Positional talipes is flexible, can be passively corrected and resolves without treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6be800e1-c40c-55b2-837e-ea3bd95cc998', '2b636394-636a-52db-a5dc-8df4b7b1cae3', 'A', 'Shoe inserts', false, 0),
  ('cf4a8969-ce6b-5f81-9d83-b5f849ebe222', '2b636394-636a-52db-a5dc-8df4b7b1cae3', 'B', 'Immediate surgery', false, 1),
  ('187b907a-72b4-50ff-8a89-04c23e5c187b', '2b636394-636a-52db-a5dc-8df4b7b1cae3', 'C', 'Physiotherapy stretches only', false, 2),
  ('bef78297-6a83-5a0a-8ea3-b884862cb37b', '2b636394-636a-52db-a5dc-8df4b7b1cae3', 'D', 'Reassurance; it will correct itself', false, 3),
  ('f152c6f0-e681-5477-91cb-c2fa56242d8d', '2b636394-636a-52db-a5dc-8df4b7b1cae3', 'E', 'Ponseti method of serial casting', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5d94a114-117f-5984-b0b1-d89fe1be3619', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 10 month old boy has a fluctuating, painless scrotal swelling on the right that gets bigger during the day. It transilluminates and you can get above it. What is the SINGLE most likely diagnosis?', 'A painless, transilluminating swelling that you can get above, which varies with activity, is a communicating hydrocele from a patent processus vaginalis. Most resolve by 1-2 years, and surgery is considered if it persists. An inguinal hernia cannot be got above and may be reducible. In infants, hernias need prompt repair because of the high risk of incarceration.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('23879c1f-c9c9-56d0-bc11-6c8d19989e72', '5d94a114-117f-5984-b0b1-d89fe1be3619', 'A', 'Epididymo-orchitis', false, 0),
  ('4833e865-38a9-5fa7-8b10-44673244b647', '5d94a114-117f-5984-b0b1-d89fe1be3619', 'B', 'Inguinal hernia', false, 1),
  ('a643f1bf-4b6a-5dd7-9c1b-6eb5bbfc19f4', '5d94a114-117f-5984-b0b1-d89fe1be3619', 'C', 'Communicating hydrocele', true, 2),
  ('5476bf89-9ffa-54f4-851d-c9af0db43e0c', '5d94a114-117f-5984-b0b1-d89fe1be3619', 'D', 'Varicocele', false, 3),
  ('7ffe0273-ef16-542f-9ac2-9e8a9c9d396d', '5d94a114-117f-5984-b0b1-d89fe1be3619', 'E', 'Testicular torsion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a56589e3-52bf-5a5a-bcda-cc499dad805c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 month old baby boy has an undescended right testis on examination. It cannot be palpated in the scrotum or the inguinal canal. The left testis is normal. What is the SINGLE most appropriate management?', 'Testes that have not descended by 3 months rarely descend later. Undescended testes increase the risk of infertility and testicular cancer. Referral by 6 months is recommended for orchidopexy, ideally by 12 months (and before 18 months). Bilateral impalpable testes in a newborn need urgent assessment for disorders of sex development.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('79154aeb-9460-541d-9cda-92ac468af85e', 'a56589e3-52bf-5a5a-bcda-cc499dad805c', 'A', 'Refer to paediatric surgery for orchidopexy, ideally between 6 and 12 months of age', true, 0),
  ('387cb0d4-e0c3-5164-aad3-0b0eb7d123f3', 'a56589e3-52bf-5a5a-bcda-cc499dad805c', 'B', 'Reassure and review at 5 years', false, 1),
  ('b15dfa32-a79e-5c68-9b1c-ab414ea4f3f1', 'a56589e3-52bf-5a5a-bcda-cc499dad805c', 'C', 'Wait until puberty', false, 2),
  ('83f96cd4-b224-57a1-b17c-3616318579ad', 'a56589e3-52bf-5a5a-bcda-cc499dad805c', 'D', 'Immediate orchidectomy', false, 3),
  ('3270845e-4210-5094-bfe3-e298c604ad98', 'a56589e3-52bf-5a5a-bcda-cc499dad805c', 'E', 'Hormonal treatment with hCG first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c4205897-2106-58b1-aa42-7d04a57bbcbd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 year old boy has a non-retractile foreskin. He has no recurrent infections, no ballooning causing problems with urination, and no scarring. His parents are worried. What is the SINGLE most appropriate management?', 'A non-retractile foreskin is normal in young boys (physiological phimosis), and the foreskin usually becomes retractable by adolescence. Parents should be told not to forcibly retract it. Referral is needed for pathological phimosis (scarring, balanitis xerotica obliterans), recurrent balanoposthitis or urinary obstruction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5499213f-0660-5c7d-b0c1-277a9f7e259d', 'c4205897-2106-58b1-aa42-7d04a57bbcbd', 'A', 'Forcible retraction', false, 0),
  ('37dc06e7-e0eb-5258-8801-3d90f2ab2a74', 'c4205897-2106-58b1-aa42-7d04a57bbcbd', 'B', 'Topical steroid cream for 6 months', false, 1),
  ('8d28a859-c49e-50ee-af66-0c27f5e79e0c', 'c4205897-2106-58b1-aa42-7d04a57bbcbd', 'C', 'Oral antibiotics', false, 2),
  ('2e61f32c-da6c-5964-9541-a32927fb65df', 'c4205897-2106-58b1-aa42-7d04a57bbcbd', 'D', 'Reassure; physiological phimosis is normal at this age', true, 3),
  ('c797077c-d618-5df4-934b-3ae3c2423ec3', 'c4205897-2106-58b1-aa42-7d04a57bbcbd', 'E', 'Refer for circumcision', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a9bacd33-9f28-5ca7-a3d3-dd953c3c134b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 year old girl has had a fever, irritability and a limp for 1 week. She has bone pain, pallor, bruising and petechiae. Examination shows hepatosplenomegaly and lymphadenopathy. Her full blood count shows Hb 78 g/L, platelets 25 x 10^9/L and WCC 32 x 10^9/L with blasts. What is the SINGLE most likely diagnosis?', 'ALL is the commonest childhood cancer, peaking at age 2-5. It presents with bone marrow failure (anaemia, bleeding, infection), bone pain, lymphadenopathy and hepatosplenomegaly. Blasts on the film need an immediate referral. Diagnosis is by bone marrow aspirate and immunophenotyping, and the cure rate is about 90%.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('57d379d5-715c-5397-9874-b4dfd8e90c02', 'a9bacd33-9f28-5ca7-a3d3-dd953c3c134b', 'A', 'Acute lymphoblastic leukaemia', true, 0),
  ('c6aeb5b0-334f-5600-b35b-0ca69d5a3dba', 'a9bacd33-9f28-5ca7-a3d3-dd953c3c134b', 'B', 'Aplastic anaemia', false, 1),
  ('266e2f73-f502-50a6-9bd2-53dee242bd3a', 'a9bacd33-9f28-5ca7-a3d3-dd953c3c134b', 'C', 'Neuroblastoma', false, 2),
  ('171d1e80-a08a-5351-9738-861b581f334c', 'a9bacd33-9f28-5ca7-a3d3-dd953c3c134b', 'D', 'Immune thrombocytopenic purpura', false, 3),
  ('7f2cc4f5-c293-5c75-a9b0-3feea29f1aa2', 'a9bacd33-9f28-5ca7-a3d3-dd953c3c134b', 'E', 'Juvenile idiopathic arthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9927ccca-b57d-50bd-a417-32b6528cb5c0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 year old boy has an abdominal mass found by his mother while bathing him. He is well. The mass is smooth, does not cross the midline and is in the left flank. He has haematuria and hypertension. What is the SINGLE most likely diagnosis?', 'Wilms tumour typically presents at 3-4 years as an asymptomatic flank mass that does not cross the midline, sometimes with haematuria or hypertension. Neuroblastoma often crosses the midline, comes from the adrenal gland, affects younger children, and the child is often unwell with raised urinary catecholamines. Children with an unexplained abdominal mass need very urgent referral (within 48 hours).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('064b5139-b662-5ceb-8516-cd727185ac7f', '9927ccca-b57d-50bd-a417-32b6528cb5c0', 'A', 'Hepatoblastoma', false, 0),
  ('d38e0853-2952-5129-9cba-e048d2d099ed', '9927ccca-b57d-50bd-a417-32b6528cb5c0', 'B', 'Polycystic kidney disease', false, 1),
  ('8a887a05-8167-5517-bb2f-b546c27ba685', '9927ccca-b57d-50bd-a417-32b6528cb5c0', 'C', 'Neuroblastoma', false, 2),
  ('e579db0c-6a65-5dd8-bfa6-363a00ec9c13', '9927ccca-b57d-50bd-a417-32b6528cb5c0', 'D', 'Wilms tumour (nephroblastoma)', true, 3),
  ('1d2d665f-8af2-533f-b2d4-7171c4f61906', '9927ccca-b57d-50bd-a417-32b6528cb5c0', 'E', 'Hydronephrosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('03b9bf34-f23f-59b4-8d2c-34472f9e4a8f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old child has had a white pupil in a photograph and a squint for 2 months. The red reflex is absent in the left eye. What is the SINGLE most appropriate management?', 'Leukocoria (an absent red reflex or white pupil) in a child suggests retinoblastoma, needing urgent referral. It may be inherited (RB1 gene, autosomal dominant, often bilateral), and these patients have an increased risk of osteosarcoma. Other causes include congenital cataract. A new squint in a child also warrants assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dd8448fb-63eb-5125-9dc4-720899723c44', '03b9bf34-f23f-59b4-8d2c-34472f9e4a8f', 'A', 'Routine optician review', false, 0),
  ('620522a4-4fa7-5289-a249-021b185ac99c', '03b9bf34-f23f-59b4-8d2c-34472f9e4a8f', 'B', 'Urgent ophthalmology referral (within 2 weeks) for suspected retinoblastoma', true, 1),
  ('120d43af-ed26-59cc-b309-59a5a0942f77', '03b9bf34-f23f-59b4-8d2c-34472f9e4a8f', 'C', 'Review at the next school check', false, 2),
  ('b217e075-fc3c-5a11-b62a-7981af46ac4e', '03b9bf34-f23f-59b4-8d2c-34472f9e4a8f', 'D', 'Patching therapy', false, 3),
  ('7064f050-8322-5468-a4b0-0e8c63232150', '03b9bf34-f23f-59b4-8d2c-34472f9e4a8f', 'E', 'Reassure; it is a camera artefact', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3dd1e53c-e99b-5e6e-b1ff-ff5ae8ce4827', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 year old girl has a convergent squint in her right eye noticed by her parents. The corneal light reflex is asymmetrical. On the cover test, when the left eye is covered, the right eye moves outward to take up fixation. What is the SINGLE most appropriate management?', 'A persistent squint after 3 months of age needs referral. Untreated strabismus can lead to amblyopia, which must be treated in early childhood while the visual system is still developing. Treatment is glasses for refractive error, patching or atropine penalisation of the good eye, and sometimes surgery. A cover test identifies a manifest squint.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1579bf50-4ccd-5a5a-925b-5c2eb62a2107', '3dd1e53c-e99b-5e6e-b1ff-ff5ae8ce4827', 'A', 'Refer to orthoptics/ophthalmology for assessment and treatment of amblyopia', true, 0),
  ('24245489-1656-5fdd-9f9a-75fe36fb23c2', '3dd1e53c-e99b-5e6e-b1ff-ff5ae8ce4827', 'B', 'Glasses from a high street optician only', false, 1),
  ('ea273fd5-c755-5d0e-b104-73288426bd57', '3dd1e53c-e99b-5e6e-b1ff-ff5ae8ce4827', 'C', 'Review at age 7', false, 2),
  ('2e36194a-b754-5539-9ece-2e242e6166a4', '3dd1e53c-e99b-5e6e-b1ff-ff5ae8ce4827', 'D', 'Reassure; it will resolve', false, 3),
  ('c7602fb2-233c-5430-b15e-7cb106aade84', '3dd1e53c-e99b-5e6e-b1ff-ff5ae8ce4827', 'E', 'Immediate strabismus surgery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5b9cb75c-408c-5abd-8f16-3335a00100bf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 week old baby has had a cough and fast breathing for 2 weeks without fever. She has had sticky eyes since day 5 of life. Her chest X-ray shows bilateral interstitial infiltrates and she has eosinophilia. What is the SINGLE most likely organism?', 'Neonatal chlamydial conjunctivitis (5-14 days) followed by afebrile pneumonia with a staccato cough at 2-19 weeks and eosinophilia suggests Chlamydia trachomatis acquired during delivery. Treatment is oral erythromycin (or azithromycin), and the mother and her partner also need treatment. Gonococcal conjunctivitis appears earlier (within 5 days) and is more severe.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('87314b2d-9d54-5b38-9223-b313f1816eb7', '5b9cb75c-408c-5abd-8f16-3335a00100bf', 'A', 'Streptococcus pneumoniae', false, 0),
  ('359a831e-b690-5848-ad72-b10ba369d8b7', '5b9cb75c-408c-5abd-8f16-3335a00100bf', 'B', 'Chlamydia trachomatis', true, 1),
  ('d95e5adc-7564-58c4-9a99-abd8734b7d0e', '5b9cb75c-408c-5abd-8f16-3335a00100bf', 'C', 'Bordetella pertussis', false, 2),
  ('cce13d85-1a89-5207-9cc6-bf0b34270846', '5b9cb75c-408c-5abd-8f16-3335a00100bf', 'D', 'Respiratory syncytial virus', false, 3),
  ('ac716c51-967a-5179-8d5d-c3878ad5466d', '5b9cb75c-408c-5abd-8f16-3335a00100bf', 'E', 'Group B streptococcus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('49e9e4a6-f832-5428-ae56-c33832d3df39', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 day old term baby develops grunting, poor feeding, temperature instability and lethargy. Her mother had a prolonged rupture of membranes and was known to be group B streptococcus positive. What is the SINGLE most appropriate antibiotic regimen?', 'Early-onset neonatal sepsis (within 72 hours) is most often caused by GBS or E. coli. Risk factors include maternal GBS carriage, prolonged rupture of membranes, preterm birth and maternal fever. NICE recommends IV benzylpenicillin plus gentamicin first-line. A lumbar puncture should be considered. Intrapartum antibiotic prophylaxis for GBS-positive mothers reduces this risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('78bd3b09-a39e-5a8a-8f3b-a55c40099136', '49e9e4a6-f832-5428-ae56-c33832d3df39', 'A', 'IV vancomycin only', false, 0),
  ('8e5fe96d-d8eb-55a3-95dd-882c33d58981', '49e9e4a6-f832-5428-ae56-c33832d3df39', 'B', 'Oral erythromycin', false, 1),
  ('58bec823-edd4-5530-be35-6477af3a78ae', '49e9e4a6-f832-5428-ae56-c33832d3df39', 'C', 'IV ceftriaxone alone', false, 2),
  ('df1639b3-f6f2-5e67-a9a2-102137206b09', '49e9e4a6-f832-5428-ae56-c33832d3df39', 'D', 'IV benzylpenicillin and gentamicin', true, 3),
  ('e7992ddc-193b-519b-8716-4c1d86f5f0e1', '49e9e4a6-f832-5428-ae56-c33832d3df39', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('79f35baf-882a-56d3-8a30-bc09c3b8356c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 day old boy born at 34 weeks has been vomiting bile, has a distended abdomen and blood in his stool. He has had formula feeds. An abdominal X-ray shows intramural gas (pneumatosis intestinalis). What is the SINGLE most likely diagnosis?', 'NEC mainly affects premature infants and causes feeding intolerance, abdominal distension, bilious aspirates and bloody stools. X-ray shows dilated loops, pneumatosis intestinalis and portal venous gas. Management is nil by mouth, NG decompression, IV fluids and broad-spectrum antibiotics, with surgery if the bowel perforates. Breast milk reduces the risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('87c05efa-e304-5774-b58c-6c5cea054ff0', '79f35baf-882a-56d3-8a30-bc09c3b8356c', 'A', 'Hirschsprung''s disease', false, 0),
  ('0970ea5d-4079-5ff2-95fa-40b4a5b69c35', '79f35baf-882a-56d3-8a30-bc09c3b8356c', 'B', 'Meconium ileus', false, 1),
  ('a5214739-423b-5318-9ee1-e79c232858be', '79f35baf-882a-56d3-8a30-bc09c3b8356c', 'C', 'Necrotising enterocolitis', true, 2),
  ('8c25cf08-795c-51f3-85ca-99873c105763', '79f35baf-882a-56d3-8a30-bc09c3b8356c', 'D', 'Intussusception', false, 3),
  ('ba17ebaa-e6ea-5d79-8845-0cfb1a103f6e', '79f35baf-882a-56d3-8a30-bc09c3b8356c', 'E', 'Duodenal atresia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fd7c8fe4-54a9-5465-86f1-4c23e58b3332', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A newborn baby with Down syndrome vomits bile with every feed from the first day. An abdominal X-ray shows a ''double bubble'' sign with no gas in the distal bowel. What is the SINGLE most likely diagnosis?', 'Duodenal atresia presents with bilious vomiting soon after birth (the obstruction is usually distal to the ampulla), polyhydramnios antenatally and a double bubble on X-ray. It is strongly associated with Down syndrome. Management is NG decompression, IV fluids and surgical duodenoduodenostomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
