  ('1a766f3f-f7d8-5ee8-a248-c787096ec5ec', 'fd7c8fe4-54a9-5465-86f1-4c23e58b3332', 'A', 'Hirschsprung''s disease', false, 0),
  ('b4faedee-cad4-5695-a24f-dfa31f045959', 'fd7c8fe4-54a9-5465-86f1-4c23e58b3332', 'B', 'Duodenal atresia', true, 1),
  ('d918bc14-eeee-5a29-a75c-1eef810de464', 'fd7c8fe4-54a9-5465-86f1-4c23e58b3332', 'C', 'Malrotation', false, 2),
  ('ec506169-7418-5b61-bcb2-da9479523044', 'fd7c8fe4-54a9-5465-86f1-4c23e58b3332', 'D', 'Oesophageal atresia', false, 3),
  ('87f7a177-70fa-557c-ad7c-abf33427e246', 'fd7c8fe4-54a9-5465-86f1-4c23e58b3332', 'E', 'Pyloric stenosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('408bb35e-0824-57ef-b9ec-a71e2bee30f5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A newborn baby has excessive drooling of saliva and chokes and goes blue on the first feed. A nasogastric tube cannot be passed and coils in the upper chest on X-ray. There is gas in the stomach. What is the SINGLE most likely diagnosis?', 'Oesophageal atresia presents with frothy saliva, choking, cyanosis with feeds and polyhydramnios. A coiled NG tube with gas in the stomach shows a distal TOF (the commonest type). It is associated with VACTERL anomalies. Management is nil by mouth, a Replogle tube on suction and surgical repair.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc82e485-921d-59ee-a1c5-8c97ca287ec8', '408bb35e-0824-57ef-b9ec-a71e2bee30f5', 'A', 'Choanal atresia', false, 0),
  ('d1e1689a-87dd-5de0-b45d-4ac1475693a3', '408bb35e-0824-57ef-b9ec-a71e2bee30f5', 'B', 'Pyloric stenosis', false, 1),
  ('5c5d9b4c-1406-5a9f-a50d-f2564abe9a7d', '408bb35e-0824-57ef-b9ec-a71e2bee30f5', 'C', 'Congenital diaphragmatic hernia', false, 2),
  ('f8d0901c-1d9d-5da6-84a8-cdee2e41e312', '408bb35e-0824-57ef-b9ec-a71e2bee30f5', 'D', 'Oesophageal atresia with distal tracheo-oesophageal fistula', true, 3),
  ('fb55524a-fedc-5f71-b84b-3243a7579ac7', '408bb35e-0824-57ef-b9ec-a71e2bee30f5', 'E', 'Duodenal atresia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6736d115-bfce-5d7b-9670-da5159439c34', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 week old baby has a heart murmur, sweating and breathlessness during feeds and poor weight gain. There is a loud pansystolic murmur at the lower left sternal edge. What is the SINGLE most likely diagnosis?', 'A VSD is the commonest congenital heart defect. A large VSD causes heart failure at 4-6 weeks as pulmonary vascular resistance falls: breathlessness, sweating with feeds and faltering growth, with a pansystolic murmur at the lower left sternal edge. Small VSDs are often asymptomatic and close on their own. Large ones need surgical repair to prevent Eisenmenger syndrome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('78646397-42c7-5956-a75d-c6136eb055e6', '6736d115-bfce-5d7b-9670-da5159439c34', 'A', 'Patent foramen ovale', false, 0),
  ('663a24bf-8fc1-5ea2-a9e2-23a9ed87153a', '6736d115-bfce-5d7b-9670-da5159439c34', 'B', 'Atrial septal defect', false, 1),
  ('60fee6d8-30a4-5482-a8c4-87d498bbbc84', '6736d115-bfce-5d7b-9670-da5159439c34', 'C', 'Ventricular septal defect', true, 2),
  ('b0411ba3-3919-5dd9-8017-2508b2b9d807', '6736d115-bfce-5d7b-9670-da5159439c34', 'D', 'Coarctation of the aorta', false, 3),
  ('8584e783-e23d-570f-aca9-5318eedfba15', '6736d115-bfce-5d7b-9670-da5159439c34', 'E', 'Tetralogy of Fallot', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4eea925b-76a6-51eb-a1b9-87f1c3b5cb8a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 month old boy has episodes of crying during which he becomes deeply cyanosed, then floppy. A harsh ejection systolic murmur at the upper left sternal edge gets quieter during these episodes. A chest X-ray shows a boot-shaped heart. What is the SINGLE most likely diagnosis?', 'Tetralogy of Fallot comprises VSD, overriding aorta, pulmonary stenosis and right ventricular hypertrophy. ''Tet spells'' (hypercyanotic episodes) occur with crying or feeding. Treatment is knee-to-chest position, oxygen, morphine, IV fluids and beta-blockers. The murmur softens during a spell because less blood flows through the stenosed outflow. Complete surgical repair is done in infancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('877a6199-c760-560c-929b-aa8f2dc06df9', '4eea925b-76a6-51eb-a1b9-87f1c3b5cb8a', 'A', 'Ventricular septal defect', false, 0),
  ('4306a405-3b7a-5eca-a261-7bdbaddbac83', '4eea925b-76a6-51eb-a1b9-87f1c3b5cb8a', 'B', 'Tetralogy of Fallot', true, 1),
  ('fd74226a-fa45-566c-b995-e43d211811c5', '4eea925b-76a6-51eb-a1b9-87f1c3b5cb8a', 'C', 'Pulmonary hypertension', false, 2),
  ('fea87d85-33d5-53bb-98fc-8c794f40e85e', '4eea925b-76a6-51eb-a1b9-87f1c3b5cb8a', 'D', 'Transposition of the great arteries', false, 3),
  ('35713199-4d4a-5520-9b23-d5957663bc90', '4eea925b-76a6-51eb-a1b9-87f1c3b5cb8a', 'E', 'Hypoplastic left heart syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c9667cd-c99b-5593-829d-51978937e1ed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 12 year old girl with type 1 diabetes and her parents ask about a target for her glycaemic control. What HbA1c target does NICE recommend for children and young people with type 1 diabetes?', 'NICE (NG18) recommends an ideal HbA1c target of 48 mmol/mol or lower in children and young people with type 1 diabetes, to minimise long-term complications without problematic hypoglycaemia. Real-time continuous glucose monitoring is offered to all. Support from the multidisciplinary team, and sick day rules for ketones, are important.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b72b28de-562a-527b-8532-d25cec5c224c', '9c9667cd-c99b-5593-829d-51978937e1ed', 'A', '48 mmol/mol or lower', true, 0),
  ('fc962c45-9b12-5d53-af98-01a95f0c74de', '9c9667cd-c99b-5593-829d-51978937e1ed', 'B', '64 mmol/mol or lower', false, 1),
  ('2869caf9-5910-5a57-b9ee-910b447e1b3a', '9c9667cd-c99b-5593-829d-51978937e1ed', 'C', '58 mmol/mol or lower', false, 2),
  ('c984c5ca-12dc-588b-a321-dd6ed7ad3339', '9c9667cd-c99b-5593-829d-51978937e1ed', 'D', 'Below 30 mmol/mol', false, 3),
  ('28818dbc-dc7e-56de-b265-fcde18a5721b', '9c9667cd-c99b-5593-829d-51978937e1ed', 'E', '75 mmol/mol or lower', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('34d10024-bf74-527e-aa0b-15381f8ee7d8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 14 year old girl has not had a period yet. She has normal breast development (Tanner stage 4), normal growth and normal pubic hair. What is the SINGLE most appropriate management?', 'Primary amenorrhoea is investigated if there are no periods by 15 with normal secondary sexual characteristics, or by 13 with no secondary sexual development. Menarche usually follows breast budding by about 2-2.5 years. Causes include constitutional delay, Turner syndrome, imperforate hymen, Müllerian agenesis and androgen insensitivity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('373e514c-04e6-5b65-a401-bc455e1210ee', '34d10024-bf74-527e-aa0b-15381f8ee7d8', 'A', 'Start the combined pill', false, 0),
  ('e24613ba-172b-5d20-a57e-580d7870d916', '34d10024-bf74-527e-aa0b-15381f8ee7d8', 'B', 'Immediate karyotype', false, 1),
  ('b83f0347-0c73-56d7-9a41-56a341f07175', '34d10024-bf74-527e-aa0b-15381f8ee7d8', 'C', 'MRI pituitary', false, 2),
  ('4ac45a7b-ab39-58ac-8eca-9cf812729693', '34d10024-bf74-527e-aa0b-15381f8ee7d8', 'D', 'Refer for laparoscopy', false, 3),
  ('79cf4cf6-d064-52a3-b35d-ce5ff2ce8822', '34d10024-bf74-527e-aa0b-15381f8ee7d8', 'E', 'Reassure and review; investigate if no periods by age 15 with normal secondary sexual characteristics', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c6e1ecd4-578f-5ed9-9389-33cac11c66fc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old girl has breast development and pubic hair. Her height is above the 98th centile and she is growing fast. Her bone age is advanced. What is the SINGLE most appropriate initial investigation?', 'Precocious puberty is secondary sexual development before age 8 in girls (9 in boys). In girls it is usually central (gonadotropin-dependent) and idiopathic. A GnRH stimulation test shows central activation, and an MRI brain is considered to exclude pathology, which is more likely in boys. Treatment is GnRH analogues to stop progression and preserve final height.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0e07baf9-9841-5231-8b23-513800b751e9', 'c6e1ecd4-578f-5ed9-9389-33cac11c66fc', 'A', 'Pelvic ultrasound only', false, 0),
  ('223c83f6-9835-5b78-ad62-5652ae137898', 'c6e1ecd4-578f-5ed9-9389-33cac11c66fc', 'B', 'No investigation needed', false, 1),
  ('30969b3b-4f79-5bec-93a3-a6462af3d495', 'c6e1ecd4-578f-5ed9-9389-33cac11c66fc', 'C', 'Thyroid function only', false, 2),
  ('43f6cd41-5547-588f-88a1-c331a0ec72f3', 'c6e1ecd4-578f-5ed9-9389-33cac11c66fc', 'D', 'Basal and stimulated LH and FSH (GnRH stimulation test), followed by brain MRI', true, 3),
  ('04a490b1-d198-523d-81fe-cc7fe4246bff', 'c6e1ecd4-578f-5ed9-9389-33cac11c66fc', 'E', 'Karyotype', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9aa28488-86d4-5738-aed8-72d76c77416b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old boy wets his bed at night most nights. He has always been dry during the day. He is otherwise well and urinalysis is normal. His parents want a long-term solution. What is the SINGLE most appropriate first-line treatment?', 'Primary nocturnal enuresis is common, and treatment is usually offered from age 5. NICE recommends an enuresis alarm as first-line, plus positive reward systems (for behaviours, not dry nights), for long-term success. Desmopressin is used for short-term control (such as sleepovers) or if the alarm is unsuitable. Underlying causes such as constipation, UTI and diabetes should be excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('13a1572c-9555-53c3-aa09-46c9a9133bc0', '9aa28488-86d4-5738-aed8-72d76c77416b', 'A', 'Fluid restriction to nothing after 3 pm', false, 0),
  ('96ddce3d-67ee-5398-a126-0240ed8de336', '9aa28488-86d4-5738-aed8-72d76c77416b', 'B', 'Oxybutynin', false, 1),
  ('653a637a-2889-5d1e-9826-89e68fd9149b', '9aa28488-86d4-5738-aed8-72d76c77416b', 'C', 'Desmopressin for all children under 5', false, 2),
  ('d4a79b2c-5786-5a2a-aa47-c64f4c5391c9', '9aa28488-86d4-5738-aed8-72d76c77416b', 'D', 'Enuresis alarm with reward systems', true, 3),
  ('a8622df2-5e90-57fe-b8b1-73c55f1e3d69', '9aa28488-86d4-5738-aed8-72d76c77416b', 'E', 'Imipramine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9265ba48-3da9-5b2d-8737-c76269079e5a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 year old boy has been diagnosed with ADHD. Despite parent training and environmental changes at school, his symptoms continue to have a significant impact. What is the SINGLE most appropriate first-line medication?', 'NICE recommends methylphenidate as first-line medication for children aged 5 and over with ADHD when environmental changes are not enough. Before starting, check baseline height, weight, heart rate and BP, and do a cardiovascular history. Lisdexamfetamine is second-line. Growth, heart rate and BP must be monitored.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
