  ('c0cdc8be-ee6d-5f9a-aed5-ecbeb883e031', '9265ba48-3da9-5b2d-8737-c76269079e5a', 'A', 'Atomoxetine', false, 0),
  ('ab53bbd3-136b-5b58-a215-68261b69d5f9', '9265ba48-3da9-5b2d-8737-c76269079e5a', 'B', 'Melatonin', false, 1),
  ('9029c208-61e5-5b5f-be07-c3dc089fcb51', '9265ba48-3da9-5b2d-8737-c76269079e5a', 'C', 'Fluoxetine', false, 2),
  ('bd11fe59-96a3-5cbf-b9f2-aa375d6f6f81', '9265ba48-3da9-5b2d-8737-c76269079e5a', 'D', 'Risperidone', false, 3),
  ('a7d0cdd4-faac-576c-b844-0ab8d366f4cd', '9265ba48-3da9-5b2d-8737-c76269079e5a', 'E', 'Methylphenidate', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('82714a88-7475-5865-bcc1-88a0a4db6da8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 14 month old girl had a generalised tonic-clonic seizure lasting 25 minutes during a febrile illness. In the Emergency Department she recovers fully over the next hour. Which feature makes this a complex febrile seizure?', 'A complex febrile seizure is focal, lasts longer than 15 minutes, or recurs within 24 hours or within the same illness. Complex seizures need admission for observation and assessment to exclude CNS infection. A simple febrile seizure is generalised, lasts under 15 minutes and does not recur.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cec6e08d-4981-57bf-be8e-e179b01e76bd', '82714a88-7475-5865-bcc1-88a0a4db6da8', 'A', 'Fever over 38°C', false, 0),
  ('4363b68e-d6e4-50d2-85e8-8fffc43a8e48', '82714a88-7475-5865-bcc1-88a0a4db6da8', 'B', 'Generalised seizure', false, 1),
  ('45b90815-53fe-5678-a864-71763f08b100', '82714a88-7475-5865-bcc1-88a0a4db6da8', 'C', 'Age 14 months', false, 2),
  ('367b887c-147e-509e-a189-74550ad910a8', '82714a88-7475-5865-bcc1-88a0a4db6da8', 'D', 'Full recovery within an hour', false, 3),
  ('4434b951-ebd8-5f8b-ac68-3b122fa7ce30', '82714a88-7475-5865-bcc1-88a0a4db6da8', 'E', 'Duration longer than 15 minutes', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f8565dbe-1fad-5413-b984-bcd237c54975', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old girl has brief episodes of staring several times a day, lasting about 10 seconds, during which she does not respond and her eyelids flutter. She resumes activity immediately afterwards. The episodes can be triggered by hyperventilation. What is the SINGLE most likely diagnosis?', 'Childhood absence epilepsy causes many brief absences a day with immediate recovery, often triggered by hyperventilation. EEG shows 3 Hz spike-and-wave discharges. Ethosuximide is first-line (sodium valproate is an alternative but avoided in girls of childbearing potential). Most children grow out of it.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6d5acd25-0b72-5704-aa57-ce656e4d7c0b', 'f8565dbe-1fad-5413-b984-bcd237c54975', 'A', 'Reflex anoxic seizures', false, 0),
  ('248f1be3-c5a0-5baf-b841-375a6c108fa7', 'f8565dbe-1fad-5413-b984-bcd237c54975', 'B', 'Childhood absence epilepsy', true, 1),
  ('cf1b08d3-bad9-5d8c-9a1e-f18b8f6a15f0', 'f8565dbe-1fad-5413-b984-bcd237c54975', 'C', 'Daydreaming', false, 2),
  ('d93ad9a5-236b-5917-ba24-eaac890a9693', 'f8565dbe-1fad-5413-b984-bcd237c54975', 'D', 'Juvenile myoclonic epilepsy', false, 3),
  ('a578896b-a767-52c5-a28b-3e2202944437', 'f8565dbe-1fad-5413-b984-bcd237c54975', 'E', 'Focal seizures', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4cf3e59d-cc75-5982-90e9-65e8b908934f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 15 year old boy has a sudden generalised tonic-clonic seizure early in the morning after a late night. For months he has had jerks of his arms in the morning and has dropped things. What is the SINGLE most likely diagnosis?', 'Juvenile myoclonic epilepsy presents in adolescence with morning myoclonic jerks, generalised tonic-clonic seizures and sometimes absences. It is often triggered by sleep deprivation and alcohol, and EEG shows generalised polyspike-and-wave. Treatment is specialist-led. Sodium valproate is effective but its use is restricted by the MHRA (in females of childbearing potential and males under 55), so levetiracetam or lamotrigine are often used. Carbamazepine and phenytoin can worsen myoclonus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bee78a9b-ae20-5957-877f-7cb6c5cfb20c', '4cf3e59d-cc75-5982-90e9-65e8b908934f', 'A', 'Focal epilepsy', false, 0),
  ('7d431f54-6391-5fb0-93c7-1f5d80507926', '4cf3e59d-cc75-5982-90e9-65e8b908934f', 'B', 'Childhood absence epilepsy', false, 1),
  ('76df737d-c65e-5992-b6c3-a3ebfdda626e', '4cf3e59d-cc75-5982-90e9-65e8b908934f', 'C', 'Psychogenic non-epileptic seizures', false, 2),
  ('cb3069c7-046e-5ac1-b7a8-0b4f83343cb5', '4cf3e59d-cc75-5982-90e9-65e8b908934f', 'D', 'Juvenile myoclonic epilepsy', true, 3),
  ('817d2e9c-b974-5451-9654-e19f47a6fb9e', '4cf3e59d-cc75-5982-90e9-65e8b908934f', 'E', 'Vasovagal syncope', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3adb80e7-ad11-5993-9257-e2d337a26cc7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'An 8 week old boy has vomiting worsening over 3 weeks. He is feeding well and is constantly hungry but is losing weight. He has wet nappies and no diarrhoea. His pulse rate is 110 bpm, respiratory rate 24 breaths per minute and oxygen saturation 98% breathing air. Arterial blood gases are taken. Which is the most likely acid base finding?', 'Progressive non-bilious vomiting in a hungry, weight-losing infant aged 2-8 weeks is pyloric stenosis. Loss of gastric acid causes a hypochloraemic, hypokalaemic metabolic alkalosis. Diagnosis is by ultrasound, and treatment is fluid and electrolyte correction followed by pyloromyotomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d308603e-de10-5845-842b-f825aa7448f8', '3adb80e7-ad11-5993-9257-e2d337a26cc7', 'A', 'Metabolic acidosis', false, 0),
  ('aae38824-e39b-5ab7-ad49-f7de37af2c7b', '3adb80e7-ad11-5993-9257-e2d337a26cc7', 'B', 'Metabolic alkalosis', true, 1),
  ('d5f35bc7-4cc0-51d7-8e8c-172110408753', '3adb80e7-ad11-5993-9257-e2d337a26cc7', 'C', 'Normal acid/base state', false, 2),
  ('37a89024-de74-5fc4-a883-2f65f40adf19', '3adb80e7-ad11-5993-9257-e2d337a26cc7', 'D', 'Respiratory acidosis', false, 3),
  ('fe8861a1-8e99-5153-86b6-ae203e06bc42', '3adb80e7-ad11-5993-9257-e2d337a26cc7', 'E', 'Respiratory alkalosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ddb04dc7-4931-5220-8481-dd42fe45f841', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 year old boy has an episode of unconsciousness and is seen in the Emergency Department. He ran into his school desk, cried out in pain and then fell to the floor unconscious. He was limp and pale for 1 minute then his body became stiff and he started to shake. His eyes rolled back and he had froth foaming from his mouth. The episode lasted 2 minutes and he gradually started to regain consciousness. He had one previous similar episode following a cut to his finger. Neurological examination is normal. Which is the most likely diagnosis?', 'A reflex anoxic seizure is triggered by a painful or frightening stimulus, which causes vagally mediated asystole. The child goes pale, limp and loses consciousness, sometimes followed by brief stiffening or jerking, then recovers quickly. It is benign and not epilepsy. An ECG is reasonable to exclude cardiac causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6a522bf5-dced-59dd-a223-c2f3adb6f626', 'ddb04dc7-4931-5220-8481-dd42fe45f841', 'A', 'Absence seizure', false, 0),
  ('aa7fd5f2-068c-5328-969c-3c1dd4277bae', 'ddb04dc7-4931-5220-8481-dd42fe45f841', 'B', 'Febrile convulsion', false, 1),
  ('20a0ff8e-2967-5b4e-bfac-43374a5a450a', 'ddb04dc7-4931-5220-8481-dd42fe45f841', 'C', 'Hyperventilation', false, 2),
  ('c7880b76-80b4-5bae-bd6a-f8ec84de9633', 'ddb04dc7-4931-5220-8481-dd42fe45f841', 'D', 'Reflex anoxic seizure', true, 3),
  ('0f4d7b1a-1ba6-54db-8ca4-268a27a73caf', 'ddb04dc7-4931-5220-8481-dd42fe45f841', 'E', 'Tonic-clonic seizure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fe0b18e3-89ee-5c86-b4cd-10d3b7f0a3c1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 9 year old boy has a cough and worsening breathlessness and is seen in the Emergency Department. He has asthma. He was given salbutamol and ipratropium nebulisers and oral prednisolone 1 hour ago. He is conscious and talking in full sentences. His pulse rate is 125 bpm, respiratory rate 30 breaths per minute and oxygen saturation 95% on 10 litres of oxygen. He has intercostal recession and has bilateral wheeze throughout both lung fields. Which is the most appropriate next management step?', 'This child has acute severe asthma that has not responded to first-line nebulisers and steroids. BTS/SIGN guidance recommends considering IV magnesium sulfate as the next step (a single bolus of 40 mg/kg in children). IV aminophylline is used after senior review if there is still no response. Intubation is for life-threatening deterioration.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3c1a5c30-645c-54bc-9644-df28cb9c6394', 'fe0b18e3-89ee-5c86-b4cd-10d3b7f0a3c1', 'A', 'Intravenous aminophylline infusion', false, 0),
  ('4ce6725c-5edb-5f61-aa44-36a033033b30', 'fe0b18e3-89ee-5c86-b4cd-10d3b7f0a3c1', 'B', 'Intravenous hydrocortisone bolus', false, 1),
  ('193c88be-7c43-51d1-8427-3dbd7cf17cb4', 'fe0b18e3-89ee-5c86-b4cd-10d3b7f0a3c1', 'C', 'Intravenous magnesium sulfate infusion', true, 2),
  ('55f8fa7f-8238-53c3-a044-48d8cc8fda62', 'fe0b18e3-89ee-5c86-b4cd-10d3b7f0a3c1', 'D', 'Intubate and ventilate', false, 3),
  ('e5a1d2c7-9a5b-52c5-a93f-706a3b5c0a70', 'fe0b18e3-89ee-5c86-b4cd-10d3b7f0a3c1', 'E', 'Nebulised adrenaline', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b60d9af8-5cb0-5da9-94c4-6b82da8d9f46', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'An 18 month old girl has poor weight gain and is seen in the GP surgery. She eats the same food as her 3 year old brother. She has had loose stools for several months. She has had no vomiting. Her weight is 10.5 kg. Her abdomen is distended and she has loose skin over her buttocks. Which is the most likely underlying cause of her poor weight gain?', 'Faltering growth, chronic loose stools, abdominal distension and wasted buttocks in a toddler after starting gluten are typical of coeliac disease. Screening is with IgA tTG antibodies and total IgA while the child is still eating gluten. Treatment is a lifelong gluten-free diet.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6172df9f-4619-5f66-a484-4a76cb6c063d', 'b60d9af8-5cb0-5da9-94c4-6b82da8d9f46', 'A', 'Coeliac disease', true, 0),
  ('48d563cb-6263-5659-a621-9b5041a17253', 'b60d9af8-5cb0-5da9-94c4-6b82da8d9f46', 'B', 'Cow’s milk protein allergy', false, 1),
  ('dc1842cf-0b3a-55dc-84a9-9805a3208197', 'b60d9af8-5cb0-5da9-94c4-6b82da8d9f46', 'C', 'Crohn’s disease', false, 2),
  ('83cebfbe-4727-56e1-b51f-d8c4590b999c', 'b60d9af8-5cb0-5da9-94c4-6b82da8d9f46', 'D', 'Lactose intolerance', false, 3),
  ('9e3cc102-e16f-531a-8d77-1cbc8c19c656', 'b60d9af8-5cb0-5da9-94c4-6b82da8d9f46', 'E', 'Non-organic failure to thrive', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7e8c0d35-6b7d-5f51-91b9-d21400182869', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'The parents of an 18 month old boy are concerned about his development. He scribbles meaninglessly using a pencil and demonstrates no hand dominance. He has a social smile. He does not hold eye contact. He has started walking. He is unable to run or kick a ball. He speaks two-syllable words with no meaning. Which developmental feature gives the most cause for concern?', 'Poor eye contact at 18 months is a red flag for autism spectrum disorder and needs referral for developmental assessment. Many 18-month-olds do not yet run well or kick a ball, scribble without purpose and have not yet developed hand dominance (which develops after about 18 months; earlier dominance is a red flag).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5fde54df-6a6c-5c89-8382-90c1f23102d6', '7e8c0d35-6b7d-5f51-91b9-d21400182869', 'A', 'Absence of hand dominance', false, 0),
  ('96bce41d-8185-5254-b79e-47639a5605a7', '7e8c0d35-6b7d-5f51-91b9-d21400182869', 'B', 'Inability to hold eye contact', true, 1),
  ('63cae46d-199e-52e6-a771-97d4b346b796', '7e8c0d35-6b7d-5f51-91b9-d21400182869', 'C', 'Inability to run or kick a ball', false, 2),
  ('b8dc62e9-129c-5a04-b3bc-550d37ebbfa1', '7e8c0d35-6b7d-5f51-91b9-d21400182869', 'D', 'Meaningless scribbling', false, 3),
  ('4847cd18-74fd-5831-b996-b0eacc9d4af1', '7e8c0d35-6b7d-5f51-91b9-d21400182869', 'E', 'Speaking two-syllable words with no meaning', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('65ace3a9-e0eb-5888-83df-137da03e084a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 10 month old boy has vomiting and fever for 3 days and is seen in the Emergency Department. He is drowsy and has cool peripheries. His weight is 8 kg. A 20 mL/kg intravenous bolus over 20 minutes is planned. Which is the correct fluid bolus to give?', 'For fluid resuscitation in children, NICE recommends an isotonic crystalloid with sodium in the range 131-154 mmol/L, such as 0.9% sodium chloride, at 10-20 mL/kg (10 mL/kg is now often preferred in sepsis). Hypotonic fluids risk hyponatraemia and cerebral oedema, and glucose solutions are not resuscitation fluids.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b4cfbc21-a160-5807-b168-d0d20854caaa', '65ace3a9-e0eb-5888-83df-137da03e084a', 'A', '0.9% sodium chloride', true, 0),
  ('eafd0d85-d150-5a4c-84b8-500b0ccb3731', '65ace3a9-e0eb-5888-83df-137da03e084a', 'B', '0.18% sodium chloride', false, 1),
  ('f473f89e-0b9b-591e-965c-c3db057e6437', '65ace3a9-e0eb-5888-83df-137da03e084a', 'C', '0.45% sodium chloride', false, 2),
  ('a6598fb1-959d-5bdd-a9a6-dd60dffcf1fc', '65ace3a9-e0eb-5888-83df-137da03e084a', 'D', '5% glucose', false, 3),
  ('61c51f81-4c62-5c49-8dc4-5456a52e0aa6', '65ace3a9-e0eb-5888-83df-137da03e084a', 'E', '10% glucose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8ab9edd2-7c65-56d1-a98b-1bd48155721e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 day old boy has poor urinary stream and is referred by his GP to the paediatric emergency clinic. He has normal genitalia and remainder of examination is unremarkable. antenatal ultrasound showed bilateral hydronephrosis, thickened bladder wall and bladder diverticula. Which is the most appropriate diagnostic investigation?', 'A newborn boy with a poor urinary stream, antenatal bilateral hydronephrosis and a thick-walled bladder with diverticula suggests posterior urethral valves. A micturating cystourethrogram (MCUG) is the diagnostic investigation. Treatment is endoscopic valve ablation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('daeee23d-e173-5b71-86b1-429b1b025d9d', '8ab9edd2-7c65-56d1-a98b-1bd48155721e', 'A', 'CT scan of renal tract', false, 0),
  ('ab3914f9-0ae8-5eac-9e0a-e52498182751', '8ab9edd2-7c65-56d1-a98b-1bd48155721e', 'B', 'DMSA', false, 1),
  ('7d410256-8ad8-56cc-9661-a15bf6ea8e3a', '8ab9edd2-7c65-56d1-a98b-1bd48155721e', 'C', 'MCUG', true, 2),
  ('21cebea6-7bdc-5751-8aeb-2462c3a412d8', '8ab9edd2-7c65-56d1-a98b-1bd48155721e', 'D', 'MRI scan of renal tract', false, 3),
  ('22607f59-c2a0-5d1e-8155-76a0539cd27a', '8ab9edd2-7c65-56d1-a98b-1bd48155721e', 'E', 'Repeat ultrasound of renal tract', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5e28b610-f13f-5d4e-b360-0dd5525c8d24', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 23 year old woman falls onto her outstretched right hand while skiing. She has tenderness in the anatomical snuffbox and pain on axial loading of the thumb. Initial scaphoid-view X-rays show no fracture. What is the SINGLE most appropriate next investigation?', 'Scaphoid fractures are often not visible on initial X-rays, and a missed fracture risks avascular necrosis and non-union because the blood supply flows from distal to proximal. NICE recommends MRI as the first-line investigation if a scaphoid fracture is still suspected after normal X-rays. CT is an alternative if MRI is unavailable. The wrist should be immobilised until the fracture has been excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('91a38781-68fa-5473-a51e-e44190c56aae', '5e28b610-f13f-5d4e-b360-0dd5525c8d24', 'A', 'Repeat X-ray in 6 weeks with no immobilisation', false, 0),
  ('4acf52f6-d83b-5fb6-95cb-13535aca1689', '5e28b610-f13f-5d4e-b360-0dd5525c8d24', 'B', 'MRI of the wrist', true, 1),
  ('07c8ae91-0314-5142-b03b-e9e5910efb65', '5e28b610-f13f-5d4e-b360-0dd5525c8d24', 'C', 'Isotope bone scan as first-line', false, 2),
  ('c0e67da3-2576-578f-b686-f8235a82adb2', '5e28b610-f13f-5d4e-b360-0dd5525c8d24', 'D', 'No further investigation needed', false, 3),
  ('f7d3b097-9108-5673-9a37-8fe5a21cab30', '5e28b610-f13f-5d4e-b360-0dd5525c8d24', 'E', 'Ultrasound of the wrist', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8f785381-ca76-5edf-a847-4878702c2f12', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 63 year old man has a sudden collapse with severe headache. A non-contrast CT of the head shows a biconvex (lens-shaped) hyperdense collection in the right temporal region that does not cross the suture lines. He was hit on the side of his head with a cricket ball earlier, and had a lucid interval. What is the SINGLE most likely diagnosis?', 'A biconvex (lentiform) collection limited by suture lines, after temporal trauma with a lucid interval, is an extradural haematoma, usually from a tear of the middle meningeal artery under the pterion. It needs urgent neurosurgical evacuation. An acute subdural haematoma is crescent-shaped, crosses sutures and comes from bridging veins. Chronic subdurals are hypodense and common in older people and those with alcohol dependence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5d5aca5c-01c2-512b-9289-4e8543e5c646', '8f785381-ca76-5edf-a847-4878702c2f12', 'A', 'Acute subdural haematoma', false, 0),
  ('6e2756e0-7729-58bc-9a7a-ef22110538d8', '8f785381-ca76-5edf-a847-4878702c2f12', 'B', 'Subarachnoid haemorrhage', false, 1),
  ('1553d200-712d-59d7-a619-69c85344dd94', '8f785381-ca76-5edf-a847-4878702c2f12', 'C', 'Chronic subdural haematoma', false, 2),
  ('959012f8-3e84-5041-bb3b-b1a9427d6683', '8f785381-ca76-5edf-a847-4878702c2f12', 'D', 'Intracerebral haemorrhage', false, 3),
  ('9bc4cf91-a696-5de4-8a9c-e8d24b8753d2', '8f785381-ca76-5edf-a847-4878702c2f12', 'E', 'Extradural haematoma', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f4d30918-3b11-53fc-9ea6-34152004f3fd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 36 year old man with severe abdominal pain has an erect chest X-ray in the Emergency Department. It shows a crescent of free air under the right hemidiaphragm. He takes ibuprofen regularly for back pain. What is the SINGLE most likely diagnosis?', 'Free air under the diaphragm (pneumoperitoneum) on an erect chest X-ray means a perforated hollow viscus, most often a perforated peptic ulcer (NSAIDs are a risk factor). A CT abdomen is more sensitive and confirms it. Management is resuscitation, IV PPI and antibiotics, nil by mouth and usually emergency surgery (laparoscopic repair with an omental patch).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f86db6d8-1ed7-5018-9d1b-89bfaa0ea46e', 'f4d30918-3b11-53fc-9ea6-34152004f3fd', 'A', 'Perforated peptic ulcer', true, 0),
  ('42b77d4f-6341-5ba9-a84b-b7a73449f67b', 'f4d30918-3b11-53fc-9ea6-34152004f3fd', 'B', 'Small bowel obstruction', false, 1),
  ('969822bc-0c7c-57d3-bb6e-24e95f425c61', 'f4d30918-3b11-53fc-9ea6-34152004f3fd', 'C', 'Acute cholecystitis', false, 2),
  ('f8437da7-c28c-5470-809e-c2a8e4a5e6ee', 'f4d30918-3b11-53fc-9ea6-34152004f3fd', 'D', 'Renal colic', false, 3),
  ('5618861d-c445-5373-ac9d-7c1d757663d5', 'f4d30918-3b11-53fc-9ea6-34152004f3fd', 'E', 'Acute pancreatitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4b1cf75-36bd-5aff-9755-4981d529f32a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 55 year old man has had sudden severe abdominal pain. An abdominal X-ray shows both sides of the bowel wall clearly outlined (Rigler''s sign). What does this sign indicate?', 'Rigler''s sign is gas on both sides of the bowel wall, meaning free intraperitoneal gas, which suggests a perforated viscus. An erect chest X-ray (gas under the diaphragm) is more sensitive, and CT is the most sensitive. Other signs of pneumoperitoneum include the football sign (in infants) and the falciform ligament sign.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6f02e24c-f231-5334-a5e7-a4d44e731463', 'e4b1cf75-36bd-5aff-9755-4981d529f32a', 'A', 'Small bowel obstruction', false, 0),
  ('bc550197-7778-5d7f-a111-3d26221d6fbb', 'e4b1cf75-36bd-5aff-9755-4981d529f32a', 'B', 'Pneumoperitoneum (free intraperitoneal gas)', true, 1),
  ('c641a4ef-89c3-53e7-8b8d-4925af1365c1', 'e4b1cf75-36bd-5aff-9755-4981d529f32a', 'C', 'Toxic megacolon', false, 2),
  ('082742b8-7bce-57c1-9b6f-5670a5914e95', 'e4b1cf75-36bd-5aff-9755-4981d529f32a', 'D', 'Ileus', false, 3),
  ('94b6d616-8f7d-5533-b032-530b128f3a41', 'e4b1cf75-36bd-5aff-9755-4981d529f32a', 'E', 'Sigmoid volvulus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a9669786-3933-55b2-8d6a-681e3f33ac9c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 35 year old woman with ulcerative colitis has severe abdominal pain, fever and distension. An abdominal X-ray shows a dilated transverse colon of 7 cm with mucosal islands and loss of haustra. What is the SINGLE most likely diagnosis?', 'Toxic megacolon is non-obstructive colonic dilatation (over 6 cm) with systemic toxicity, complicating severe UC, C. difficile infection or other colitis. It carries a high risk of perforation. Management is IV steroids (for UC), fluids, antibiotics, avoiding opioids and antimotility drugs, and urgent surgical review, often needing colectomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('deee939e-dd95-5d87-bc02-266d9b29b3dd', 'a9669786-3933-55b2-8d6a-681e3f33ac9c', 'A', 'Toxic megacolon', true, 0),
  ('1e06173a-d1f3-5284-a0c8-b92fbba05391', 'a9669786-3933-55b2-8d6a-681e3f33ac9c', 'B', 'Small bowel obstruction', false, 1),
  ('9651b53c-9043-5b1a-9d51-92b1cd69b0ad', 'a9669786-3933-55b2-8d6a-681e3f33ac9c', 'C', 'Sigmoid volvulus', false, 2),
  ('e7e43106-edc9-574e-a3ef-73649fdaf7de', 'a9669786-3933-55b2-8d6a-681e3f33ac9c', 'D', 'Perforated appendix', false, 3),
  ('8171a3b2-d429-5c00-bc9e-f0688eb125ec', 'a9669786-3933-55b2-8d6a-681e3f33ac9c', 'E', 'Pseudo-obstruction', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d4ac1165-7dc5-5c53-9486-310c0dcdd12b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 65 year old man has a chest X-ray showing an opacity in the right lower zone that obscures the right heart border. Which lobe is MOST likely affected?', 'The silhouette sign helps localise pathology. Right middle lobe pathology obscures the right heart border, lingula pathology the left heart border, and lower lobe pathology the hemidiaphragm. Left lower lobe collapse gives a ''sail sign'' behind the heart. This helps in localising pneumonia, collapse and masses.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e7efa3f6-0b5b-5069-ab2b-4e607b545d07', 'd4ac1165-7dc5-5c53-9486-310c0dcdd12b', 'A', 'Right middle lobe', true, 0),
  ('6142bc46-cf84-5ecb-bae3-53289a870585', 'd4ac1165-7dc5-5c53-9486-310c0dcdd12b', 'B', 'Lingula', false, 1),
  ('5485a690-5b07-565d-a326-01765541277f', 'd4ac1165-7dc5-5c53-9486-310c0dcdd12b', 'C', 'Left lower lobe', false, 2),
  ('96ef71b3-7d59-571d-898c-70522eb1e229', 'd4ac1165-7dc5-5c53-9486-310c0dcdd12b', 'D', 'Right lower lobe', false, 3),
  ('4da756d0-94a8-54d3-b8e3-f77764255462', 'd4ac1165-7dc5-5c53-9486-310c0dcdd12b', 'E', 'Right upper lobe', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ede22c12-7899-5f7f-9daf-84c13bc1a6f7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 72 year old woman has a chest X-ray showing a triangular opacity behind the heart with a ''sail'' appearance and loss of the medial left hemidiaphragm. What is the SINGLE most likely diagnosis?', 'Left lower lobe collapse shows a triangular retrocardiac opacity (the sail sign) with loss of the medial left hemidiaphragm. Lobar collapse in an adult smoker suggests an obstructing endobronchial tumour, which needs CT and bronchoscopy. Other causes include mucus plugging (after surgery) and foreign bodies.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3674e5d2-8e41-5fab-bbd2-ec0415215b60', 'ede22c12-7899-5f7f-9daf-84c13bc1a6f7', 'A', 'Pneumothorax', false, 0),
  ('924e2ac2-f43b-5c4e-8ffd-110685426530', 'ede22c12-7899-5f7f-9daf-84c13bc1a6f7', 'B', 'Left lower lobe collapse', true, 1),
  ('177d9808-8520-5c66-bc14-79a82c84a85c', 'ede22c12-7899-5f7f-9daf-84c13bc1a6f7', 'C', 'Pericardial effusion', false, 2),
  ('681f59f3-15bb-55c2-9106-dab91e4a4f3b', 'ede22c12-7899-5f7f-9daf-84c13bc1a6f7', 'D', 'Right middle lobe collapse', false, 3),
  ('f9d64dec-45a6-5972-b329-aa5be7a8935c', 'ede22c12-7899-5f7f-9daf-84c13bc1a6f7', 'E', 'Hiatus hernia only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e90541f5-8204-5f76-8702-0f2cdccde9ef', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 40 year old woman has a chest X-ray showing a widened mediastinum in the anterior compartment. Which of the following is a recognised cause of an anterior mediastinal mass?', 'Anterior mediastinal masses are thymoma (associated with myasthenia gravis), teratoma or germ cell tumour, retrosternal thyroid and lymphoma. Middle mediastinal masses include lymphadenopathy and bronchogenic cysts. Posterior masses include neurogenic tumours, oesophageal lesions and descending aortic aneurysm. CT is the next step.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fbeb0858-e1fe-53d2-a6f4-ed19f4813e29', 'e90541f5-8204-5f76-8702-0f2cdccde9ef', 'A', 'Oesophageal cancer', false, 0),
  ('6471021d-3bb0-5b40-8ed1-39fb8797f7c8', 'e90541f5-8204-5f76-8702-0f2cdccde9ef', 'B', 'Neurofibroma', false, 1),
  ('40dce77e-be87-52b0-9da6-3e163926bfc8', 'e90541f5-8204-5f76-8702-0f2cdccde9ef', 'C', 'Thymoma (the ''4 Ts'': thymoma, teratoma, thyroid, ''terrible'' lymphoma)', true, 2),
  ('71628e4e-5d67-5f5e-b4cd-5780c1502c9e', 'e90541f5-8204-5f76-8702-0f2cdccde9ef', 'D', 'Hiatus hernia', false, 3),
  ('d0d99493-5330-5e6f-8fa8-86cda7bc25e7', 'e90541f5-8204-5f76-8702-0f2cdccde9ef', 'E', 'Aortic aneurysm of the descending aorta', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('605ae5f4-82cd-5a23-9ff8-981418fa7bf9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 60 year old man had a CT head after a fall 3 weeks ago, and is now confused with headache. CT shows a crescent-shaped hypodense collection over the left hemisphere. He drinks heavily. What is the SINGLE most likely diagnosis?', 'Chronic subdural haematoma is a crescent-shaped collection that is hypodense on CT after 3 weeks or more (acute subdurals are hyperdense). It comes from torn bridging veins, often after minor trauma in older people, those with alcohol dependence and those on anticoagulants. It presents with fluctuating confusion, headache and focal signs. Treatment is burr hole drainage if symptomatic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('25408724-636f-5192-a91e-889c1db15ebe', '605ae5f4-82cd-5a23-9ff8-981418fa7bf9', 'A', 'Chronic subdural haematoma', true, 0),
  ('4473b2ec-8f66-5f12-b307-7ce1d69ab94c', '605ae5f4-82cd-5a23-9ff8-981418fa7bf9', 'B', 'Subarachnoid haemorrhage', false, 1),
  ('8f7890bb-effc-5d8a-be0a-2783d7ea7cf2', '605ae5f4-82cd-5a23-9ff8-981418fa7bf9', 'C', 'Ischaemic stroke', false, 2),
  ('35f4a42c-fbdf-5080-8745-6a8fd58bc534', '605ae5f4-82cd-5a23-9ff8-981418fa7bf9', 'D', 'Acute extradural haematoma', false, 3),
  ('fe84734a-dcc0-5c01-8428-beb5c5031421', '605ae5f4-82cd-5a23-9ff8-981418fa7bf9', 'E', 'Brain abscess', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f6680694-b4f4-5869-b99c-8a51af55ab0d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 45 year old woman has sudden severe headache. Non-contrast CT shows hyperdensity in the basal cisterns and Sylvian fissures. What is the SINGLE most appropriate next investigation?', 'Blood in the basal cisterns on non-contrast CT confirms subarachnoid haemorrhage. CT angiography identifies the source, most often a ruptured berry aneurysm. Management includes nimodipine (to prevent vasospasm), neurosurgical referral and endovascular coiling or clipping. Complications include rebleeding, vasospasm, hydrocephalus and hyponatraemia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6c24ad8d-8295-5738-876b-34cb8eabcbbc', 'f6680694-b4f4-5869-b99c-8a51af55ab0d', 'A', 'Lumbar puncture', false, 0),
  ('425f7872-d87f-5584-ab90-c6b6d8412397', 'f6680694-b4f4-5869-b99c-8a51af55ab0d', 'B', 'CT angiography to identify an aneurysm', true, 1),
  ('177f8bd1-2c8c-5d74-b023-96970aefec4c', 'f6680694-b4f4-5869-b99c-8a51af55ab0d', 'C', 'EEG', false, 2),
  ('fa5de0c0-0026-549d-b9e3-b8c3c4cb5945', 'f6680694-b4f4-5869-b99c-8a51af55ab0d', 'D', 'Discharge with analgesia', false, 3),
  ('4ddc87ed-7340-5ba3-8643-2f138d952376', 'f6680694-b4f4-5869-b99c-8a51af55ab0d', 'E', 'MRI brain only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('575423db-fddd-5744-86be-5a627acd3e82', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 25 year old pregnant woman (20 weeks) needs imaging for suspected appendicitis after an inconclusive ultrasound. Which imaging is MOST appropriate?', 'In pregnancy, ultrasound is first-line. If inconclusive, MRI without gadolinium is preferred because it involves no ionising radiation. CT can be used if MRI is unavailable and the benefit outweighs the risk. Gadolinium contrast is generally avoided in pregnancy. Appendicitis is the commonest non-obstetric surgical emergency in pregnancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3764b9ba-082e-5b70-b3e4-75d2b1b3b4c3', '575423db-fddd-5744-86be-5a627acd3e82', 'A', 'No imaging; proceed to laparotomy without imaging in all cases', false, 0),
  ('f81d19ff-7c33-5054-b045-19e76ebdb9b4', '575423db-fddd-5744-86be-5a627acd3e82', 'B', 'Abdominal X-ray', false, 1),
  ('11225d90-b605-53a0-b37b-61d8226c798f', '575423db-fddd-5744-86be-5a627acd3e82', 'C', 'CT abdomen with contrast', false, 2),
  ('190eabd0-47d2-5fc9-9e1f-d6ecf7707451', '575423db-fddd-5744-86be-5a627acd3e82', 'D', 'Nuclear medicine scan', false, 3),
  ('188eeaee-8e4f-58c1-8925-a1f1808316d1', '575423db-fddd-5744-86be-5a627acd3e82', 'E', 'MRI without gadolinium', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8b860164-e2f3-5584-9c43-9695f41f1f82', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 55 year old man is having a contrast-enhanced CT. Which question is MOST important to ask before giving iodinated contrast?', 'Before iodinated contrast, check for previous contrast reactions or allergies (premedication may be needed), kidney function (risk of contrast-associated AKI, so hydrate at-risk patients) and metformin use. Thyroid disease should also be considered, because of the risk of thyrotoxicosis. Pregnancy status should be checked for radiation exposure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7c5bac0a-4fc9-5081-9471-d751ac2faa42', '8b860164-e2f3-5584-9c43-9695f41f1f82', 'A', 'His blood group', false, 0),
  ('4e93eb61-11f4-50fd-a7d3-b1527b807fa3', '8b860164-e2f3-5584-9c43-9695f41f1f82', 'B', 'History of previous contrast reaction, kidney function and metformin use', true, 1),
  ('fb998566-9b70-5ec1-9f88-39b02ceba5d7', '8b860164-e2f3-5584-9c43-9695f41f1f82', 'C', 'His favourite food', false, 2),
  ('2760ec2f-8e5c-55a3-9cf9-bca620d4ef5c', '8b860164-e2f3-5584-9c43-9695f41f1f82', 'D', 'His height', false, 3),
  ('131a483b-df39-5cdb-a5c5-768566f5adb8', '8b860164-e2f3-5584-9c43-9695f41f1f82', 'E', 'Whether he has had an MRI before', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0f08f677-a0bd-5857-9510-10532a6ad441', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 40 year old man needs an MRI for back pain. Which of the following is an ABSOLUTE contraindication to MRI?', 'Absolute contraindications to MRI include non-MRI-conditional pacemakers and ICDs, metallic intraocular foreign bodies, some cochlear implants and certain ferromagnetic aneurysm clips. Many modern devices are MRI-conditional. Claustrophobia is a relative contraindication. Joint replacements and dental work are usually safe, although they cause artefacts.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('acd48c13-9e90-5f29-96d8-48766850b96c', '0f08f677-a0bd-5857-9510-10532a6ad441', 'A', 'Hip replacement', false, 0),
  ('9c42c840-f7d2-5908-87b6-4e6f68f89d25', '0f08f677-a0bd-5857-9510-10532a6ad441', 'B', 'Pregnancy in the second trimester', false, 1),
  ('b959c879-b746-5a98-845f-b8b5403c4272', '0f08f677-a0bd-5857-9510-10532a6ad441', 'C', 'Dental fillings', false, 2),
  ('dd36b0a2-478e-5842-ac61-133c3db062de', '0f08f677-a0bd-5857-9510-10532a6ad441', 'D', 'An older non-MRI-conditional cardiac pacemaker or a metallic intraocular foreign body', true, 3),
  ('70e07d08-7453-5b16-8f9f-aa53365954ed', '0f08f677-a0bd-5857-9510-10532a6ad441', 'E', 'Claustrophobia (relative only)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4a95c89-4535-5ec5-9fbb-ca5ee096cd0a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 30 year old woman has right upper quadrant pain. Which imaging is FIRST-LINE for suspected gallbladder disease?', 'Ultrasound is first-line for gallbladder and biliary disease: it detects stones (with acoustic shadowing), wall thickening, pericholecystic fluid and duct dilatation, without radiation. MRCP is used for suspected common bile duct stones. A HIDA scan helps in acalculous cholecystitis or biliary dyskinesia. Only about 10-15% of gallstones are visible on plain X-ray.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('547d5be2-cf52-5f03-a56c-f52d1de60675', 'e4a95c89-4535-5ec5-9fbb-ca5ee096cd0a', 'A', 'Abdominal ultrasound', true, 0),
  ('a8342044-c506-5597-9592-58b1227442d9', 'e4a95c89-4535-5ec5-9fbb-ca5ee096cd0a', 'B', 'CT abdomen', false, 1),
  ('0614b630-aee9-573e-9b15-be2e92c299a0', 'e4a95c89-4535-5ec5-9fbb-ca5ee096cd0a', 'C', 'Plain abdominal X-ray', false, 2),
  ('bea87238-d96a-5003-9f40-a4086fd520ad', 'e4a95c89-4535-5ec5-9fbb-ca5ee096cd0a', 'D', 'MRCP', false, 3),
  ('d4b90de0-98f0-5267-aea1-8c68c95e478b', 'e4a95c89-4535-5ec5-9fbb-ca5ee096cd0a', 'E', 'HIDA scan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('05f52c1e-18ea-550a-870f-52bae669a090', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 52 year old man has a chest X-ray showing bilateral hilar enlargement, upper lobe diversion, Kerley B lines, cardiomegaly and small pleural effusions. What is the SINGLE most likely diagnosis?', 'Chest X-ray signs of heart failure (ABCDE): Alveolar oedema (bat''s wing), Kerley B lines (interstitial oedema), Cardiomegaly (cardiothoracic ratio over 0.5 on a PA film), Dilated upper lobe vessels and pleural Effusions. Bilateral hilar lymphadenopathy with normal heart size suggests sarcoidosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7855990c-801c-5b0f-bbb4-4b5581f3c2e0', '05f52c1e-18ea-550a-870f-52bae669a090', 'A', 'Congestive (left ventricular) heart failure', true, 0),
  ('af1d08b3-e9b8-540e-9d74-b9784e786472', '05f52c1e-18ea-550a-870f-52bae669a090', 'B', 'COPD', false, 1),
  ('ba2832dd-7d57-5930-801c-08196b2eb585', '05f52c1e-18ea-550a-870f-52bae669a090', 'C', 'Pneumonia', false, 2),
  ('b80aae93-8b25-5e9e-98ed-55fc85063fa0', '05f52c1e-18ea-550a-870f-52bae669a090', 'D', 'Lung cancer', false, 3),
  ('a72fb44d-e518-5c60-a0d7-c4c029c76b16', '05f52c1e-18ea-550a-870f-52bae669a090', 'E', 'Sarcoidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c1838eb6-dfd8-57ff-99e8-c11c3fbe2fd5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 70 year old man with metastatic lung cancer is taking oral modified-release morphine 30 mg twice daily, which controls his pain well. He is now unable to swallow because he is drowsy, and the palliative care team plan to start a subcutaneous syringe driver. What is the SINGLE most appropriate equivalent subcutaneous morphine dose?', 'His total daily oral morphine dose is 60 mg. Subcutaneous morphine is about twice as potent as oral morphine, so divide the oral dose by 2, giving 30 mg over 24 hours by syringe driver. If converting to subcutaneous diamorphine instead, divide the oral morphine dose by 3. Breakthrough doses are usually one-sixth of the 24-hour dose.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e59aa5ec-4245-5f73-ab14-586c9456ed70', 'c1838eb6-dfd8-57ff-99e8-c11c3fbe2fd5', 'A', 'Morphine 10 mg over 24 hours', false, 0),
  ('49d04d99-c279-586e-a34d-65eebfef5440', 'c1838eb6-dfd8-57ff-99e8-c11c3fbe2fd5', 'B', 'Morphine 20 mg over 24 hours', false, 1),
  ('42d8451a-bacc-5354-a342-8d8ce0ed6932', 'c1838eb6-dfd8-57ff-99e8-c11c3fbe2fd5', 'C', 'Morphine 30 mg over 24 hours', true, 2),
  ('72d5cef6-4928-51f0-aef3-c9e99457a447', 'c1838eb6-dfd8-57ff-99e8-c11c3fbe2fd5', 'D', 'Morphine 60 mg over 24 hours', false, 3),
  ('5a599624-4da3-564d-85dd-881415b75597', 'c1838eb6-dfd8-57ff-99e8-c11c3fbe2fd5', 'E', 'Morphine 120 mg over 24 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('50e160fb-753e-58f7-aeb3-fb1c08282da9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 34 year old man has been taking co-codamol 30/500 regularly for 10 days for back pain after a lifting injury. He now complains of passing hard stools only every 3 days, with straining. He has no rectal bleeding, weight loss or abdominal pain, and he will need the analgesia for at least another week. Which of the following is the SINGLE most appropriate laxative?', 'Opioids reduce gut motility, so opioid-induced constipation is best treated with a stimulant laxative such as senna (with an osmotic laxative or a softener if needed). Bulk-forming laxatives such as ispaghula husk and methylcellulose should be avoided because they can worsen symptoms and cause obstruction when motility is reduced. Loperamide is an antidiarrhoeal. Enemas are kept for faecal impaction or failure of oral treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a4a20865-3596-5710-8a2e-898ef6cf652b', '50e160fb-753e-58f7-aeb3-fb1c08282da9', 'A', 'Phosphate enema', false, 0),
  ('26b2b2c5-2a5b-5568-9580-36c4b724a3c4', '50e160fb-753e-58f7-aeb3-fb1c08282da9', 'B', 'Loperamide', false, 1),
  ('e6096fad-3dd3-538f-bee7-11f8b7ebc8ea', '50e160fb-753e-58f7-aeb3-fb1c08282da9', 'C', 'Methylcellulose', false, 2),
  ('57168859-533f-5c8f-9d3c-11a6d8b30ff0', '50e160fb-753e-58f7-aeb3-fb1c08282da9', 'D', 'Senna', true, 3),
  ('a253f4b7-f73c-5e68-810e-4cfc9e31f97b', '50e160fb-753e-58f7-aeb3-fb1c08282da9', 'E', 'Ispaghula husk', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('36287ede-b6f8-57e7-8d8b-b9e126272959', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 79 year old woman is seen by her GP after three falls in a month. Each time she felt light-headed just after standing up from a chair. Her medications are amlodipine, doxazosin, furosemide, amitriptyline and omeprazole. Her lying blood pressure is 142/80 mmHg and her standing blood pressure at 3 minutes is 108/66 mmHg. ECG shows sinus rhythm. What is the SINGLE most appropriate next step?', 'A systolic drop of more than 20 mmHg on standing confirms orthostatic hypotension. Her symptoms are most likely caused by medication: the alpha-blocker doxazosin is a major culprit, and diuretics and tricyclics add to it. The first step is a structured medication review, stopping or reducing the drugs that cause it, starting with doxazosin. Fludrocortisone or midodrine are only considered if symptoms persist after reversible causes have been dealt with.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9fa4a6b2-4fbe-5d2d-8009-1e13631d67d2', '36287ede-b6f8-57e7-8d8b-b9e126272959', 'A', 'Start fludrocortisone', false, 0),
  ('16c50234-fbfb-507e-8187-7810c524690d', '36287ede-b6f8-57e7-8d8b-b9e126272959', 'B', 'Start midodrine', false, 1),
  ('183257fb-4259-59dd-9d36-e9cb40265cec', '36287ede-b6f8-57e7-8d8b-b9e126272959', 'C', 'Refer for a permanent pacemaker', false, 2),
  ('86ce957d-c345-5b34-baae-06b218e2334f', '36287ede-b6f8-57e7-8d8b-b9e126272959', 'D', 'Medication review and stop doxazosin', true, 3),
  ('df8e9281-a2e0-5f61-a696-6130e58d113c', '36287ede-b6f8-57e7-8d8b-b9e126272959', 'E', 'Arrange a CT scan of the head', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1c2fac7c-2de8-5a9b-9fa8-38200ae647ba', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 46 year old man with bipolar affective disorder has been stable on lithium for 6 years. Two weeks ago he started regular ibuprofen for a knee injury. He now presents with vomiting, diarrhoea, a coarse tremor, unsteadiness and confusion. He is afebrile and has no muscle rigidity. What is the SINGLE most likely diagnosis?', 'NSAIDs reduce renal lithium excretion and raise serum levels. ACE inhibitors, ARBs, thiazide diuretics and dehydration do the same. Toxicity typically causes GI upset, a coarse tremor (a fine tremor is normal at therapeutic levels), ataxia, confusion and, in severe cases, seizures. Check the serum lithium level urgently and stop lithium and the NSAID. Haemodialysis may be needed in severe toxicity. Neuroleptic malignant syndrome and serotonin syndrome usually cause fever and rigidity or clonus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('009c8dc9-178e-54bf-b65b-f8b89d380fbf', '1c2fac7c-2de8-5a9b-9fa8-38200ae647ba', 'A', 'Hypothyroidism', false, 0),
  ('75366d6c-553b-5e4f-9f06-da233bd60b89', '1c2fac7c-2de8-5a9b-9fa8-38200ae647ba', 'B', 'Lithium toxicity', true, 1),
  ('cbd18241-8bbd-5df1-9e93-a56156f334b9', '1c2fac7c-2de8-5a9b-9fa8-38200ae647ba', 'C', 'Hyponatraemia', false, 2),
  ('4e2b052c-1ac6-5cc7-8610-a272860effc6', '1c2fac7c-2de8-5a9b-9fa8-38200ae647ba', 'D', 'Serotonin syndrome', false, 3),
  ('491edb81-b588-5cd5-995e-ce5946c1b0db', '1c2fac7c-2de8-5a9b-9fa8-38200ae647ba', 'E', 'Neuroleptic malignant syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cbf760e4-67b0-5fc6-8059-7560da466e94', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 68 year old man on warfarin for atrial fibrillation attends the anticoagulation clinic. His INR is 8.4. He recently finished a course of clarithromycin. He has no bleeding, bruising, haematuria or melaena, and his observations are normal. What is the SINGLE most appropriate management?', 'With an INR above 8 and no bleeding, the BNF advises stopping warfarin and giving 1-5 mg of vitamin K by mouth (using the IV preparation orally). Repeat the dose if the INR is still high after 24 hours, and restart warfarin when the INR is below 5. IV vitamin K with prothrombin complex concentrate is for major bleeding. Clarithromycin inhibits warfarin metabolism and probably caused the high INR.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5a205b7-5bc8-5265-a111-838aafcf2b69', 'cbf760e4-67b0-5fc6-8059-7560da466e94', 'A', 'Omit one dose of warfarin only', false, 0),
  ('74697f4b-9f93-5a3e-beca-783bc59dbd36', 'cbf760e4-67b0-5fc6-8059-7560da466e94', 'B', 'Stop warfarin and give oral vitamin K (phytomenadione)', true, 1),
  ('29d9e18d-e629-5d27-a6cb-3b307821b224', 'cbf760e4-67b0-5fc6-8059-7560da466e94', 'C', 'Give IV vitamin K and prothrombin complex concentrate', false, 2),
  ('434f1cec-c5d0-5025-90c1-ec8e0cfac7ca', 'cbf760e4-67b0-5fc6-8059-7560da466e94', 'D', 'Give fresh frozen plasma', false, 3),
  ('ce19c0a5-2982-5eaf-b11b-20aaba76a394', 'cbf760e4-67b0-5fc6-8059-7560da466e94', 'E', 'Continue warfarin at a reduced dose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('15097872-00c1-537b-84fb-9574456917a6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'An 82 year old woman with atrial fibrillation on digoxin 250 micrograms daily has 4 days of nausea, vomiting, confusion and seeing yellow-tinged halos around lights. She recently started furosemide. Her potassium is 2.9 mmol/L, creatinine has risen, and her ECG shows a heart rate of 48 beats/minute. What is the SINGLE most likely diagnosis?', 'GI upset, confusion, yellow-green visual disturbance (xanthopsia) and bradyarrhythmias in an older person on digoxin suggest toxicity. Hypokalaemia from the new loop diuretic, and worsening kidney function, increase the risk. Management is to stop digoxin, correct potassium and check a digoxin level (6 hours after the dose). Digoxin-specific antibody fragments (DigiFab) are given for life-threatening arrhythmias or severe toxicity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bc34e0ef-b917-5d08-8094-4f9ca8d16e19', '15097872-00c1-537b-84fb-9574456917a6', 'A', 'Hyperkalaemia', false, 0),
  ('cfba34cf-6aff-5c54-b15c-6d3bfa98d2f3', '15097872-00c1-537b-84fb-9574456917a6', 'B', 'Hypothyroidism', false, 1),
  ('413e57c8-f27e-5521-8d95-ab174685ee83', '15097872-00c1-537b-84fb-9574456917a6', 'C', 'Digoxin toxicity', true, 2),
  ('b259df7e-9687-5a56-b572-3e4ee02827fc', '15097872-00c1-537b-84fb-9574456917a6', 'D', 'Acute angle-closure glaucoma', false, 3),
  ('deea6136-a1c6-519c-99f2-8a57ca9671de', '15097872-00c1-537b-84fb-9574456917a6', 'E', 'Viral gastroenteritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f22b0fa0-ef88-5e6b-b122-5f70ec9f81eb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 66 year old man takes simvastatin 40 mg daily. He is prescribed a 7-day course of clarithromycin for a chest infection. Five days later he has generalised muscle aches and weakness and dark urine. His CK is 42,000 U/L. What is the SINGLE most likely mechanism?', 'Simvastatin is metabolised by CYP3A4. Macrolides (clarithromycin, erythromycin) strongly inhibit CYP3A4 and raise statin levels, risking myopathy and rhabdomyolysis. The statin should be paused during macrolide courses. Other CYP3A4 inhibitors include azole antifungals, HIV protease inhibitors and grapefruit juice. Treatment of rhabdomyolysis is aggressive IV fluids and monitoring for AKI and hyperkalaemia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb72e8df-cb2b-559b-851b-8e9bb90228be', 'f22b0fa0-ef88-5e6b-b122-5f70ec9f81eb', 'A', 'An allergic reaction to clarithromycin', false, 0),
  ('23f9a17f-ddba-53c2-8642-dc88c48f0dd4', 'f22b0fa0-ef88-5e6b-b122-5f70ec9f81eb', 'B', 'Clarithromycin induces CYP3A4, reducing simvastatin levels', false, 1),
  ('379b8217-6a75-5ed2-8a41-271b9d9e1932', 'f22b0fa0-ef88-5e6b-b122-5f70ec9f81eb', 'C', 'Simvastatin reduces clarithromycin absorption', false, 2),
  ('d40c1c6f-ddd5-5120-8b68-50d6c11ffead', 'f22b0fa0-ef88-5e6b-b122-5f70ec9f81eb', 'D', 'Viral myositis unrelated to the medication', false, 3),
  ('0de07b35-66fb-5118-bac4-7c12baf8cc81', 'f22b0fa0-ef88-5e6b-b122-5f70ec9f81eb', 'E', 'Clarithromycin inhibits CYP3A4, raising simvastatin levels and causing rhabdomyolysis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6dd19231-baf1-5359-b022-0cadbf240eff', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 58 year old woman with rheumatoid arthritis has been taking methotrexate 15 mg once weekly for 2 years. She is given a prescription for trimethoprim for a UTI. A week later she has mouth ulcers, a sore throat and fever. Her white cell count is 0.9 x 10^9/L. What is the SINGLE most likely cause?', 'Trimethoprim (and co-trimoxazole) is a folate antagonist and reduces methotrexate excretion, which can cause severe or fatal bone marrow suppression. This combination should be avoided. Methotrexate patients should report sore throat, fever, mouth ulcers or bruising urgently. Neutropenic sepsis needs urgent IV antibiotics. Folinic acid rescue is given for methotrexate toxicity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('80598517-14ae-53f0-ab9a-4cfeb7300419', '6dd19231-baf1-5359-b022-0cadbf240eff', 'A', 'Drug-induced lupus', false, 0),
  ('0ffcc6b9-0ee9-5542-addd-0bd02ac12bec', '6dd19231-baf1-5359-b022-0cadbf240eff', 'B', 'Viral pharyngitis', false, 1),
  ('9af9b358-da54-57ed-acfe-6b4ce1f59992', '6dd19231-baf1-5359-b022-0cadbf240eff', 'C', 'Rheumatoid arthritis flare', false, 2),
  ('3909a0b5-3d2c-5fe2-b99d-18b74511b72c', '6dd19231-baf1-5359-b022-0cadbf240eff', 'D', 'Agranulocytosis from carbimazole', false, 3),
  ('4a1b3518-f7e3-541c-aabf-565b059d5e69', '6dd19231-baf1-5359-b022-0cadbf240eff', 'E', 'Bone marrow suppression from a methotrexate-trimethoprim interaction', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04c2466c-28eb-552b-8445-d9d398916497', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 70 year old man is on IV gentamicin for pyelonephritis. On day 4 he reports ringing in his ears and difficulty with balance. His creatinine has risen from 90 to 160 micromol/L. What is the SINGLE most appropriate action?', 'Aminoglycosides such as gentamicin are nephrotoxic and ototoxic (vestibular and cochlear), and ototoxicity may be irreversible. Risk increases with high trough levels, longer courses, kidney impairment, older age and interacting drugs (loop diuretics, vancomycin). Levels must be monitored with dose adjustment by protocol. With AKI and ototoxic symptoms, gentamicin should be stopped and an alternative chosen with microbiology advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ffb592e2-8129-584e-934d-d169c973583c', '04c2466c-28eb-552b-8445-d9d398916497', 'A', 'Continue the same dose and recheck in a week', false, 0),
  ('60140790-cbab-5de3-b421-f810dd96df5a', '04c2466c-28eb-552b-8445-d9d398916497', 'B', 'Add IV vancomycin', false, 1),
  ('b59d63ef-daa9-5dc9-b3b6-aa77e5cc45d2', '04c2466c-28eb-552b-8445-d9d398916497', 'C', 'Add IV furosemide', false, 2),
  ('cad1e9da-404f-55f0-b1d1-3d2767c80a1f', '04c2466c-28eb-552b-8445-d9d398916497', 'D', 'Stop or withhold gentamicin, check levels and seek microbiology advice', true, 3),
  ('14b86467-530b-5a3c-a223-c67c6f792ec2', '04c2466c-28eb-552b-8445-d9d398916497', 'E', 'Increase the gentamicin dose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c229577-b58b-5efb-afa3-69c5970603a9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 45 year old woman has taken oral prednisolone 10 mg daily for 6 months for an inflammatory condition. She develops gastroenteritis with vomiting and diarrhoea and asks what to do about her steroid. What is the SINGLE most appropriate advice?', 'Long-term steroids (more than 3 weeks, or 5 mg or more of prednisolone for 4 weeks or longer) suppress the hypothalamic-pituitary-adrenal axis. Stopping suddenly or failing to increase the dose during illness can cause an adrenal crisis. Sick day rules are to double the dose during illness with fever and to use emergency IM hydrocortisone or attend hospital if vomiting. Patients should carry a steroid emergency card.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d5ab6405-a5b6-512c-812c-d10bfd975ced', '0c229577-b58b-5efb-afa3-69c5970603a9', 'A', 'Switch to inhaled steroids', false, 0),
  ('3c5260bf-b4d0-5ebe-94d7-2d03cd2ee8ba', '0c229577-b58b-5efb-afa3-69c5970603a9', 'B', 'Stop prednisolone until she recovers', false, 1),
  ('518bc2ab-cfb8-5a9f-a855-349e81ec0e58', '0c229577-b58b-5efb-afa3-69c5970603a9', 'C', 'Halve her prednisolone dose', false, 2),
  ('728dec37-429f-5272-94a9-99dbfa6464c7', '0c229577-b58b-5efb-afa3-69c5970603a9', 'D', 'Continue the same dose with no changes', false, 3),
  ('8ff08972-bf7d-5472-9267-a850f85fda4b', '0c229577-b58b-5efb-afa3-69c5970603a9', 'E', 'Double her prednisolone dose while unwell (sick day rules), and seek urgent help if vomiting prevents taking it', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ad6b9d3c-4023-52a2-aa61-af187c9fff5d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 26 year old woman with epilepsy who takes carbamazepine wants contraception. She would like a reliable long-acting method and has no other medical problems. What is the SINGLE most appropriate choice?', 'Carbamazepine is a potent enzyme inducer (CYP3A4) that reduces the effectiveness of hormonal contraceptives metabolised by the liver, including the COCP, POP and implant. FSRH guidance recommends contraception that is not affected by enzyme inducers: the copper IUD, the levonorgestrel IUS or the progestogen-only injection. Other enzyme inducers include phenytoin, rifampicin and St John''s wort.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('95579024-2a6f-5dca-bae3-c66515baac9b', 'ad6b9d3c-4023-52a2-aa61-af187c9fff5d', 'A', 'Etonogestrel implant', false, 0),
  ('d7ebb351-a440-5757-bb81-41648e3d9376', 'ad6b9d3c-4023-52a2-aa61-af187c9fff5d', 'B', 'Combined oral contraceptive pill', false, 1),
  ('7563bf7a-f8bb-5764-8b43-f6f8d263a456', 'ad6b9d3c-4023-52a2-aa61-af187c9fff5d', 'C', 'Copper intrauterine device or levonorgestrel intrauterine system', true, 2),
  ('1db786e2-27f1-560b-9b5a-780ed6fe3d1a', 'ad6b9d3c-4023-52a2-aa61-af187c9fff5d', 'D', 'Progestogen-only pill', false, 3),
  ('194d7ccc-4175-5391-86ee-229cfa2f33df', 'ad6b9d3c-4023-52a2-aa61-af187c9fff5d', 'E', 'Oral emergency contraception as needed', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04815bc4-7c88-553c-a9bc-33d52a7ddaa0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 74 year old woman with AF on warfarin (INR target 2-3) is started on a new drug and her INR rises to 6.5 a week later. Which drug is MOST likely responsible?', 'Enzyme inhibitors raise the INR on warfarin: azole antifungals (fluconazole), macrolides, ciprofloxacin, metronidazole, amiodarone, SSRIs, omeprazole, cranberry juice and alcohol binges. Enzyme inducers lower the INR: rifampicin, carbamazepine, phenytoin, St John''s wort and chronic alcohol. The INR should be monitored closely when interacting drugs are started or stopped.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1b4da3eb-9e86-5409-811b-38448338ce19', '04815bc4-7c88-553c-a9bc-33d52a7ddaa0', 'A', 'Carbamazepine', false, 0),
  ('68f2746b-ddba-51fc-89c9-fff7fb2c188d', '04815bc4-7c88-553c-a9bc-33d52a7ddaa0', 'B', 'St John''s wort', false, 1),
  ('0616fa7e-8fa9-5e2c-9965-4faa348e74d1', '04815bc4-7c88-553c-a9bc-33d52a7ddaa0', 'C', 'Fluconazole', true, 2),
  ('a4e0a32e-2c2c-5997-9135-8e9eb3d2b396', '04815bc4-7c88-553c-a9bc-33d52a7ddaa0', 'D', 'Rifampicin', false, 3),
  ('6c0d7fdb-1360-5e2d-bb95-2f47de32d3e7', '04815bc4-7c88-553c-a9bc-33d52a7ddaa0', 'E', 'Phenytoin (long-term)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d7554837-238b-51df-94a0-5d310aff02b8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 68 year old man with heart failure takes ramipril and spironolactone. He is prescribed trimethoprim for a UTI. A week later his potassium is 6.8 mmol/L. What is the SINGLE most likely mechanism?', 'Hyperkalaemia risk is increased by ACE inhibitors and ARBs, potassium-sparing diuretics (spironolactone, amiloride), trimethoprim (which blocks distal tubular sodium channels), NSAIDs, heparin and CKD. Combinations need caution and monitoring. Severe hyperkalaemia with ECG changes needs IV calcium, insulin-dextrose and removal of the causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6c9b7be4-f981-53e2-b419-77bdec93eee5', 'd7554837-238b-51df-94a0-5d310aff02b8', 'A', 'Insulin deficiency', false, 0),
  ('af518e5a-b3c6-5ae3-9e93-ecb13c6da2b2', 'd7554837-238b-51df-94a0-5d310aff02b8', 'B', 'Combined potassium-raising effects of ACE inhibitor, spironolactone and trimethoprim (which blocks ENaC like amiloride)', true, 1),
  ('c0054238-cd99-5f45-82df-49a8a7594ee2', 'd7554837-238b-51df-94a0-5d310aff02b8', 'C', 'Increased potassium in the diet only', false, 2),
  ('212106ea-20ca-5a5c-9282-f766913d6dd3', 'd7554837-238b-51df-94a0-5d310aff02b8', 'D', 'Lab error', false, 3),
  ('b67b6720-a369-5389-84ea-4017b2a70d17', 'd7554837-238b-51df-94a0-5d310aff02b8', 'E', 'Trimethoprim-induced vomiting', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('812fcc1a-41f3-5d57-96f2-0bd2814815ba', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 64 year old man starts amiodarone for atrial fibrillation. Which baseline and monitoring tests are MOST important?', 'Amiodarone has many side effects: hypo- or hyperthyroidism (it contains iodine), pulmonary fibrosis, hepatotoxicity, photosensitivity and blue-grey skin, corneal deposits, peripheral neuropathy, QT prolongation and bradycardia. TFTs and LFTs are checked at baseline and every 6 months. A chest X-ray is done at baseline. It interacts with warfarin, digoxin and statins.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5729aa84-4126-561e-9ce7-8184277e62a3', '812fcc1a-41f3-5d57-96f2-0bd2814815ba', 'A', 'Thyroid function, liver function and chest X-ray (with lung function), plus ECG', true, 0),
  ('c3ba6d97-5f5f-5ed1-b1c0-bff74b37d77a', '812fcc1a-41f3-5d57-96f2-0bd2814815ba', 'B', 'Amylase', false, 1),
  ('5d7ba2b4-e091-5aed-8b38-cac8d31ea1ae', '812fcc1a-41f3-5d57-96f2-0bd2814815ba', 'C', 'Creatine kinase', false, 2),
  ('429fde79-58ec-5a24-b1aa-51045a7d1b07', '812fcc1a-41f3-5d57-96f2-0bd2814815ba', 'D', 'Full blood count only', false, 3),
  ('427534d4-ed09-52da-bfb0-2826f7f9bda2', '812fcc1a-41f3-5d57-96f2-0bd2814815ba', 'E', 'Renal function only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('07c1c905-4ed3-5a3f-b8d2-06e3edbadbd8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 50 year old man takes allopurinol for gout. He has had a lung transplant and is started on azathioprine. Which interaction is MOST important?', 'Azathioprine is metabolised to 6-mercaptopurine, which is broken down by xanthine oxidase. Allopurinol inhibits xanthine oxidase, causing severe myelosuppression unless the azathioprine dose is reduced to about a quarter, or an alternative is used. TPMT activity should be checked before starting azathioprine, because low activity increases the risk of toxicity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8f58db73-4313-5365-92f6-7d2ffb408d23', '07c1c905-4ed3-5a3f-b8d2-06e3edbadbd8', 'A', 'No interaction', false, 0),
  ('30e802c8-6bc3-566f-9268-5283c88eeff0', '07c1c905-4ed3-5a3f-b8d2-06e3edbadbd8', 'B', 'Azathioprine increases uric acid', false, 1),
  ('38e761a3-06d4-5294-a497-d5b36cbea4bb', '07c1c905-4ed3-5a3f-b8d2-06e3edbadbd8', 'C', 'Both cause hyperkalaemia', false, 2),
  ('1679cf38-13f6-5042-b478-406b6910b9d3', '07c1c905-4ed3-5a3f-b8d2-06e3edbadbd8', 'D', 'Allopurinol reduces azathioprine levels', false, 3),
  ('dabe5984-2c29-553d-90cd-091d682cbe70', '07c1c905-4ed3-5a3f-b8d2-06e3edbadbd8', 'E', 'Allopurinol inhibits xanthine oxidase, increasing azathioprine toxicity (bone marrow suppression)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('97c3f50c-bad4-5d60-8d9d-75d93049c346', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 26 year old woman has asthma and is prescribed a drug for migraine prophylaxis. Two days later she has severe bronchospasm. Which drug is MOST likely responsible?', 'Non-selective beta-blockers (propranolol, timolol eye drops) can cause life-threatening bronchospasm in asthma and should be avoided. Cardioselective beta-blockers (such as bisoprolol) are used with caution in mild asthma if clearly indicated. Other drugs that can worsen asthma include NSAIDs and aspirin in aspirin-exacerbated respiratory disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
