  ('3b7f72a2-3c33-55e2-b742-97c7fb5a3c39', '97c3f50c-bad4-5d60-8d9d-75d93049c346', 'A', 'Propranolol', true, 0),
  ('10b56e8a-5518-5a3b-8bed-8e8a7d700cb7', '97c3f50c-bad4-5d60-8d9d-75d93049c346', 'B', 'Amitriptyline', false, 1),
  ('8f6eeac1-5d0e-554a-9eaf-f4de9eb023d3', '97c3f50c-bad4-5d60-8d9d-75d93049c346', 'C', 'Riboflavin', false, 2),
  ('3f0f6be0-7129-596b-a904-de3b21608ec4', '97c3f50c-bad4-5d60-8d9d-75d93049c346', 'D', 'Topiramate', false, 3),
  ('5e9c3970-0216-5a91-978f-a46e0697550f', '97c3f50c-bad4-5d60-8d9d-75d93049c346', 'E', 'Candesartan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dc5760d4-2cd1-536b-8e66-b246f6195841', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 70 year old woman on long-term omeprazole has fatigue and muscle cramps and had a seizure. Which electrolyte abnormality is MOST associated with long-term PPI use?', 'Long-term PPIs can cause hypomagnesaemia (which can also cause hypocalcaemia and hypokalaemia), as well as C. difficile infection, fractures, B12 deficiency and microscopic colitis. Magnesium should be checked in long-term users with symptoms or those also on diuretics or digoxin. Deprescribing should be considered when PPIs are no longer needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
