  ('99578b48-e875-53ca-87b2-b4e45e1696f2', 'dc5760d4-2cd1-536b-8e66-b246f6195841', 'A', 'Hyperkalaemia', false, 0),
  ('859d9a00-e6f9-50b1-afdb-1babc6298c4e', 'dc5760d4-2cd1-536b-8e66-b246f6195841', 'B', 'Hypernatraemia', false, 1),
  ('d6fad2d8-1a17-5f8c-9bdf-87338970f8e7', 'dc5760d4-2cd1-536b-8e66-b246f6195841', 'C', 'Hyperphosphataemia', false, 2),
  ('0eec2b53-60ef-592f-9c91-e3737ea8853c', 'dc5760d4-2cd1-536b-8e66-b246f6195841', 'D', 'Hypercalcaemia', false, 3),
