insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1544f06f-aa25-5ccf-8f35-0cf62b359c87', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 65 year old man takes 4 g of paracetamol daily. He weighs 42 kg and has chronic alcohol use. What is the SINGLE most appropriate advice about paracetamol dosing?', 'The usual adult paracetamol dose is 1 g four times daily (maximum 4 g/day). The dose should be reduced (for example to 15 mg/kg per dose, maximum 3 g/day) in adults under 50 kg or with risk factors for hepatotoxicity: chronic alcohol use, malnutrition, liver disease or enzyme-inducing drugs. IV paracetamol is weight-based in adults under 50 kg.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('aedf59e1-9569-518e-86cb-485b128ca739', '1544f06f-aa25-5ccf-8f35-0cf62b359c87', 'A', 'Paracetamol is contraindicated in all older people', false, 0),
  ('b673c285-d686-57b4-b75f-c3b403742615', '1544f06f-aa25-5ccf-8f35-0cf62b359c87', 'B', 'Reduce the dose (e.g. maximum 3 g/day or 15 mg/kg per dose) because of low weight and hepatotoxicity risk factors', true, 1),
  ('a7bd51a0-a257-5f66-b353-23c6ce79905b', '1544f06f-aa25-5ccf-8f35-0cf62b359c87', 'C', 'Switch to aspirin 4 g daily', false, 2),
  ('7517f661-fdab-516c-a22d-140434075c49', '1544f06f-aa25-5ccf-8f35-0cf62b359c87', 'D', 'Increase to 6 g daily', false, 3),
  ('ed1255f4-2061-5cd7-8328-334f54f3627c', '1544f06f-aa25-5ccf-8f35-0cf62b359c87', 'E', 'Continue 4 g daily', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6c7254f1-35b5-5c64-8ca2-9ebad9ab4664', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 30 year old woman is planning pregnancy and takes several medications. Which drug MUST be stopped before conception because of teratogenicity?', 'Isotretinoin is highly teratogenic. Women must follow a Pregnancy Prevention Programme and avoid pregnancy for 1 month after stopping. Other major teratogens include valproate (neural tube defects, neurodevelopmental problems), warfarin, ACE inhibitors and ARBs, methotrexate, lithium, mycophenolate and tetracyclines. Levothyroxine and insulin should be continued, with dose adjustment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
