  ('573825ce-33f5-5031-9652-841ae603c0e3', '6c7254f1-35b5-5c64-8ca2-9ebad9ab4664', 'B', 'Insulin', false, 1),
  ('ed020804-4f41-53ce-8a11-06253cfc5323', '6c7254f1-35b5-5c64-8ca2-9ebad9ab4664', 'C', 'Levothyroxine', false, 2),
  ('7866345c-97aa-51f2-9458-add09245c44d', '6c7254f1-35b5-5c64-8ca2-9ebad9ab4664', 'D', 'Isotretinoin', true, 3),
  ('dde0ef6e-5c10-544c-8fc0-7223c87e5dfd', '6c7254f1-35b5-5c64-8ca2-9ebad9ab4664', 'E', 'Labetalol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3c5ba4e1-3f97-5f82-af9e-56ac2cca1d95', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 60 year old man has a sore, red, swollen tongue and lips and a hoarse voice 3 weeks after starting a new antihypertensive. He has no rash or itch. Which drug is MOST likely responsible?', 'ACE inhibitors can cause angioedema (bradykinin-mediated), even after months or years of use. It is more common in people of Black African or African-Caribbean origin. It does not respond well to antihistamines or adrenaline, and the airway may need securing. The ACE inhibitor must be stopped permanently. ARBs carry a small risk of cross-reactivity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
