  ('1890e861-88c4-5d7a-848b-3e1ef24e5be7', '3c5ba4e1-3f97-5f82-af9e-56ac2cca1d95', 'A', 'Bendroflumethiazide', false, 0),
  ('d3de8329-53d5-5441-84cb-60f7046b43bb', '3c5ba4e1-3f97-5f82-af9e-56ac2cca1d95', 'B', 'Bisoprolol', false, 1),
  ('c2944d50-32ba-5b5d-94bd-a336d8f16a03', '3c5ba4e1-3f97-5f82-af9e-56ac2cca1d95', 'C', 'Ramipril', true, 2),
  ('d40a1b2e-f2a9-5c51-bd3d-129dc9039c5b', '3c5ba4e1-3f97-5f82-af9e-56ac2cca1d95', 'D', 'Amlodipine', false, 3),
  ('d8d07e7d-6709-5652-85fa-db14fc7e5e23', '3c5ba4e1-3f97-5f82-af9e-56ac2cca1d95', 'E', 'Doxazosin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('366c1a3e-e431-584a-8581-f2dc0e283368', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 76 year old woman has a fall and her lying-standing BP shows a large drop. She recently started a medicine for urinary symptoms. Which drug is MOST likely responsible?', 'Alpha-blockers (doxazosin, tamsulosin, terazosin) cause vasodilation and orthostatic hypotension, especially after the first dose and in older people. Other common causes of postural hypotension include diuretics, vasodilators, antihypertensives, nitrates, tricyclics, antipsychotics and levodopa. Medication review is key in falls assessment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
