  ('62497ebb-2170-52eb-87f9-f9bf1ee12bcf', '366c1a3e-e431-584a-8581-f2dc0e283368', 'A', 'Desmopressin', false, 0),
  ('b0de0b8c-384f-51fc-a638-b859f72ae921', '366c1a3e-e431-584a-8581-f2dc0e283368', 'B', 'Doxazosin', true, 1),
  ('b4d321f4-c396-5910-b86a-66514e4fc21b', '366c1a3e-e431-584a-8581-f2dc0e283368', 'C', 'Trimethoprim', false, 2),
  ('77cff0c6-4801-5c9e-84be-9afa3dd7d8bb', '366c1a3e-e431-584a-8581-f2dc0e283368', 'D', 'Mirabegron', false, 3),
