insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4ba6e354-e49f-524c-829c-272382a9e33c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 30 year old man with epilepsy on phenytoin has nystagmus, ataxia, slurred speech and confusion. He was recently started on another medicine. Phenytoin levels are high. Which drug is MOST likely responsible?', 'Phenytoin has a narrow therapeutic index and non-linear (saturable) kinetics, so small dose changes or enzyme inhibition can cause a large rise in levels and toxicity (nystagmus, ataxia, dysarthria, confusion). Enzyme inhibitors include azoles, isoniazid, amiodarone and sodium valproate. Long-term side effects include gingival hyperplasia, hirsutism and osteomalacia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5ec885f-9563-5cf7-9c64-21ac6ae8302b', '4ba6e354-e49f-524c-829c-272382a9e33c', 'A', 'Phenobarbital', false, 0),
  ('7561782e-6aff-5ef3-a8f4-76ef663fba54', '4ba6e354-e49f-524c-829c-272382a9e33c', 'B', 'Carbamazepine', false, 1),
  ('edc71c30-e980-5cbb-bc8f-5bb94946576b', '4ba6e354-e49f-524c-829c-272382a9e33c', 'C', 'St John''s wort', false, 2),
  ('d0f2c320-b601-59be-ade4-f80a37cdfc9e', '4ba6e354-e49f-524c-829c-272382a9e33c', 'D', 'Rifampicin', false, 3),
  ('1900bb13-c6b4-560c-871d-7290adafb1ae', '4ba6e354-e49f-524c-829c-272382a9e33c', 'E', 'Fluconazole (enzyme inhibitor)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('81c9d092-50b4-51ca-8646-94251d686060', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 55 year old woman has been on prednisolone 30 mg daily for 4 months for polymyositis. Which preventive measure is MOST important for her bones?', 'Long-term glucocorticoids (7.5 mg prednisolone daily or more for 3 months or longer) cause rapid bone loss. Bone protection (an oral bisphosphonate plus calcium and vitamin D) should be started early in those at high risk, guided by FRAX or the NOGG guidelines. Other side effects include diabetes, hypertension, infection, cataracts, peptic ulcer, myopathy, mood change and adrenal suppression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
