  ('c65ead08-a6b2-53ce-b83b-ee2e7206aaad', '81c9d092-50b4-51ca-8646-94251d686060', 'A', 'Hormone therapy for all', false, 0),
  ('22671e1b-4d80-5a15-b9f5-711de207661b', '81c9d092-50b4-51ca-8646-94251d686060', 'B', 'No preventive measures', false, 1),
  ('38eda905-27f6-576b-9783-bcc2d415c77a', '81c9d092-50b4-51ca-8646-94251d686060', 'C', 'Iron supplements', false, 2),
  ('cfe7fac7-bf86-5cb5-8087-9f6a95fbdbd7', '81c9d092-50b4-51ca-8646-94251d686060', 'D', 'Bone protection with a bisphosphonate plus calcium and vitamin D', true, 3),
  ('762a1be5-9e80-5c4a-9b9e-341041ceca07', '81c9d092-50b4-51ca-8646-94251d686060', 'E', 'Vitamin C', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 45 year old woman with chronic back pain is taking 30 mg of oral morphine twice daily. She has severe constipation. Which laxative combination is MOST appropriate?', 'Opioid-induced constipation should be prevented by co-prescribing laxatives. A stimulant (senna or bisacodyl) plus a softener or osmotic laxative (docusate, macrogol) is used. Bulk-forming laxatives should be avoided. If this fails, a peripherally acting mu-opioid receptor antagonist (methylnaltrexone or naloxegol) can be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('292a1578-7338-5fd0-8ae9-3b454934b8b0', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'A', 'Rectal enemas daily', false, 0),
  ('365fe4c1-3ae6-52e3-ba2c-16f7f5322425', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'B', 'Stop all opioids immediately', false, 1),
  ('4041f883-5fab-59a0-8f18-2169da519795', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'C', 'Stimulant laxative (senna) plus a softener or osmotic laxative', true, 2),
  ('fa6afcfe-09fd-5923-948c-fc7cc9d1830b', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'D', 'Bulk-forming laxative only', false, 3),
  ('01ed7706-984a-5c65-a084-c4110c2699ba', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'E', 'Loperamide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('57cff6df-8958-5196-ad14-4b5693d49b4c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 32 year old woman takes the combined oral contraceptive pill. She is starting rifampicin for latent TB. What is the SINGLE most appropriate contraceptive advice?', 'Rifampicin is a potent enzyme inducer that makes most hormonal contraceptives ineffective (COCP, POP, implant, patch, ring). Reliable options are the copper IUD, LNG-IUS or DMPA injection. Contraceptive precautions continue for 28 days after stopping the enzyme inducer. Rifampicin also lowers levels of warfarin and many other drugs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a68747a4-0bf5-550e-8866-845a088de955', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'A', 'Continue the COCP as normal', false, 0),
  ('a5916d48-d310-5d70-bdd7-c7def2d81e01', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'B', 'Use the implant', false, 1),
  ('932b22f7-ec90-5bac-acb4-fc3da22c1f39', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'C', 'Use a non-hormonal method (copper IUD) or a method unaffected by enzyme inducers, during treatment and for 28 days after', true, 2),
  ('30349c3e-3981-52d2-9bd9-d9a1bea57790', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'D', 'Switch to the progestogen-only pill', false, 3),
  ('1b876851-3d9b-5556-ab01-e192f8e4dbcb', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'E', 'Double the COCP dose for 3 days', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 72 year old man takes digoxin and has developed nausea and visual disturbance. His eGFR has fallen recently. Which electrolyte disturbance would MOST increase his risk of digoxin toxicity?', 'Digoxin competes with potassium at the Na+/K+-ATPase, so hypokalaemia increases toxicity. Hypomagnesaemia and hypercalcaemia also increase toxicity. Reduced renal function causes accumulation because digoxin is cleared by the kidneys. Drugs that increase digoxin levels include amiodarone, verapamil and macrolides. Severe toxicity is treated with DigiFab.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a841cb9-d065-5994-ac59-17b88a554dda', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'A', 'Hyperkalaemia', false, 0),
  ('934be068-3b61-57ae-a2e2-9ea3426047d2', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'B', 'Hypercalcaemia only', false, 1),
  ('4b98b056-4bca-567c-b9b2-c55d0f4e642d', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'C', 'Hypokalaemia', true, 2),
  ('284f1757-4080-5d1f-8f07-02d9b9edea61', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'D', 'Hypermagnesaemia', false, 3),
  ('a6ca31f0-46f3-564d-9359-58046d8a8675', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'E', 'Hyponatraemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c462591-7190-5c60-b0b8-cce196c753a9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 70 year old man with Parkinson''s disease is admitted with confusion and is nil by mouth. His usual medication is co-careldopa. What is the SINGLE most appropriate action?', 'Omitting or delaying Parkinson''s medication can cause severe rigidity, inability to swallow, aspiration and neuroleptic malignant-like syndrome. Doses must be given on time. If the patient cannot swallow, options include NG administration or a transdermal rotigotine patch. Dopamine antagonists (haloperidol, metoclopramide, prochlorperazine) must be avoided. Domperidone is a safer antiemetic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('933526fb-313b-57ca-9763-37a61b99265d', '2c462591-7190-5c60-b0b8-cce196c753a9', 'A', 'Give metoclopramide for nausea', false, 0),
  ('afe0698b-85ba-5af5-af76-1d38f8adacc4', '2c462591-7190-5c60-b0b8-cce196c753a9', 'B', 'Withhold all Parkinson''s medication until he can swallow', false, 1),
  ('e57e6c33-88d7-524a-8bbb-0cdae10a6156', '2c462591-7190-5c60-b0b8-cce196c753a9', 'C', 'Give haloperidol for confusion', false, 2),
  ('a75b9523-f662-5c29-809d-eeab7edda993', '2c462591-7190-5c60-b0b8-cce196c753a9', 'D', 'Stop co-careldopa permanently', false, 3),
  ('ffa93a98-7d8b-5197-9ec4-98c27534bc30', '2c462591-7190-5c60-b0b8-cce196c753a9', 'E', 'Ensure Parkinson''s medication is given on time (e.g. via nasogastric tube or a rotigotine patch if unable to swallow)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 26 year old man with depression has taken a large overdose of citalopram. His ECG shows a QTc of 560 ms. What is the SINGLE most important concern?', 'Citalopram and escitalopram cause dose-dependent QT prolongation, and overdose can lead to torsades de pointes. Other QT-prolonging drugs include antipsychotics, macrolides, quinolones, ondansetron, methadone and class III antiarrhythmics. Torsades is treated with IV magnesium sulfate. Electrolytes (K, Mg, Ca) should be corrected.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('65d0cbb9-c55c-5a0d-9e3c-6ec6402b9ef4', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'A', 'Renal failure', false, 0),
  ('9b89f3bd-e081-5240-bd4e-3ce96488f079', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'B', 'Hepatotoxicity', false, 1),
  ('84a6d2a0-e8de-5a91-8738-e4069fd48c58', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'C', 'Hypoglycaemia', false, 2),
  ('8b8dc26b-8106-5114-855f-40b93b594da1', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'D', 'Torsades de pointes (polymorphic VT) and sudden cardiac death', true, 3),
  ('314fe595-5d55-5065-8887-b30841d663eb', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'E', 'Bone marrow suppression', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('07a8a90e-6376-54cf-be5e-0efb0706df74', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 72 year old woman taking methotrexate weekly for rheumatoid arthritis attends for routine monitoring. Which set of blood tests is MOST important?', 'Methotrexate monitoring (FBC, U&E, LFT) is done every 2 weeks initially, then every 3 months once stable. Side effects include myelosuppression, hepatotoxicity, pneumonitis, mucositis and teratogenicity. It is taken once weekly with folic acid on a different day. Trimethoprim and NSAIDs increase toxicity. Prescribing errors (daily instead of weekly) have caused deaths.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
