  ('5b9a5d5d-8ed0-5175-9c54-de5eee39aa23', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'A', 'Vitamin D only', false, 0),
  ('625001a6-26a6-5cd1-bbc8-49e5a7780090', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'B', 'Thyroid function and HbA1c', false, 1),
  ('b566a121-1cef-567f-9150-f4dafdd9b89c', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'C', 'Lipids only', false, 2),
  ('a2f08d62-214b-5345-988d-479bf18a0b82', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'D', 'Amylase and lipase', false, 3),
  ('68bfd2fa-c011-5969-9d99-0598db25c53c', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'E', 'Full blood count, renal function and liver function tests', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dbf935ac-8bc9-58f5-94f0-548790e7c983', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 30 year old woman with known G6PD deficiency has a UTI. Which antibiotic should be AVOIDED?', 'In G6PD deficiency, drugs that cause oxidative stress can trigger haemolysis: nitrofurantoin, quinolones (ciprofloxacin), sulfonamides (co-trimoxazole), dapsone, primaquine and high-dose aspirin. Cephalosporins, penicillins and fosfomycin are generally safe. Patients should know which drugs to avoid.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
