  ('dc61b705-60f9-50c1-8448-38e39c04b30e', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'A', 'Cefalexin', false, 0),
  ('7fd2b78c-b8cb-5f52-b457-aca1f76cfd0d', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'B', 'Pivmecillinam', false, 1),
  ('967ac291-87c7-5a74-be0d-700f10d9c39e', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'C', 'Amoxicillin (if sensitive)', false, 2),
  ('6dc89973-0b44-5b93-83f3-4017fc21225d', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'D', 'Nitrofurantoin', true, 3),
  ('0c7e010f-2e8e-5c41-9c17-d25d5417c237', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'E', 'Fosfomycin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 64 year old man with CKD (eGFR 22 mL/min/1.73m2) and type 2 diabetes is taking metformin 1 g twice daily. What is the SINGLE most appropriate action?', 'Metformin is contraindicated with an eGFR under 30 because of the risk of lactic acidosis, and the dose should be reviewed (usually halved) at an eGFR under 45. It should be paused during acute illness with dehydration or AKI (sick day rules) and around iodinated contrast in at-risk patients. Many diabetes drugs need dose adjustment in CKD.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c4221ca2-f621-5827-bf29-8b3a967e1483', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'A', 'Stop metformin because eGFR is below 30', true, 0),
  ('8eb799b8-ae73-591a-a2c8-6773cec02f08', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'B', 'Continue at the same dose', false, 1),
  ('eb33c6d9-052e-5f4e-84e7-74a4b5aaf7df', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'C', 'Increase metformin', false, 2),
  ('f8f60f83-1271-5ff3-9227-8a1222ea47b5', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'D', 'Switch to IV insulin', false, 3),
  ('245c3016-d943-5824-a72d-c9fc19acc43a', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'E', 'Add gliclazide and continue metformin unchanged', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8722c344-58c6-509f-af1d-f5f53688437c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 22 year old man with acne is prescribed doxycycline. Which advice is MOST important?', 'Tetracyclines can cause oesophageal ulceration, so they are taken upright with water. They cause photosensitivity. Absorption is reduced by milk, antacids, iron, calcium and zinc. Tetracyclines are contraindicated in pregnancy, breastfeeding and children under 12, because they stain teeth and affect bone growth.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('19c7a003-8d46-5822-b7d2-9708203038e6', '8722c344-58c6-509f-af1d-f5f53688437c', 'A', 'Doxycycline is safe in pregnancy', false, 0),
  ('efcdac11-f535-5f4b-96ac-d2fca970d924', '8722c344-58c6-509f-af1d-f5f53688437c', 'B', 'Take at bedtime lying down', false, 1),
  ('6d8fdc6f-40ea-535d-ba17-59f6f21f67b0', '8722c344-58c6-509f-af1d-f5f53688437c', 'C', 'Take with a full glass of water while sitting or standing, avoid lying down for 30 minutes, and avoid strong sunlight', true, 2),
  ('225d7e0a-36b3-5f18-a9d2-f84bbcf4276a', '8722c344-58c6-509f-af1d-f5f53688437c', 'D', 'Take with milk', false, 3),
  ('327dae7c-a012-520a-bfbf-1114d41491f0', '8722c344-58c6-509f-af1d-f5f53688437c', 'E', 'Take with antacids', false, 4);
